Javascript code:
// Load Sentinel-5P Carbon Monoxide data for October 2024
var dataset = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_CO')
  .filter(ee.Filter.date('2024-10-01', '2024-10-31'))
  .select('CO_column_number_density');

// Define Australia and Indonesia boundaries
var australia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
  .filter(ee.Filter.eq('country_na', 'Australia'));

var indonesia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
  .filter(ee.Filter.eq('country_na', 'Indonesia'));

// Create visualization parameters for Carbon Monoxide
var coVis = {
  min: 0,
  max: 0.05,
  palette: ['black', 'blue', 'purple', 'cyan', 'green', 'yellow', 'red']
};

// Function to calculate mean CO for a specific region
function calculateMeanCO(dataset, region) {
  // Get the mean CO over the time period
  var meanCO = dataset.mean();

  // Calculate the average CO in the region
  var meanRegionalCO = meanCO.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 10000,  // Scale in meters
    maxPixels: 1e12
  });

  return meanRegionalCO;
}

// Calculate the mean CO for both countries
var meanCO_Australia = calculateMeanCO(dataset, australia);
var meanCO_Indonesia = calculateMeanCO(dataset, indonesia);

// Get the CO values
var coValue_Australia = meanCO_Australia.get('CO_column_number_density');
var coValue_Indonesia = meanCO_Indonesia.get('CO_column_number_density');

// Compare the CO values
var difference = ee.Number(coValue_Australia).subtract(coValue_Indonesia);
var percentDifference = difference.divide(coValue_Indonesia).multiply(100);
var australiaHigher = ee.Number(coValue_Australia).gt(coValue_Indonesia);

// Print the results
print('Mean Australia CO (mol/m²):', coValue_Australia);
print('Mean Indonesia CO (mol/m²):', coValue_Indonesia);
print('Absolute Difference (mol/m²):', difference);
print('Percentage Difference (%):', percentDifference);
print('Does Australia show higher carbon monoxide than Indonesia?', australiaHigher);

// Calculate monthly mean CO
var meanCOImg = dataset.mean();

// Add layers to the map
Map.addLayer(meanCOImg.clip(australia), coVis, 'CO Australia Oct 2024');
Map.addLayer(meanCOImg.clip(indonesia), coVis, 'CO Indonesia Oct 2024');

// Add country boundaries
Map.addLayer(australia, {color: 'yellow'}, 'Australia Boundary');
Map.addLayer(indonesia, {color: 'white'}, 'Indonesia Boundary');

// Center the map to show both countries
// Use error margin for the union operation to avoid the error
var australiaBounds = australia.geometry().bounds();
var indonesiaBounds = indonesia.geometry().bounds();
var bothCountries = australiaBounds.union(indonesiaBounds, 1); // 1 meter error margin
Map.centerObject(bothCountries, 4);

// Additional analysis: Regional hotspots
// Create a threshold for high CO levels
var highCO = meanCOImg.gt(0.03); // Threshold for high CO (adjust as needed)

// Find high CO areas in both countries
var highCO_Australia = highCO.clip(australia);
var highCO_Indonesia = highCO.clip(indonesia);

// Calculate area of high CO in each country
var areaHighCO_Australia = highCO_Australia.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: australia,
  scale: 100000,
  maxPixels: 1e12
});

var areaHighCO_Indonesia = highCO_Indonesia.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: indonesia,
  scale: 100000,
  maxPixels: 1e12
});

// Print the high CO area results
print('Area with high CO in Australia (km²):', 
      ee.Number(areaHighCO_Australia.get('CO_column_number_density')).divide(1e6));
print('Area with high CO in Indonesia (km²):', 
      ee.Number(areaHighCO_Indonesia.get('CO_column_number_density')).divide(1e6));

// Additional visualization: Show high CO areas
var highCOVis = {
  palette: ['red']
};
Map.addLayer(highCO_Australia.selfMask(), highCOVis, 'High CO Areas Australia');
Map.addLayer(highCO_Indonesia.selfMask(), highCOVis, 'High CO Areas Indonesia');

// Analyze temporal variation within October 2024
var earlyOct = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_CO')
  .filter(ee.Filter.date('2024-10-01', '2024-10-15'))
  .select('CO_column_number_density')
  .mean();

var lateOct = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_CO')
  .filter(ee.Filter.date('2024-10-16', '2024-10-31'))
  .select('CO_column_number_density')
  .mean();

// Calculate mean CO for early and late October for each country
var earlyOct_Australia = earlyOct.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: australia,
  scale: 10000,
  maxPixels: 1e12
}).get('CO_column_number_density');

var lateOct_Australia = lateOct.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: australia,
  scale: 10000,
  maxPixels: 1e12
}).get('CO_column_number_density');

var earlyOct_Indonesia = earlyOct.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: indonesia,
  scale: 10000,
  maxPixels: 1e12
}).get('CO_column_number_density');

var lateOct_Indonesia = lateOct.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: indonesia,
  scale: 10000,
  maxPixels: 1e12
}).get('CO_column_number_density');

// Print temporal results
print('Early October Australia CO (mol/m²):', earlyOct_Australia);
print('Late October Australia CO (mol/m²):', lateOct_Australia);
print('Early October Indonesia CO (mol/m²):', earlyOct_Indonesia);
print('Late October Indonesia CO (mol/m²):', lateOct_Indonesia);

// Analysis of valley fog coverage in Upper Arrow Lake area
// comparing morning to afternoon on October 22, 2018

// Define the Upper Arrow Lake area in British Columbia, Canada
// var upperArrowLake = ee.Geometry.Rectangle([-118.35, 50.25, -117.75, 50.75]);
var upperArrowLake = ee.Geometry.Rectangle([-119.998, 49.570, -117.370, 50.999]);

// Load MODIS Terra (morning) and Aqua (afternoon) data for October 22, 2018
// Terra typically passes in the morning (~10:30 AM local time)
// Aqua typically passes in the afternoon (~1:30 PM local time)

// Morning data from Terra MODIS
var terraMorning = ee.ImageCollection('MODIS/061/MOD21A1D')
  .filter(ee.Filter.date('2018-10-22', '2018-10-23'))
  .first();

// Afternoon data from Aqua MODIS
var aquaAfternoon = ee.ImageCollection('MODIS/061/MYD21A1D')
  .filter(ee.Filter.date('2018-10-22', '2018-10-23'))
  .first();

// Function to extract cloud flag from QC band (bits 4-5)
function extractCloudFlag(image) {
  var qcBand = image.select('QC');
  // Extract bits 4-5 (cloud flag)
  // Shift right by 4 bits, then mask to keep only 2 bits
  var cloudFlag = qcBand.rightShift(4).bitwiseAnd(3);
  return cloudFlag;
}

// Extract cloud flags
var morningCloudFlag = extractCloudFlag(terraMorning);
var afternoonCloudFlag = extractCloudFlag(aquaAfternoon);

// Create masks for fog detection
// In valley fog analysis, we're looking for low clouds/fog in the morning
// that typically dissipate in the afternoon
// Valley fog would typically be classified as "Cloudy pixel" (value 3) in the cloud flag

// Create masks for fog (cloud flag = 3)
var morningFogMask = morningCloudFlag.eq(3);
var afternoonFogMask = afternoonCloudFlag.eq(3);

// Calculate fog coverage area for morning and afternoon
function calculateFogArea(fogMask, region) {
  var fogArea = fogMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,  // MODIS resolution
    maxPixels: 1e12
  });
  return fogArea.get('QC');  // QC is the band name
}

var morningFogArea = calculateFogArea(morningFogMask, upperArrowLake);
var afternoonFogArea = calculateFogArea(afternoonFogMask, upperArrowLake);

// Calculate the change in fog coverage
var absoluteChange = ee.Number(afternoonFogArea).subtract(morningFogArea);
var percentChange = absoluteChange.divide(morningFogArea).multiply(100);

// Print results
print('Morning Fog Coverage Area (sq m):', morningFogArea);
print('Afternoon Fog Coverage Area (sq m):', afternoonFogArea);
print('Absolute Change in Fog Coverage (sq m):', absoluteChange);
print('Percentage Change in Fog Coverage (%):', percentChange);
print('Did fog coverage decrease from morning to afternoon?', 
      ee.Number(afternoonFogArea).lt(morningFogArea));

// Also calculate the percentage of the Upper Arrow Lake area covered by fog
var totalArea = upperArrowLake.area();
print('Total Upper Arrow Lake Area (sq m):', totalArea);
print('Morning Fog Coverage (% of area):', 
      ee.Number(morningFogArea).divide(totalArea).multiply(100));
print('Afternoon Fog Coverage (% of area):', 
      ee.Number(afternoonFogArea).divide(totalArea).multiply(100));

// Visualization
// Create a visualization of the cloud flag classes for both times
var cloudFlagVis = {
  min: 0,
  max: 3,
  palette: ['green', 'yellow', 'orange', 'white']
};

// Add false color composite for context (using LST and emissivity bands if available)
// If these bands aren't available, we'll use QC bands for visualization
var falseColorVis = {
  bands: ['QC'],
  min: 0,
  max: 255,
  gamma: 1.4
};

// Alternative visualization specifically for fog detection
var fogVis = {
  palette: ['000000', '0000FF']  // Black for no fog, blue for fog
};

// Center map on Upper Arrow Lake
Map.centerObject(upperArrowLake, 7);

// Add base layers
Map.addLayer(terraMorning, falseColorVis, 'Morning MODIS Terra Raw', false);
Map.addLayer(aquaAfternoon, falseColorVis, 'Afternoon MODIS Aqua Raw', false);

// Add cloud flag classification layers
Map.addLayer(morningCloudFlag, cloudFlagVis, 'Morning Cloud Flag', false);
Map.addLayer(afternoonCloudFlag, cloudFlagVis, 'Afternoon Cloud Flag', false);

// Add fog mask layers (the main result)
Map.addLayer(morningFogMask.selfMask(), fogVis, 'Morning Fog Coverage', true);
Map.addLayer(afternoonFogMask.selfMask(), {palette: ['FF0000']}, 'Afternoon Fog Coverage', true);

// Add the Upper Arrow Lake boundary
Map.addLayer(ee.FeatureCollection(upperArrowLake), {color: 'black'}, 'Upper Arrow Lake Area');

// Create a difference layer (fog present in morning but not afternoon)
var fogDissipated = morningFogMask.eq(1).and(afternoonFogMask.eq(0));
Map.addLayer(fogDissipated.selfMask(), {palette: ['yellow']}, 'Fog Dissipated', true);

// Define Southern Siberia region (approximate bounds)
var southernSiberia = ee.Geometry.Rectangle([94.49481025986987, 51.69942865837741, 124.37762275986987, 67.79241448202215]);

// Get MODIS data for both dates
var dataset_Oct14 = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2018-10-14', '2018-10-15'))
  .map(function(img){
    return img.add(-100).multiply(0.0001);
  })
  .filterBounds(southernSiberia);

var dataset_Oct29 = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2018-10-29', '2018-10-30'))
  .map(function(img){
    return img.add(-100).multiply(0.0001);
  })
  .filterBounds(southernSiberia);

// Function to calculate NDSI (Normalized Difference Snow Index)
var calculateNDSI = function(image) {
  var green = image.select('sur_refl_b04'); // Band 4 (Green)
  var swir = image.select('sur_refl_b06'); // Band 6 (SWIR)
  var ndsi = green.subtract(swir).divide(green.add(swir));
  return ndsi.rename('NDSI');
};

// Calculate NDSI for both dates
var ndsi_Oct14 = dataset_Oct14.map(calculateNDSI).mosaic().clip(southernSiberia);
var ndsi_Oct29 = dataset_Oct29.map(calculateNDSI).mosaic().clip(southernSiberia);

// Define NDSI threshold for snow detection
var ndsiThreshold = 0.4;

// Create snow masks
var snowMask_Oct14 = ndsi_Oct14.gte(ndsiThreshold);
var snowMask_Oct29 = ndsi_Oct29.gte(ndsiThreshold);

// Calculate snow area (in pixels)
var snowArea_Oct14 = snowMask_Oct14.reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: southernSiberia,
  scale: 500, // MODIS resolution
  maxPixels: 1e13
}).get('NDSI');

var snowArea_Oct29 = snowMask_Oct29.reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: southernSiberia,
  scale: 500, // MODIS resolution
  maxPixels: 1e13
}).get('NDSI');

// Calculate the total area in km²
var pixelArea = 500 * 500 / 1000000; // area of one pixel in km²

// Convert snow pixels to area in km²
var snowAreaKm2_Oct14 = ee.Number(snowArea_Oct14).multiply(pixelArea);
var snowAreaKm2_Oct29 = ee.Number(snowArea_Oct29).multiply(pixelArea);

// Calculate percentage change
var snowChangePercent = ee.Number(snowAreaKm2_Oct29).subtract(snowAreaKm2_Oct14)
  .divide(snowAreaKm2_Oct14).multiply(100);

// Print snow areas and change
print("Oct 14, 2018 snow area (pixels):", snowArea_Oct14);
print("Oct 29, 2018 snow area (pixels):", snowArea_Oct29);
print("Oct 14, 2018 snow area (km²):", snowAreaKm2_Oct14);
print("Oct 29, 2018 snow area (km²):", snowAreaKm2_Oct29);
print("Change in snow area (%):", snowChangePercent);

// Determine if snow cover increased
var hasIncreased = ee.Number(snowArea_Oct29).gt(snowArea_Oct14);
print("Did snow cover increase?", hasIncreased);

// Visualize RGB image
var trueColorVis = {
  min: 0.0,
  max: 0.3,
  bands: ['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03'], // Red, Green, Blue
};

// Visualize NDSI
var ndsiVis = {
  min: -1,
  max: 1,
  palette: ['blue', 'white', 'green']
};

// Visualize snow mask
var snowMaskVis = {
  min: 0,
  max: 1,
  palette: ['black','white']
};

// Calculate the snow cover difference (positive values indicate increase)
var snowCoverDifference = snowMask_Oct29.subtract(snowMask_Oct14);

// Visualize the difference
var diffVis = {
  min: -1,
  max: 1,
  palette: ['red', 'black', 'blue'] // Decrease, No change, Increase
};

// Add layers to the map
Map.centerObject(southernSiberia, 5);

// Add true color images
var trueColor_Oct14 = dataset_Oct14.mosaic().clip(southernSiberia);
var trueColor_Oct29 = dataset_Oct29.mosaic().clip(southernSiberia);
Map.addLayer(trueColor_Oct14, trueColorVis, 'Oct 14 True Color');
Map.addLayer(trueColor_Oct29, trueColorVis, 'Oct 29 True Color');

// Add NDSI layers
Map.addLayer(ndsi_Oct14, ndsiVis, 'Oct 14 NDSI', false);
Map.addLayer(ndsi_Oct29, ndsiVis, 'Oct 29 NDSI', false);

// Add snow mask layers
Map.addLayer(snowMask_Oct14.updateMask(snowMask_Oct14), snowMaskVis, 'Oct 14 Snow Mask');
Map.addLayer(snowMask_Oct29.updateMask(snowMask_Oct29), snowMaskVis, 'Oct 29 Snow Mask');

// Add the snow cover difference layer
Map.addLayer(snowCoverDifference, diffVis, 'Snow Cover Change (blue = increase)');

// Define China boundary
var countries = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017");
var china = countries.filter(ee.Filter.eq('country_na', 'China'));

// Load MODIS Vegetation Index product (provides better coverage for actual green leaf area)
var modis2000 = ee.ImageCollection("MODIS/006/MOD13A2")
  .filterDate('2000-01-01', '2000-12-31')
  .filterBounds(china);

var modis2017 = ee.ImageCollection("MODIS/006/MOD13A2")
  .filterDate('2017-01-01', '2017-12-31')
  .filterBounds(china);

// Create composites of maximum annual EVI (Enhanced Vegetation Index)
// EVI is better for dense vegetation areas compared to NDVI
var evi2000 = modis2000.select('EVI').max().divide(10000); // Scale factor for MODIS EVI
var evi2017 = modis2017.select('EVI').max().divide(10000);

// Calculate the change in green leaf area
var eviChange = evi2017.subtract(evi2000);

// Load Hansen Global Forest Change dataset for additional context
var hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');
var treeCover2000 = hansen.select('treecover2000');
var forestGain = hansen.select('gain'); // Forest gain 2000-2023
var forestLoss = hansen.select('loss'); // Forest loss 2000-2023

// Calculate area with EVI increase and decrease
var eviIncrease = eviChange.gt(0.05); // Areas with significant EVI increase (threshold: 0.05)
var eviDecrease = eviChange.lt(-0.05); // Areas with significant EVI decrease (threshold: 0.05)

// Calculate areas in square kilometers
var areaImage = ee.Image.pixelArea().divide(1e6); // Convert to square kilometers

// Calculate total area of China
var totalArea = areaImage.reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: china,
  scale: 10000,
  maxPixels: 1e12
});

// Calculate area of EVI increase
var increaseArea = eviIncrease.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: china,
  scale: 1000,
  maxPixels: 1e12
});

// Calculate area of EVI decrease
var decreaseArea = eviDecrease.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: china,
  scale: 10000,
  maxPixels: 1e12
});

// Calculate area with forest gain and loss (Hansen dataset)
var gainArea = forestGain.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: china,
  scale: 3000,
  maxPixels: 1e12
});

var lossArea = forestLoss.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: china,
  scale: 3000,
  maxPixels: 1e12
});

// Calculate mean EVI for both years
var meanEvi2000 = evi2000.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: china,
  scale: 10000,
  maxPixels: 1e12
});

var meanEvi2017 = evi2017.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: china,
  scale: 10000,
  maxPixels: 1e12
});

// Print results
print('Total area of China (sq km):', totalArea);
print('Area with significant green leaf increase (sq km):', increaseArea);
print('Area with significant green leaf decrease (sq km):', decreaseArea);
print('Mean EVI in 2000:', meanEvi2000);
print('Mean EVI in 2017:', meanEvi2017);
print('Forest gain area 2000-2023 (sq km):', gainArea);
print('Forest loss area 2000-2023 (sq km):', lossArea);

// Calculate net change percentage
var totalAreaValue = ee.Number(totalArea.get('area'));
var increaseAreaValue = ee.Number(increaseArea.get('EVI'));
var decreaseAreaValue = ee.Number(decreaseArea.get('EVI'));

var netChangeArea = increaseAreaValue.subtract(decreaseAreaValue);
var netChangePercent = netChangeArea.divide(totalAreaValue).multiply(100);

var meanEvi2000Value = ee.Number(meanEvi2000.get('EVI'));
var meanEvi2017Value = ee.Number(meanEvi2017.get('EVI'));
var eviPercentChange = meanEvi2017Value.subtract(meanEvi2000Value)
  .divide(meanEvi2000Value).multiply(100);

print('Net green leaf area change (sq km):', netChangeArea);
print('Net green leaf area change (% of China):', netChangePercent);
print('Percent change in mean EVI:', eviPercentChange);

// Create a thematic visualization of the EVI change
var changeVisParams = {
  min: -0.2,
  max: 0.2,
  palette: ['red', 'white', 'green']
};

var eviIncreaseDecreaseVis = {
  min: 1,
  max: 2,
  palette: ['red', 'green']
};

// Create a combined image showing increase vs decrease
var increaseDecrease = eviDecrease.multiply(1).add(eviIncrease.multiply(2));

// Visualize the results
Map.centerObject(china, 4);
Map.addLayer(evi2000, {min: 0, max: 0.8, palette: ['white', 'green']}, 'EVI 2000', false);
Map.addLayer(evi2017, {min: 0, max: 0.8, palette: ['white', 'green']}, 'EVI 2017', false);
Map.addLayer(eviChange, changeVisParams, 'EVI Change (2000-2017)');
Map.addLayer(increaseDecrease.selfMask(), eviIncreaseDecreaseVis, 'Significant Increase/Decrease');
Map.addLayer(china, {}, 'China Boundary', false);

// Add a title
var title = ui.Label('Green Leaf Area Change in China (2000-2017)', 
  {fontWeight: 'bold', fontSize: '18px', margin: '10px 5px'});
Map.add(title);

// Add a legend
var legend = ui.Panel({
  style: {
    position: 'bottom-left',
    padding: '8px 15px'
  }
});

var makeRow = function(color, name) {
  var colorBox = ui.Label({
    style: {
      backgroundColor: color,
      padding: '8px',
      margin: '0 0 4px 0'
    }
  });

  var description = ui.Label({
    value: name,
    style: {margin: '0 0 4px 6px'}
  });

  return ui.Panel({
    widgets: [colorBox, description],
    layout: ui.Panel.Layout.Flow('horizontal')
  });
};

var legendTitle = ui.Label({
  value: 'Legend',
  style: {
    fontWeight: 'bold',
    fontSize: '16px',
    margin: '0 0 4px 0',
    padding: '0'
  }
});

legend.add(legendTitle);
legend.add(makeRow('green', 'Significant Increase (>0.05 EVI)'));
legend.add(makeRow('red', 'Significant Decrease (>0.05 EVI)'));
legend.add(makeRow('white', 'Little Change'));

Map.add(legend);

// Create a regional analysis panel
var regions = [
  'Northeast China (Dongbei)',
  'North China Plain',
  'Loess Plateau',
  'Qinghai-Tibet Plateau',
  'Southwest China',
  'Southern China'
];

// Load a finer provinces dataset for regional analysis
var provinces = ee.FeatureCollection("USDOS/LSIB/2017");
var chinaProvinces = provinces.filter(ee.Filter.eq('COUNTRY_NA', 'China'));

// Print the provinces to help with analysis
print('China Provinces:', chinaProvinces);

// Define the location of Lake Menindee, Australia
var menindee = ee.Geometry.Point([142.325654, -32.338791]);

// Create a buffer around Lake Menindee to capture the entire lake system
var buffer = menindee.buffer(8000);  // 30km buffer to include the Menindee Lakes system

// Load Landsat 8 imagery for the two dates
var before = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2017-01-20', '2017-02-05')  // Around January 27, 2017
  .filterBounds(buffer)
  .mosaic();

var after = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2019-01-25', '2019-02-10')  // Around February 2, 2019
  .filterBounds(buffer)
  .mosaic();

// Function to mask clouds using the quality band
function maskL8(image) {
  // Bit 0 - Fill
  // Bit 1 - Dilated Cloud
  // Bit 2 - Cirrus
  // Bit 3 - Cloud
  // Bit 4 - Cloud Shadow
  var qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
  var saturationMask = image.select('QA_RADSAT').eq(0);

  // Apply the scaling factors to the appropriate bands
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);

  // Replace the original bands with the scaled ones and apply the masks
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true)
    .updateMask(qaMask)
    .updateMask(saturationMask);
}

// Apply cloud mask
var beforeCloudMasked = maskL8(before);
var afterCloudMasked = maskL8(after);

// Calculate NDWI (Normalized Difference Water Index) for water detection
// Using Green (B3) and NIR (B5) bands
var ndwiBefore = beforeCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
var ndwiAfter = afterCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

// Apply threshold to identify water (NDWI > 0.1 typically indicates water)
var waterBefore = ndwiBefore.gt(0.1);
var waterAfter = ndwiAfter.gt(0.1);

// Calculate water area for both dates
var areaBefore = waterBefore.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: buffer,
  scale: 30,
  maxPixels: 1e13  // Increased max pixels for larger area
});

var areaAfter = waterAfter.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: buffer,
  scale: 30,
  maxPixels: 1e13
});

// Print the water area in square kilometers
print('Water area in January 2017 (sq km):', ee.Number(areaBefore.get('NDWI')).divide(1e6));
print('Water area in February 2019 (sq km):', ee.Number(areaAfter.get('NDWI')).divide(1e6));

// Calculate and print the percentage change in water area
var areaBeforeValue = ee.Number(areaBefore.get('NDWI')).divide(1e6);
