// Load MODIS Land Surface Temperature dataset
var modisLST = ee.ImageCollection("MODIS/006/MOD11A2");

// Define the target period (February 11-25, 2019)
var targetStartDate = ee.Date('2019-02-11');
var targetEndDate = ee.Date('2019-02-25');

// Define the historical reference period (2000-2012)
var startYear = 2000;
var endYear = 2012;

// Select land surface temperature band
var lstBand = 'LST_Day_1km';

// Function to convert MODIS LST to Celsius
var convertToCelsius = function(image) {
  var lst = image.select(lstBand);
  // MODIS LST is stored as Kelvin * 0.02, so multiply by 0.02 to get Kelvin
  // then subtract 273.15 to convert to Celsius
  var lstCelsius = lst.multiply(0.02).subtract(273.15);
  return image.addBands(lstCelsius.rename('LST_Celsius'), null, true);
};

// Get LST data for February 11-25, 2019
var lst2019 = modisLST
  .filter(ee.Filter.date(targetStartDate, targetEndDate))
  .map(convertToCelsius)
  .select('LST_Celsius')
  .mean();

// Function to get February 11-25 data for a given year
var getFebData = function(year) {
  var startDate = ee.Date.fromYMD(year, 2, 11);
  var endDate = ee.Date.fromYMD(year, 2, 25);
  return modisLST
    .filter(ee.Filter.date(startDate, endDate))
    .map(convertToCelsius)
    .select('LST_Celsius')
    .mean()
    .set('year', year);
};

// Create a list of years for the reference period
var years = ee.List.sequence(startYear, endYear);

// Get February 11-25 LST data for each year in the reference period
var historicalCollection = ee.ImageCollection.fromImages(
  years.map(function(year) {
    return getFebData(year);
  })
);

// Calculate the historical average for February 11-25
var historicalAverage = historicalCollection.mean();

// Calculate the anomaly (difference from historical average)
var lstAnomaly = lst2019.subtract(historicalAverage);

// Define visualization parameters
var lstVis = {
  min: -5,
  max: 15,
  palette: ['blue', 'purple', 'cyan', 'green', 'yellow', 'red']
};

var anomalyVis = {
