// Calculate MNDWI for both datasets
function calculateMNDWI(image) {
  // MNDWI = (Green - SWIR) / (Green + SWIR)
  // For Landsat 8, Green is B3 and SWIR1 is B6
  var green = image.select('SR_B3');
  var swir1 = image.select('SR_B6');
  var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
  return image.addBands(mndwi);
}

// Apply MNDWI calculation to both datasets
var dataset_2018_with_mndwi = dataset_2018.map(calculateMNDWI);
var dataset_2019_with_mndwi = dataset_2019.map(calculateMNDWI);

// Create a binary water mask where MNDWI > 0
function createWaterMask(image) {
  var waterMask = image.select('MNDWI').gt(0);
  return waterMask.rename('water_mask');
}

