// Define the area of interest: Madre de Dios region in Peru
var madreDeDios = geometry; // Approximate bounds for Madre de Dios

// Load Hansen Global Forest Change dataset (2023 version)
var dataset = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

// Get various bands from the dataset
var treeCover = dataset.select(['treecover2000']); // Tree cover in 2000
var loss = dataset.select(['loss']); // Forest loss 2000-2023
var lossYear = dataset.select(['lossyear']); // Year of loss
var gain = dataset.select(['gain']); // Forest gain 2000-2023

// Load Sentinel-2 imagery for RGB visualization
var sentinel2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filter(ee.Filter.date('2019-01-01', '2019-12-31'))
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 10))
  .median();

// Create a mask for areas that had forest in 2000 (with at least 30% tree cover)
var forestMask = treeCover.gte(30);

// Apply the mask to the loss year data
var lossYearMasked = lossYear.updateMask(forestMask);

// Calculate total forest area in 2000 (baseline)
var forestArea2000 = forestMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: madreDeDios,
  scale: 300,
  maxPixels: 1e13,
});

// Calculate forest loss up to 2013 (to get forest cover in 2013)
var lossUntil2013 = lossYear.lte(13).and(forestMask);
var forestLossUntil2013 = lossUntil2013.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: madreDeDios,
  scale: 300,
  maxPixels: 1e13,
});

// Calculate forest loss up to 2018 (to get forest cover in 2018)
var lossUntil2018 = lossYear.lte(18).and(forestMask);
var forestLossUntil2018 = lossUntil2018.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: madreDeDios,
  scale: 300,
  maxPixels: 1e13,
});

// Calculate specifically the loss between 2013 and 2018
var loss2013to2018 = lossYear.gt(13).and(lossYear.lte(18)).and(forestMask);
var forestLoss2013to2018 = loss2013to2018.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: madreDeDios,
  scale: 300,
  maxPixels: 1e13,
});

// Convert to square kilometers
var forestAreaSqKm = ee.Number(forestArea2000.get('treecover2000')).divide(1e6);
var forestLossUntil2013SqKm = ee.Number(forestLossUntil2013.get('lossyear')).divide(1e6);
var forestLossUntil2018SqKm = ee.Number(forestLossUntil2018.get('lossyear')).divide(1e6);
var forestLoss2013to2018SqKm = ee.Number(forestLoss2013to2018.get('lossyear')).divide(1e6);

// Calculate forest cover in 2013 and 2018
var forestCover2013 = forestAreaSqKm.subtract(forestLossUntil2013SqKm);
var forestCover2018 = forestAreaSqKm.subtract(forestLossUntil2018SqKm);

// Calculate percentage decrease from 2013 to 2018
var percentDecrease = forestLoss2013to2018SqKm.divide(forestCover2013).multiply(100);

// Print results
print('Total forest area in 2000 (sq km):', forestAreaSqKm);
print('Forest cover in 2013 (sq km):', forestCover2013);
print('Forest cover in 2018 (sq km):', forestCover2018);
print('Forest loss between 2013 and 2018 (sq km):', forestLoss2013to2018SqKm);
print('Percentage decrease from 2013 to 2018 (%):', percentDecrease);

// Determine if forest cover decreased from 2013 to 2018
var hasDecreased = forestCover2018.lt(forestCover2013);
print('Did forest cover decrease from 2013 to 2018?', hasDecreased);

// Calculate annual forest loss between 2013 and 2018
var annualLoss = {};
for (var year = 14; year <= 18; year++) {
  var yearLoss = lossYear.eq(year).and(forestMask);
  var yearLossArea = yearLoss.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: madreDeDios,
    scale: 300,
    maxPixels: 1e13,
  });
  var yearLossSqKm = ee.Number(yearLossArea.get('lossyear')).divide(1e6);
  annualLoss['20' + (year + 2000)] = yearLossSqKm;
}

