// Function to get April data for a given year (all layers)
var getAprilData = function(year) {
  var startDate = ee.Date.fromYMD(year, 4, 1);
  var endDate = startDate.advance(1, 'month');
  return era5Land
    .filter(ee.Filter.date(startDate, endDate))
    .select(soilLayers)
    .median()
    .set('year', year);
};

// Create a list of years for the reference period
