// Function to add a layer with a checkbox
var addLayerWithCheckbox = function(image, visParams, name) {
  var checkbox = ui.Checkbox({
    label: name,
    value: false,
    onChange: function(checked) {
      if (checked) {
        Map.addLayer(image.clip(somalia), visParams, name);
      } else {
        // Find and remove the layer
        Map.layers().forEach(function(layer) {
          if (layer.getName() === name) {
            Map.remove(layer);
          }
        });
      }
    }
  });
  panel.add(checkbox);
};

