    hAxis: {title: 'Month', gridlines: {count: 12}},
    vAxis: {title: 'Number of Fire Hotspots'},
    legend: {position: 'top'},
    series: {
      0: {color: 'blue'},
      1: {color: 'red'}
    }
  });

print(chart);

