// Function to calculate NDSI
var calculateNDSI = function(image) {
  var green = image.select('sur_refl_b04'); // Band 4 (Green)
  var swir = image.select('sur_refl_b06');  // Band 6 (SWIR)
  var ndsi = green.subtract(swir).divide(green.add(swir));
  return ndsi.rename('NDSI');
};

