// Analysis to determine if location is more likely a solar farm than a water pond
// Location: 34.770153, -118.423217 with 300m radius
// Date: April 14, 2020
// Using Landsat imagery

// Define the point of interest and buffer area (300m radius)
var point = ee.Geometry.Point([-118.423217, 34.770153]);
var area = point.buffer(300);

// Load Landsat 8 collection
var landsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2020-04-14', '2020-04-15')  // Specific date requested
  .filterBounds(area);

// Print the collection to check available images
print('Available Landsat images:', landsat);

// Get the first image (if available)
var image = landsat.first();

// Function to scale the surface reflectance bands
function scaleImage(image) {
  // Select the surface reflectance bands
  var opticalBands = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'])
    .multiply(0.0000275).add(-0.2);  // Scale factor for Collection 2

  // Select thermal bands
  var thermalBand = image.select(['ST_B10'])
    .multiply(0.00341802).add(149.0);  // Scale factor for Collection 2

  return image.addBands(opticalBands, null, true)
              .addBands(thermalBand, null, true);
}

// Scale the image if available
if (image) {
  image = scaleImage(image);
}

// Calculate indices useful for distinguishing water and solar panels
function calculateIndices(image) {
  // NDWI (Normalized Difference Water Index)
  var ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

  // NDVI (Normalized Difference Vegetation Index)
  var ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

  // Add brightness and specular reflection measures (helpful for solar panels)
  var brightness = image.select(['SR_B4', 'SR_B5', 'SR_B6']).reduce(ee.Reducer.sum()).rename('brightness');

  // Calculate standard deviation of reflectance (solar panels often have high variation)
  var stdDev = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'])
                    .reduce(ee.Reducer.stdDev()).rename('stdDev');

  return image.addBands([ndwi, ndvi, brightness, stdDev]);
}

// Calculate indices if image is available
if (image) {
  image = calculateIndices(image);

  // Sample the region to get statistics
  var stats = image.select(['NDWI', 'NDVI', 'brightness', 'stdDev', 'ST_B10']).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: area,
    scale: 30,
    maxPixels: 1e9
  });

  print('Region statistics:', stats);

  // Criteria for classification:
  // 1. Solar farms typically have:
  //    - Low NDWI (not water)
  //    - Low NDVI (little vegetation)
  //    - High brightness (reflective)
  //    - High standard deviation (panel structure creates variation)
  //    - Potentially higher surface temperature than water

  // 2. Water ponds typically have:
  //    - High NDWI (water presence)
  //    - Low NDVI (unless algae/vegetation present)
  //    - Low brightness (absorbs light)
  //    - Low standard deviation (uniform surface)
  //    - Lower surface temperature (thermal inertia of water)

  // Evaluate the criteria
  var ndwiValue = ee.Number(stats.get('NDWI'));
  var ndviValue = ee.Number(stats.get('NDVI'));
  var brightnessValue = ee.Number(stats.get('brightness'));
  var stdDevValue = ee.Number(stats.get('stdDev'));
  var temperatureValue = ee.Number(stats.get('ST_B10'));

  // Visualization for the map
  Map.centerObject(area, 15);
  Map.addLayer(image, {bands: ['SR_B4', 'SR_B3', 'SR_B2'], min: 0, max: 0.3}, 'True Color');
  Map.addLayer(image, {bands: ['SR_B5', 'SR_B4', 'SR_B3'], min: 0, max: 0.3}, 'False Color');
  Map.addLayer(image.select('NDWI'), {min: -1, max: 1, palette: ['red', 'white', 'blue']}, 'NDWI');
  Map.addLayer(image.select('brightness'), {min: 0, max: 1, palette: ['black', 'white']}, 'Brightness');
  Map.addLayer(image.select('stdDev'), {min: 0, max: 0.1, palette: ['black', 'white']}, 'Standard Deviation');
  Map.addLayer(area, {color: 'yellow'}, 'Area of Interest');

  // Evaluation logic:
  // Higher probability of being solar farm if:
  // - NDWI is negative (not water)
  // - Brightness is high
  // - Standard deviation is relatively high
  // - Temperature is higher than typical water

  // Simple decision based on NDWI and brightness
  var isSolarFarmProbability = ee.Algorithms.If(
    ndwiValue.lt(0).and(brightnessValue.gt(0.5).or(stdDevValue.gt(0.03))),
    'High probability of being a solar farm',
    ee.Algorithms.If(
      ndwiValue.gt(0.1),
      'High probability of being a water pond',
      'Inconclusive, but more likely a solar farm than water pond'
    )
  );

  print('Classification result:', isSolarFarmProbability);

  // Export a feature with the results
  var resultFeature = ee.Feature(area, {
    'NDWI': ndwiValue,
    'NDVI': ndviValue,
    'Brightness': brightnessValue,
    'StdDev': stdDevValue,
    'Temperature': temperatureValue,
    'Classification': isSolarFarmProbability
  });

  // Export a more detailed view for analysis
  Map.addLayer(image.normalizedDifference(['SR_B2', 'SR_B4']), 
              {min: -0.5, max: 0.5, palette: ['brown', 'yellow', 'green']}, 
              'B2-B4 Difference (helpful for solar panels)', false);
} else {
  print('No Landsat 8 image available for the specified date and location.');
  print('Consider expanding the date range or switching to another satellite (e.g., Sentinel-2).');

  // Try with a date range if no direct match
  var landsatRange = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate('2020-04-01', '2020-04-30')  // Expanded range to April 2020
    .filterBounds(area);

  print('Available Landsat images in April 2020:', landsatRange);
}

// Additional helper analysis: historical NDWI pattern
