  .map(function(img) {
    var scaled = scaleImage(img);
    var ndwi = scaled.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    return scaled.addBands(ndwi).set('date', img.date().format('YYYY-MM-dd'));
  });

print('Historical images count:', timeSeriesCollection.size());

