// Calculate total forest area in 2000
var forestArea2000 = forestMask2000
  .multiply(ee.Image.pixelArea())
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: saltaProvince,
    scale: 30,
    maxPixels: 1e13
  });

// Calculate forest loss from 2000 to 2019
var forestLossUntil2019 = lossYear.lte(19).and(forestMask2000);
var forestLossArea2000to2019 = forestLossUntil2019
  .multiply(ee.Image.pixelArea())
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: saltaProvince,
    scale: 30,
    maxPixels: 1e13
  });

// Convert areas to square kilometers
var forestArea2000SqKm = ee.Number(forestArea2000.get('treecover2000')).divide(1e6);
var forestLossAreaSqKm = ee.Number(forestLossArea2000to2019.get('lossyear')).divide(1e6);

// Calculate remaining forest area in 2019
var forestArea2019 = forestArea2000SqKm.subtract(forestLossAreaSqKm);

// Calculate percentage of forest loss
var percentForestLoss = forestLossAreaSqKm.divide(forestArea2000SqKm).multiply(100);

// Determine if forest cover decreased
var hasDecreased = forestLossAreaSqKm.gt(0);

