var image_2020 = modis_2020.median();

// Function to calculate MNDWI (Modified Normalized Difference Water Index)
// MNDWI = (Green - SWIR) / (Green + SWIR)
// For MODIS, Green is band 4 (sur_refl_b04) and SWIR is band 6 (sur_refl_b06)
function calculateMNDWI(image) {
  var green = image.select('sur_refl_b04');
  var swir = image.select('sur_refl_b06');
  var mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
  return image.addBands(mndwi);
}

// Apply MNDWI calculation to images
var image_2019_with_mndwi = calculateMNDWI(image_2019);
var image_2020_with_mndwi = calculateMNDWI(image_2020);

// Create water masks (MNDWI > 0 typically indicates water)
function createWaterMask(image) {
  var waterMask = image.select('MNDWI').gt(0);
  return waterMask.rename('water_mask');
}

var waterMask_2019 = createWaterMask(image_2019_with_mndwi);
var waterMask_2020 = createWaterMask(image_2020_with_mndwi);

