// Function to calculate NDVI
var calculateNDVI = function(image) {
  var nir = image.select('sur_refl_b02'); // Band 2 (NIR)
  var red = image.select('sur_refl_b01'); // Band 1 (Red)
  var ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');
  return ndvi;
};

// Calculate NDVI and create a mosaic
