// Create a better land mask to exclude sea while preserving all land pixels
// Using the MOD44W land/water mask product
var waterMask = ee.Image('MODIS/MOD44W/MOD44W_005_2000_02_24').select('water_mask');
var landMask = waterMask.eq(0); // 0 = land, 1 = water

