// Function to calculate NDSI from MOD09GA.
function calculateNDSI(image) {
  var green = image.select('sur_refl_b04'); // Band 4 (Green)
  var swir = image.select('sur_refl_b06'); // Band 6 (SWIR)

  var ndsi = green.subtract(swir).divide(green.add(swir)).rename('NDSI');
  return image.addBands(ndsi);
}

// Load and filter MOD09GA for February.
