  .filterDate(dateFeb, dateFeb.advance(1, 'day'))
  .map(function(img){return img.add(-100).multiply(0.0001)}) // Scale the reflectance values.
  .map(calculateNDSI)
  .filterBounds(greatLakesROI); // Filter to the Great Lakes region.

// Load and filter MOD09GA for March.
var datasetMarch = ee.ImageCollection('MODIS/061/MOD09GA')
  .filterDate(dateMarch, dateMarch.advance(1, 'day'))
  .map(function(img){return img.add(-100).multiply(0.0001)}) // Scale the reflectance values.
  .map(calculateNDSI)
  .filterBounds(greatLakesROI); // Filter to the Great Lakes region.

