// Define the area of interest: Banamepe along the Digul River in Papua
var banamepe = ee.Geometry.Point([139.755433, -7.371745]).buffer(10000); // 10km buffer around Banamepe

// Load Hansen Global Forest Change dataset (2023 version)
var dataset = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

// Get various bands from the dataset
var treeCover = dataset.select(['treecover2000']); // Tree cover in 2000
var loss = dataset.select(['loss']); // Forest loss 2000-2023
var lossYear = dataset.select(['lossyear']); // Year of loss
var gain = dataset.select(['gain']); // Forest gain 2000-2023

// Create a mask for areas that had forest in 2000 (with at least 30% tree cover)
var forestMask = treeCover.gte(30);

// Apply the mask to the loss year data
var lossYearMasked = lossYear.updateMask(forestMask);

// Filter loss to only include 2002-2019 period
var lossStart = lossYear.gte(2).and(forestMask); // 2002 (Hansen data starts at year 2000, so 2 = 2002)
var lossEnd = lossYear.lte(19).and(forestMask); // 2019 (19 = 2019)
var lossPeriod = lossStart.and(lossEnd);

// Calculate total forest area in 2000 (baseline)
var forestArea2000 = forestMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: banamepe,
  scale: 30,
  maxPixels: 1e13,
});

// Calculate forest loss by year
var forestLossArea = lossPeriod.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: banamepe,
  scale: 30,
  maxPixels: 1e13,
});

// Calculate forest loss in different time periods
var loss2002to2010 = lossYear.gte(2).and(lossYear.lte(10)).and(forestMask);
var loss2011to2019 = lossYear.gte(11).and(lossYear.lte(19)).and(forestMask);

var loss2002to2010Area = loss2002to2010.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: banamepe,
  scale: 30,
  maxPixels: 1e13,
});

var loss2011to2019Area = loss2011to2019.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: banamepe,
  scale: 30,
  maxPixels: 1e13,
});

// Calculate percent forest loss
var forestAreaSqKm = ee.Number(forestArea2000.get('treecover2000')).divide(1e6);
var forestLossAreaSqKm = ee.Number(forestLossArea.get('lossyear')).divide(1e6);
var loss2002to2010AreaSqKm = ee.Number(loss2002to2010Area.get('lossyear')).divide(1e6);
var loss2011to2019AreaSqKm = ee.Number(loss2011to2019Area.get('lossyear')).divide(1e6);

var percentLoss = forestLossAreaSqKm.divide(forestAreaSqKm).multiply(100);

// Count the number of pixels lost in each year
var lossYearHistogram = lossYearMasked.reduceRegion({
  reducer: ee.Reducer.frequencyHistogram(),
  geometry: banamepe,
  scale: 30,
  maxPixels: 1e13,
});

// Create a feature collection to visualize annual loss
var createAnnualLossFeatures = function() {
  // Get the histogram dictionary from the server
  var lossYearDict = ee.Dictionary(lossYearHistogram.get('lossyear'));

  // Get the keys as years and values as pixel counts
  var years = lossYearDict.keys();
  var counts = lossYearDict.values();

  // Create a list of features with year and count properties
  var features = ee.List.sequence(0, ee.Number(years.length()).subtract(1)).map(function(i) {
    var year = ee.Number.parse(ee.String(years.get(i)));
    var count = ee.Number(counts.get(i));
    var actualYear = year.add(2000); // Convert to actual year (Hansen data starts at 2000)

    return ee.Feature(null, {
      'year': actualYear,
      'count': count,
      'area_ha': count.multiply(900).divide(10000) // Convert 30m pixels to hectares
    });
  });

  return ee.FeatureCollection(features);
};

var annualLossFeatures = createAnnualLossFeatures();

