// Function to mask clouds using the quality band
function maskL8(image) {
  // Bit 0 - Fill
  // Bit 1 - Dilated Cloud
  // Bit 2 - Cirrus
  // Bit 3 - Cloud
  // Bit 4 - Cloud Shadow
  var qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
  var saturationMask = image.select('QA_RADSAT').eq(0);

  // Apply the scaling factors to the appropriate bands
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);

  // Replace the original bands with the scaled ones and apply the masks
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true)
    .updateMask(qaMask)
    .updateMask(saturationMask);
}

// Apply cloud mask
var beforeCloudMasked = maskL8(before);
var afterCloudMasked = maskL8(after);

// Calculate NDWI (Normalized Difference Water Index) for water detection
// Using Green (B3) and NIR (B5) bands
var ndwiBefore = beforeCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
var ndwiAfter = afterCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

// Apply threshold to identify water (NDWI > 0.1 typically indicates water)
var waterBefore = ndwiBefore.gt(0.1);
var waterAfter = ndwiAfter.gt(0.1);

