print('Water area in February 2021 (sq km):', ee.Number(areaAfter.get('NDWI')).divide(1e6));

// Calculate and print the percentage change in water area
var areaBeforeValue = ee.Number(areaBefore.get('NDWI')).divide(1e6);
var areaAfterValue = ee.Number(areaAfter.get('NDWI')).divide(1e6);
var areaDifference = areaAfterValue.subtract(areaBeforeValue);
var percentChange = areaDifference.divide(areaBeforeValue).multiply(100);

print('Absolute difference (sq km):', areaDifference);
print('Percentage change (%):', percentChange);

// Add a condition to explicitly answer the question
print('Does Lake Menindee shrink from February 2019 to May, 2021?',
      ee.Algorithms.If(areaDifference.lt(0), 'Yes, Lake Menindee has shrunk', 'No, Lake Menindee has not shrunk'));

