// Helper function to get Landsat 5 data for our date with a wider window
// Using Landsat 5 since it was operational in 1987
function getLandsatForDate(date) {
  var startDate = date.advance(-15, 'day');  // Allow wider window to ensure data
  var endDate = date.advance(15, 'day');

  return ee.ImageCollection("LANDSAT/LT05/C02/T1_L2")
    .filterDate(startDate, endDate)
    .filterBounds(ee.Geometry.MultiPoint([
      [dorsoidongPoint.coordinates().get(0), dorsoidongPoint.coordinates().get(1)],
      [chibzhangPoint.coordinates().get(0), chibzhangPoint.coordinates().get(1)]
    ]))
    .sort('system:time_start')
    .first();  // Get the closest image to our target date
}

// Get Landsat data for the target date
var landsatImage = getLandsatForDate(targetDate);

// Add a print statement to check if we have data
print('Landsat Scene Date:', landsatImage.date());

// Function to calculate lighter blue color
function calculateBlueIntensity(image) {
  // For Landsat 5, Blue is band 1 (B)
  // Need to apply scaling factors for surface reflectance product
  var blue = image.select('SR_B1').multiply(0.0000275).add(-0.2);
  var green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
  var red = image.select('SR_B3').multiply(0.0000275).add(-0.2);

  // Calculate blue intensity (normalized by total RGB intensity)
  // Higher values indicate relatively more blueness
  var blueIntensity = blue.divide(blue.add(green).add(red)).rename('blue_intensity');

  // Calculate lightness of blue (higher values = lighter blue)
  // We use the blue reflectance directly as a measure of lightness
  // Higher reflectance in blue band = lighter blue appearance
  var blueLightness = blue.rename('blue_lightness');

  return image.addBands([blueIntensity, blueLightness]);
}

// Create a water mask using NDWI (Normalized Difference Water Index)
function getWaterMask(image) {
  var green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
  var nir = image.select('SR_B4').multiply(0.0000275).add(-0.2);

  // Calculate NDWI = (Green - NIR) / (Green + NIR)
  var ndwi = green.subtract(nir).divide(green.add(nir));

  // Use a threshold to identify water (NDWI > 0.3)
  var waterMask = ndwi.gt(0.3);
  return waterMask;
}

// Get water mask
var waterMask = getWaterMask(landsatImage);

