var blueIntensity = calculateBlueIntensity(landsatImage);

// Apply water mask to blue intensity and lightness
var processedImage = calculateBlueIntensity(landsatImage);
var blueIntensityWater = processedImage.select('blue_intensity').updateMask(waterMask);
var blueLightnessWater = processedImage.select('blue_lightness').updateMask(waterMask);

// Function to calculate statistics for each lake region
function calculateStats(image, region, name) {
  var stats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.stdDev(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 30,  // Landsat resolution
    maxPixels: 1e12
  });
  print(name + ' Statistics:', stats);
  return stats;
}

