var dorsoidongLightnessStats = calculateStats(blueLightnessWater, dorsoidongBoundary, 'Dorsoidong Co Lake - Lightness');
var chibzhangLightnessStats = calculateStats(blueLightnessWater, chibzhangBoundary, 'Chibzhang Co Lake - Lightness');

