// Function to apply scaling factors for Landsat 8
function applyScaleFactorsL8(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Function to apply scaling factors for Landsat 5
function applyScaleFactorsL5(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Apply scaling factors
dataset_2016 = dataset_2016.map(applyScaleFactorsL8);
dataset_1988 = dataset_1988.map(applyScaleFactorsL5);

// Calculate MNDWI for Landsat 8 (2016)
function calculateMNDWI_L8(image) {
  // MNDWI = (Green - SWIR) / (Green + SWIR)
  // For Landsat 8, Green is B3 and SWIR1 is B6
  var green = image.select('SR_B3');
  var swir1 = image.select('SR_B6');
  var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
  return image.addBands(mndwi);
}

// Calculate MNDWI for Landsat 5 (1988)
function calculateMNDWI_L5(image) {
  // For Landsat 5, Green is B2 and SWIR1 is B5
  var green = image.select('SR_B2');
  var swir1 = image.select('SR_B5');
  var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
  return image.addBands(mndwi);
}

// Apply MNDWI calculation to both datasets
var dataset_2016_with_mndwi = dataset_2016.map(calculateMNDWI_L8);
var dataset_1988_with_mndwi = dataset_1988.map(calculateMNDWI_L5);

// Create a binary water mask where MNDWI > 0
function createWaterMask(image) {
  var waterMask = image.select('MNDWI').gt(0);
  return waterMask.rename('water_mask');
}

// Get the median image from each collection for analysis
var image_2016 = dataset_2016_with_mndwi.median();
var image_1988 = dataset_1988_with_mndwi.median();

// Create water masks
var waterMask_2016 = createWaterMask(image_2016);
var waterMask_1988 = createWaterMask(image_1988);

// Calculate the area of water within the region
// Scale is set to 30 meters (Landsat resolution)
var area_2016 = waterMask_2016.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: geometry,
  scale: 30,
  maxPixels: 1e12
});

var area_1988 = waterMask_1988.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: geometry,
  scale: 30,
  maxPixels: 1e12
});

// Get area in square meters
var waterArea_2016 = area_2016.get('water_mask');
var waterArea_1988 = area_1988.get('water_mask');

// Convert to square kilometers for easier interpretation
var waterAreaSqKm_2016 = ee.Number(waterArea_2016).divide(1e6);
var waterAreaSqKm_1988 = ee.Number(waterArea_1988).divide(1e6);

// Calculate the change in water area between 1988 and 2016
var waterAreaChange = waterAreaSqKm_2016.subtract(waterAreaSqKm_1988);
var percentChange = waterAreaSqKm_2016.subtract(waterAreaSqKm_1988).divide(waterAreaSqKm_1988).multiply(100);

// Print results
print('Water Area 1988 (sq km):', waterAreaSqKm_1988);
print('Water Area 2016 (sq km):', waterAreaSqKm_2016);
print('Change in Water Area 1988-2016 (sq km):', waterAreaChange);
print('Percent Change in Water Area 1988-2016 (%):', percentChange);

