  .filter(ee.Filter.eq('ADM1_NAME', 'Santa Cruz de Tenerife'));

// Define time periods for comparison
var before_start = '2021-05-15';
var before_end = '2021-05-25';  // Centered around May 21, 2021
var after_start = '2021-12-10';
var after_end = '2021-12-20';   // Centered around December 15, 2021

// Load Landsat 8 collections for both time periods
var landsat_before = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterBounds(geometry)
  .filterDate(before_start, before_end);

var landsat_after = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterBounds(geometry)
  .filterDate(after_start, after_end);

// Print collection sizes to verify data availability
print('Number of images before:', landsat_before.size());
print('Number of images after:', landsat_after.size());

// Function to apply scale factors to convert to reflectance
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
              .addBands(thermalBands, null, true);
}

// Apply scale factors to both collections
var landsat_before_scaled = landsat_before.map(applyScaleFactors);
var landsat_after_scaled = landsat_after.map(applyScaleFactors);

// Create median composites for both periods
var before_img = landsat_before_scaled.median();
var after_img = landsat_after_scaled.median();

// RGB visualization parameters
var rgbVis = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0.0,
  max: 0.25,
};

// Define a specialized visualization for lava flows (highlighting hot areas)
var lavaVis = {
  bands: ['SR_B7', 'SR_B5', 'SR_B4'],  // SWIR2, NIR, Red
  min: 0.0,
  max: 0.3,
};

// Function to detect lava using spectral indices
function detectLava(image) {
  // Calculate Normalized Burn Ratio (NBR)
  // NBR = (NIR - SWIR) / (NIR + SWIR)
  // For Landsat 8: NIR is B5, SWIR is B7
  var nir = image.select('SR_B5');
  var swir2 = image.select('SR_B7');
  var nbr = nir.subtract(swir2).divide(nir.add(swir2)).rename('NBR');

  // Calculate thermal anomalies using thermal band
  var thermal = image.select('ST_B10');
  var hotSpots = thermal.gt(320);  // Threshold for hot areas in Kelvin

  // Combine indices: lower NBR indicates burnt/lava areas
  var lavaIndex = nbr.lt(-0.1);  // Threshold for lava

  return lavaIndex.rename('lava_mask');
}

// Create lava masks for both dates
var lava_before = detectLava(before_img);
var lava_after = detectLava(after_img);

// Calculate new lava flows (after - before)
var new_lava = lava_after.and(lava_before.not());

// Calculate area of lava flows
var area_before = lava_before.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: geometry,
  scale: 30,
  maxPixels: 1e9
});

var area_after = lava_after.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: geometry,
  scale: 30,
  maxPixels: 1e9
});

var area_new = new_lava.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: geometry,
  scale: 30,
  maxPixels: 1e9
});

// Convert to square kilometers
var lavaAreaBefore = ee.Number(area_before.get('lava_mask')).divide(1e6);
var lavaAreaAfter = ee.Number(area_after.get('lava_mask')).divide(1e6);
var newLavaArea = ee.Number(area_new.get('lava_mask')).divide(1e6);

// Print results
print('Lava area in May 2021 (sq km):', lavaAreaBefore);
print('Lava area in December 2021 (sq km):', lavaAreaAfter);
print('New lava area (sq km):', newLavaArea);
print('Percentage increase:', lavaAreaAfter.subtract(lavaAreaBefore).divide(lavaAreaBefore).multiply(100));

// Center map on area of interest
Map.centerObject(geometry, 12);

// Add layers to map
Map.addLayer(laPalmaIsland, {color: 'gray'}, 'La Palma Island');
Map.addLayer(before_img, rgbVis, 'RGB Before (May 2021)', false);
Map.addLayer(after_img, rgbVis, 'RGB After (December 2021)');
Map.addLayer(before_img, lavaVis, 'SWIR Composite Before (May 2021)', false);
Map.addLayer(after_img, lavaVis, 'SWIR Composite After (December 2021)', false);
Map.addLayer(lava_before, {palette: ['black', 'yellow']}, 'Lava Extent Before (May 2021)');
Map.addLayer(lava_after, {palette: ['black', 'red']}, 'Lava Extent After (December 2021)');
Map.addLayer(new_lava, {palette: ['black', 'orange']}, 'New Lava Flows');
Map.addLayer(geometry, {color: 'blue', fillColor: '00000000'}, 'Study Area');

// Create a visualization to highlight changes
var changeVis = {
  bands: ['SR_B7', 'SR_B5', 'SR_B4'],
  min: 0.0,
  max: 0.25,
};

// Add a threshold-based visualization to better highlight changes
var lavaChange = after_img.select('ST_B10').subtract(before_img.select('ST_B10'));
Map.addLayer(lavaChange, {min: 0, max: 50, palette: ['black', 'yellow', 'orange', 'red']}, 'Thermal Change');

// Assess the impact of the eruption by calculating NDVI change
function calculateNDVI(image) {
  return image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
}

var ndvi_before = calculateNDVI(before_img);
var ndvi_after = calculateNDVI(after_img);
var ndvi_change = ndvi_after.subtract(ndvi_before);

Map.addLayer(ndvi_before, {min: -0.2, max: 0.8, palette: ['brown', 'white', 'green']}, 'NDVI Before', false);
Map.addLayer(ndvi_after, {min: -0.2, max: 0.8, palette: ['brown', 'white', 'green']}, 'NDVI After', false);
Map.addLayer(ndvi_change, {min: -0.5, max: 0.5, palette: ['red', 'white', 'blue']}, 'NDVI Change', false);

// Add a title to the map
var title = ui.Label('La Palma Lava Flow Analysis (May-December 2021)', {
  fontSize: '18px',
  fontWeight: 'bold',
  position: 'top-center'
});
Map.add(title);

// Final assessment text
if (lavaAreaAfter.subtract(lavaAreaBefore).gt(0)) {
  print('CONCLUSION: Lava-covered area increased between May and December 2021');
} else {
  print('CONCLUSION: No significant increase in lava-covered area');
}

