print('Total Rainfall (Oct-Nov 2021) in mm:', meanRainfall_2021.get('precipitation'));

// --- Baseline Period: October-November from 2000-2013 ---

// Define the baseline years.
var startYear = 2000;
var endYear = 2013;
var years = ee.List.sequence(startYear, endYear);

// Function to calculate total rainfall for Oct-Nov for a given year.
var yearlyRainfall = function(year) {
  var startDate = ee.Date.fromYMD(year, 10, 1);
  var endDate = ee.Date.fromYMD(year, 11, 30);
  var total = chirps
      .filterDate(startDate, endDate)
      .filterBounds(southernEthiopia)
      .sum();
  return total;
};

// Map the function over the baseline years to get a collection of total rainfall images.
var yearlyTotals = ee.ImageCollection.fromImages(
  years.map(yearlyRainfall)
);

// Calculate the mean of the yearly total rainfall images.
var longTermAverage = yearlyTotals.mean();

// Calculate the mean long-term average rainfall within the Southern Ethiopia region.
var meanLongTermAverage = longTermAverage.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: southernEthiopia,
  scale: 5566,
  maxPixels: 1e9
});

print('Long-Term Average Rainfall (Oct-Nov, 2000-2013) in mm:', meanLongTermAverage.get('precipitation'));

