// Load the CHIRPS Daily precipitation dataset.
var chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

// --- Define Time Periods ---
var anomalyStartDate = '2021-10-01';
var anomalyEndDate = '2021-11-30';
var baselineStartYear = 2000;
var baselineEndYear = 2013;

// --- Function to Calculate and Print Rainfall Anomaly ---
var calculateRainfallAnomaly = function(region, regionName) {
  // 1. Calculate Total Rainfall for Oct-Nov 2021
  var rainfall2021 = chirps
      .filter(ee.Filter.date(anomalyStartDate, anomalyEndDate))
      .sum();

  var meanRainfall2021 = rainfall2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000, // Scale in meters for the reducer
    maxPixels: 1e9
  }).get('precipitation');

  // 2. Calculate Long-Term Average for Oct-Nov (2000-2013)
  var baselineYears = ee.List.sequence(baselineStartYear, baselineEndYear);

  var yearlyTotals = ee.ImageCollection.fromImages(
    baselineYears.map(function(year) {
      var startDate = ee.Date.fromYMD(year, 10, 1);
      var endDate = ee.Date.fromYMD(year, 11, 30);
      return chirps
          .filter(ee.Filter.date(startDate, endDate))
          .sum()
          .set('year', year);
    })
  );

  var longTermAverage = yearlyTotals.mean();

  var meanLongTermAverage = longTermAverage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // 3. Calculate the Anomaly (2021 rainfall - long-term average)
  var anomaly = ee.Number(meanRainfall2021).subtract(ee.Number(meanLongTermAverage));
  var anomalyPercentage = anomaly.divide(ee.Number(meanLongTermAverage)).multiply(100);


  // Print the results for the region
  print('--- Results for ' + regionName + ' ---');
  print('Total Rainfall (Oct-Nov 2021) in mm:', meanRainfall2021);
  print('Long-Term Average (2000-2013) in mm:', meanLongTermAverage);
  print('Rainfall Anomaly (2021 vs Average) in mm:', anomaly);
  print('Rainfall Anomaly as % of Average:', anomalyPercentage);
};

