// Function to detect light-blue water areas
function detectLightBlueWater(image) {
  // Extract blue, green, and red bands
  var blue = image.select('SR_B2');
  var green = image.select('SR_B3');
  var red = image.select('SR_B4');

  // Light blue water typically has higher blue reflectance than green and red
  var blueHigherThanGreen = blue.gt(green);
  var blueHigherThanRed = blue.gt(red);

  // Blue reflectance in the moderate range for light blue water
  var blueModerateBrightness = blue.gte(0.07).and(blue.lte(0.18));

  // Combine conditions to detect light blue water
  var lightBlueWater = blueHigherThanGreen
    .and(blueHigherThanRed)
    .and(blueModerateBrightness);

  return lightBlueWater;
}

