// Function to create a mask for corn, wheat, and soybeans
function getCropMask(image) {
  // Create masks for each crop type
  var cornMask = image.eq(1).or(image.eq(12)).or(image.eq(13));  // Corn, sweet corn, pop corn
  var wheatMask = image.eq(22).or(image.eq(23)).or(image.eq(24));  // Durum, spring, winter wheat
  var soybeanMask = image.eq(5);  // Soybeans

  // Combine into a single crop mask
  var cropMask = cornMask.or(wheatMask).or(soybeanMask);

  // Add individual crop type bands
  var cornArea = cornMask.selfMask().rename('corn');
  var wheatArea = wheatMask.selfMask().rename('wheat');
  var soybeanArea = soybeanMask.selfMask().rename('soybean');

  return ee.Image(cropMask.selfMask())
    .addBands(cornArea)
    .addBands(wheatArea)
    .addBands(soybeanArea);
}

// Function to calculate crop area in square kilometers
function calculateCropArea(image, geometry) {
  var pixelArea = ee.Image.pixelArea();

  // Calculate total area for all target crops combined
  var totalArea = pixelArea.updateMask(image.select(0))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e12
    });

  // Calculate area for each crop type
  var cornArea = pixelArea.updateMask(image.select('corn'))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e12
    });

  var wheatArea = pixelArea.updateMask(image.select('wheat'))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e12
    });

  var soybeanArea = pixelArea.updateMask(image.select('soybean'))
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e12
    });

  // Convert to square kilometers
  var totalAreaSqKm = ee.Number(totalArea.get('area')).divide(1e6);
  var cornAreaSqKm = ee.Number(cornArea.get('area')).divide(1e6);
  var wheatAreaSqKm = ee.Number(wheatArea.get('area')).divide(1e6);
  var soybeanAreaSqKm = ee.Number(soybeanArea.get('area')).divide(1e6);

  return {
    totalSqKm: totalAreaSqKm,
    cornSqKm: cornAreaSqKm,
    wheatSqKm: wheatAreaSqKm,
    soybeanSqKm: soybeanAreaSqKm
  };
}

