// Function to calculate cropland area from MODIS Land Cover Type dataset
function getCroplandArea(year) {
  // Load MODIS Land Cover Type Yearly Global 500m dataset
  // Land cover classification scheme used: IGBP (International Geosphere-Biosphere Programme)
  // Class 12 = Croplands
  // Class 14 = Cropland/Natural Vegetation Mosaics
  var modisLandCover = ee.Image('MODIS/061/MCD12Q1/' + year + '_01_01')
    .select('LC_Type1');

  // Create a mask for cropland (class 12) and cropland/natural vegetation mosaics (class 14)
  var croplandMask = modisLandCover.eq(12).or(modisLandCover.eq(14));

  // Calculate area in square kilometers
  var area = croplandMask.multiply(ee.Image.pixelArea()).divide(1e6).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: brazil,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  });

  return ee.Number(area.get('LC_Type1'));
}

// Calculate cropland area for 2003 and 2019
var croplandArea2003 = getCroplandArea('2003');
var croplandArea2019 = getCroplandArea('2019');

// Calculate change in cropland area
var areaChange = croplandArea2019.subtract(croplandArea2003);
var percentChange = areaChange.divide(croplandArea2003).multiply(100);

// Determine if cropland area increased
var hasIncreased = croplandArea2019.gt(croplandArea2003);

// Let's also create a year-by-year analysis to see the trend
var years = ee.List.sequence(2003, 2019);
var yearlyAreas = years.map(function(year) {
  var area = getCroplandArea(ee.Number(year).format());
  return ee.Feature(null, {
    'year': year,
    'cropland_area_km2': area
  });
});

