// Function to calculate mean surface reflectance over water
function calculateMeanReflectance(dataset) {
  // Get the mean reflectance over the time period
  var meanReflectance = dataset.mean();

  // Apply the water mask
  var waterReflectance = meanReflectance.updateMask(waterMask);

  // Calculate the mean value within the Black Sea region
  var regionalMean = waterReflectance.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blackSea,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  });

  return regionalMean;
}

// Calculate the mean reflectance for both dates
var mean_may = calculateMeanReflectance(reflectance_may);
var mean_june = calculateMeanReflectance(reflectance_june);

// Calculate changes in reflectance
var red_may = mean_may.get('sur_refl_b01');
var red_june = mean_june.get('sur_refl_b01');
var nir_may = mean_may.get('sur_refl_b02');
var nir_june = mean_june.get('sur_refl_b02');

// Calculate the percentage change
var redChange = ee.Number(red_june).subtract(red_may).divide(red_may).multiply(100);
var nirChange = ee.Number(nir_june).subtract(nir_may).divide(nir_may).multiply(100);

// Calculate average brightness (mean of red and NIR bands)
var brightness_may = ee.Number(red_may).add(nir_may).divide(2);
var brightness_june = ee.Number(red_june).add(nir_june).divide(2);
var brightnessChange = ee.Number(brightness_june).subtract(brightness_may).divide(brightness_may).multiply(100);

// Print the results
print('Mean Surface Reflectance May 20, 2022 (Red band):', red_may);
print('Mean Surface Reflectance June 20, 2022 (Red band):', red_june);
print('Percentage Change in Red band (%):', redChange);

print('Mean Surface Reflectance May 20, 2022 (NIR band):', nir_may);
print('Mean Surface Reflectance June 20, 2022 (NIR band):', nir_june);
print('Percentage Change in NIR band (%):', nirChange);

print('Average Brightness May 20, 2022:', brightness_may);
print('Average Brightness June 20, 2022:', brightness_june);
print('Percentage Change in Average Brightness (%):', brightnessChange);
print('Did surface brightness increase in June?', ee.Number(brightness_june).gt(brightness_may));

