// Function to scale and prepare Sentinel-2 imagery
function prepSentinel(image) {
  // Select the visible and NIR bands
  // B2 (blue), B3 (green), B4 (red), B8 (NIR)
  var opticalBands = image.select(['B2', 'B3', 'B4', 'B8']);

  // Scale the pixel values (Sentinel-2 uses scale factor of 10000)
  var scaled = opticalBands.divide(10000);

  // Create cloud mask from SCL band (Scene Classification)
  var scl = image.select('SCL');
  var cloudMask = scl.neq(9).and(scl.neq(8)).and(scl.neq(7)).and(scl.neq(3)).and(scl.neq(10));

  // Apply the cloud mask
  scaled = scaled.updateMask(cloudMask);

  return scaled;
}

// Map the function over the collections
