var processed_2022 = sentinel_2022.map(prepSentinel);

// Create composites for both periods
var composite_2021 = processed_2021.median();
var composite_2022 = processed_2022.median();

// Function to detect coccolithophore blooms
// Adapted for Sentinel-2 bands
function detectCoccolithophores(image) {
  // Calculate blue-to-green ratio (higher in coccolithophore blooms)
  var blueGreenRatio = image.select('B2').divide(image.select('B3'));

  // Calculate overall reflectance in blue band (coccolithophores have high reflectance)
  var blueReflectance = image.select('B2');

  // Combine metrics to create a "coccolithophore index"
  var coccoIndex = blueGreenRatio.multiply(blueReflectance);

  // Add normalized difference between blue and green bands
  // This can help distinguish coccolithophores from other water types
  var ndbi = image.normalizedDifference(['B2', 'B3']).rename('ndbi');

  return coccoIndex.rename('cocco_index').addBands(ndbi);
}

