// Function to rescale the surface reflectance
function prepSrL8(image) {
  // Landsat 8 Collection 2 Level 2 surface reflectance data needs scaling
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Apply the scaling function
var landsatScaled = prepSrL8(landsat);

// Function to calculate turbidity index using Landsat 8 bands
// For Landsat 8, we'll use Red (SR_B4) and Green (SR_B3)
function calculateTurbidityIndex(image) {
  // Select Red and Green bands
  var red = image.select('SR_B4');
  var green = image.select('SR_B3');

  // Calculate NDTI (Normalized Difference Turbidity Index)
  // NDTI = (Red - Green) / (Red + Green)
  var ndti = red.subtract(green).divide(red.add(green)).rename('ndti');

  return ndti;
}

// Calculate NDTI for the image
var ndti = calculateTurbidityIndex(landsatScaled);

// Function to calculate statistics for a region
function calculateStats(image, region, name) {
  var stats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.stdDev(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 30, // Landsat 8 resolution
    maxPixels: 1e12
  });

  print(name + ' Statistics:', stats);
  return stats;
}

// Calculate statistics for both lakes
