print('Lake Abijata Mean NDTI:', abijataNDTIMean);
print('NDTI Difference (Langano - Abijata):', langanoNDTIMean.subtract(abijataNDTIMean));
print('Is Lake Langano more turbid than Lake Abijata?', langanoNDTIMean.gt(abijataNDTIMean));

// Additional analysis: Calculate another turbidity metric - Red/Blue ratio
// Higher values indicate higher turbidity
function calculateRedBlueRatio(image) {
  var red = image.select('SR_B4');
  var blue = image.select('SR_B2');

  var redBlueRatio = red.divide(blue).rename('rb_ratio');
  return redBlueRatio;
}

