// Function to mask clouds in Sentinel-2 imagery
function maskS2clouds(image) {
  var qa = image.select('QA60');

  // Bits 10 and 11 are clouds and cirrus, respectively
  var cloudBitMask = 1 << 10;
  var cirrusBitMask = 1 << 11;

  // Both flags should be set to zero, indicating clear conditions
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

  return image.updateMask(mask).divide(10000);
}

// Function to calculate NDVI
function calculateNDVI(image) {
  return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
}

// Identify agricultural land using Dynamic World V1 probabilities
var dynamicWorld = ee.ImageCollection('GOOGLE/DYNAMICWORLD/V1')
  .filterBounds(peoria)
  .filterDate('2022-09-01', '2022-10-31');

// Create probability-based mask using Dynamic World probabilities
var dwProbComposite = dynamicWorld.select('crops').median();
var agricMask = dwProbComposite.gt(0.5); // Areas with >50% probability of being crops

// Load Sentinel-2 Surface Reflectance data for September and October 2022
var sentinel2_Sept = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterBounds(peoria)
  .filterDate('2022-09-01', '2022-09-30')
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter less cloudy images
  .select('B2', 'B3', 'B4', 'B8', 'B11', 'B12', 'QA60')
  .map(maskS2clouds);

var sentinel2_Oct = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
  .filterBounds(peoria)
  .filterDate('2022-10-01', '2022-10-31')
  .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter less cloudy images
  .select('B2', 'B3', 'B4', 'B8', 'B11', 'B12', 'QA60')
  .map(maskS2clouds);

// Create median composites for each month
