var ndvi_Oct = calculateNDVI(composite_Oct);

// Calculate NDVI difference (Oct - Sept)
var ndviDifference = ndvi_Oct.subtract(ndvi_Sept);

// Use NDVI decrease as indicator of browning (harvest or senescence)
var browningMask = ndviDifference.lt(0);

// Apply agricultural mask to focus only on cropland
