// Function to get the March-September rainfall for a specific year
var getMarchSeptemberRainfall = function(year) {
  var startDate = ee.Date.fromYMD(year, 3, 1);
  var endDate = ee.Date.fromYMD(year, 9, 30);

  return chirps
    .filterDate(startDate, endDate)
    .sum();
};

// Get rainfall for March-September for each year in the baseline period
var years = ee.List.sequence(1981, 2021);
var baselineRainfallCollection = years.map(function(year) {
  var rainfall = getMarchSeptemberRainfall(year);
  return rainfall.set('year', year);
});

// Convert the list to an image collection
var baselineRainfallImgCol = ee.ImageCollection.fromImages(baselineRainfallCollection);

// Calculate the long-term average (1981-2021) for March-September
var baselineAvgRainfall = baselineRainfallImgCol.mean();

// Calculate anomaly (difference from long-term average)
var rainfallAnomaly = targetTotalRainfall.subtract(baselineAvgRainfall);

// Calculate percent change
var percentChange = rainfallAnomaly.divide(baselineAvgRainfall).multiply(100);

