  scale: 50000,
  maxPixels: 1e9
});

var anomalyStats = rainfallAnomaly.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: somalia,
  scale: 50000,
  maxPixels: 1e9
});

var percentChangeStats = percentChange.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: somalia,
  scale: 50000,
  maxPixels: 1e9
});

