  .filter(ee.Filter.date('2024-01-15', '2024-01-16'))
  .first();

// Function to extract cloud flag from QC band (bits 4-5)
function extractCloudFlag(image) {
  var qcBand = image.select('QC');
  // Extract bits 4-5 (cloud flag)
  // Shift right by 4 bits, then mask to keep only 2 bits
  var cloudFlag = qcBand.rightShift(4).bitwiseAnd(3);
  return cloudFlag;
}

// Extract cloud flags
var morningCloudFlag = extractCloudFlag(terraMorning);
var afternoonCloudFlag = extractCloudFlag(aquaAfternoon);

// Create masks for cloud detection (cloud flag = 3 indicates cloudy pixels)
var morningCloudMask = morningCloudFlag.eq(3);
var afternoonCloudMask = afternoonCloudFlag.eq(3);

// Calculate cloud coverage area for morning and afternoon
function calculateCloudArea(cloudMask, region) {
  var cloudArea = cloudMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region.geometry(),
    scale: 1000,  // MODIS resolution
    maxPixels: 1e12
  });
  return cloudArea.get('QC');  // QC is the band name
}

var morningCloudArea = calculateCloudArea(morningCloudMask, delhi);
var afternoonCloudArea = calculateCloudArea(afternoonCloudMask, delhi);

// Calculate the total area of Delhi
var totalArea = delhi.geometry().area();

// Calculate percentage of Delhi covered by clouds
var morningCloudPercentage = ee.Number(morningCloudArea).divide(totalArea).multiply(100);
var afternoonCloudPercentage = ee.Number(afternoonCloudArea).divide(totalArea).multiply(100);

