// Function to scale surface temperature
function scaleTemp(image) {
  // Surface temperature band is ST_B10, needs scaling
  // For Landsat Collection 2: multiply by 0.00341802 and add 149.0
  // Convert from Kelvin to Celsius by subtracting 273.15
  var st = image.select('B10')
               .subtract(273.15).rename('surface_temp_celsius');
  return image.addBands(st);
}

// Apply temperature scaling
var landsatWithTemp = landsat.map(scaleTemp);

// Get the first image (assuming there's at least one for this date)
var image = landsatWithTemp.first();

// Calculate mean temperature for each region
