  reducer: ee.Reducer.mean(),
  geometry: grindavikRegion,
  scale: 30 // Landsat resolution
});

var northTemp = image.select('surface_temp_celsius').reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: northRegion,
  scale: 30
});

// Get the temperature values
var grindavikTempValue = grindavikTemp.get('surface_temp_celsius');
var northTempValue = northTemp.get('surface_temp_celsius');

// Calculate the temperature difference
var tempDifference = ee.Number(northTempValue).subtract(grindavikTempValue);

// Check if the northern region is warmer
