// Function to apply scale factors for surface reflectance bands
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Function to mask clouds using the QA_PIXEL band
function maskClouds(image) {
  // Get the QA band
  var qa = image.select('QA_PIXEL');

  // Bit positions: 1 = dilated cloud, 3 = cloud, 4 = cloud shadow
  var cloudBitMask = 1 << 1 | 1 << 3;
  var shadowBitMask = 1 << 4;

  // Mask out clouds and shadows
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
             .and(qa.bitwiseAnd(shadowBitMask).eq(0));

  return image.updateMask(mask);
}

// Apply scale factors and cloud masking
dataset_1984 = dataset_1984.map(applyScaleFactors).map(maskClouds);
dataset_2022 = dataset_2022.map(applyScaleFactors).map(maskClouds);

