// Function to calculate mean precipitation for a specific dataset over a region
function calculateMeanPrecipitation(dataset, region) {
  // Get the mean precipitation over the month
  var meanPrecip = dataset.mean();

  // Calculate the average precipitation in the region in mm/day
  var meanRegionalPrecip = meanPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e12
  });

  return meanRegionalPrecip.get('precipitation');
}

// Calculate the monthly total precipitation by summing daily values
var totalPrecip_2023 = precipitation_2023.sum();
var totalPrecip_2024 = precipitation_2024.sum();

// Calculate the mean precipitation for both years
var meanDailyPrecip_2023 = calculateMeanPrecipitation(precipitation_2023, zimbabwe);
var meanDailyPrecip_2024 = calculateMeanPrecipitation(precipitation_2024, zimbabwe);

// Calculate the total February precipitation for both years (mean daily * number of days)
var totalPrecip_2023_mm = ee.Number(meanDailyPrecip_2023).multiply(28); // 28 days in Feb 2023
var totalPrecip_2024_mm = ee.Number(meanDailyPrecip_2024).multiply(29); // 29 days in Feb 2024 (leap year)

// Calculate the absolute and percentage change
var absoluteChange = ee.Number(totalPrecip_2024_mm).subtract(totalPrecip_2023_mm);
var percentChange = absoluteChange.divide(totalPrecip_2023_mm).multiply(100);

// For fair comparison (adjusting for different number of days), calculate daily average
var dailyAvg_2023 = ee.Number(totalPrecip_2023_mm).divide(28);
var dailyAvg_2024 = ee.Number(totalPrecip_2024_mm).divide(29);
var dailyAvgChange = ee.Number(dailyAvg_2024).subtract(dailyAvg_2023);
var dailyAvgPercentChange = dailyAvgChange.divide(dailyAvg_2023).multiply(100);

// Print the results
