print('Mean Daily Precipitation in Zimbabwe - February 2024 (mm/day):', meanDailyPrecip_2024);
print('Total Precipitation in Zimbabwe - February 2023 (mm):', totalPrecip_2023_mm);
print('Total Precipitation in Zimbabwe - February 2024 (mm):', totalPrecip_2024_mm);
print('Absolute Change in Total Precipitation (mm):', absoluteChange);
print('Percentage Change in Total Precipitation (%):', percentChange);
print('Did rainfall decrease in February 2024?', ee.Number(totalPrecip_2024_mm).lt(totalPrecip_2023_mm));

// Account for different number of days in month
print('Daily Average - February 2023 (mm/day):', dailyAvg_2023);
print('Daily Average - February 2024 (mm/day):', dailyAvg_2024);
print('Absolute Change in Daily Average (mm/day):', dailyAvgChange);
