// Function to apply scale factors for Landsat 7
function applyScaleFactorsL7(image) {
  var opticalBands = image.select('SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7')
      .multiply(0.0000275)
      .add(-0.2);

  // var thermalBand = image.select('ST_B6')
  //     .multiply(0.00341802)
  //     .add(149);

  return image.addBands(opticalBands, null, true);
              // .addBands(thermalBand, null, true);
}

// Function to apply scale factors for Landsat 8
function applyScaleFactorsL8(image) {
  var opticalBands = image.select('SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7')
      .multiply(0.0000275)
      .add(-0.2);

  // var thermalBands = image.select('ST_B10', 'ST_B11')
  //     .multiply(0.00341802)
  //     .add(149);

  return image.addBands(opticalBands, null, true);
              // .addBands(thermalBands, null, true);
}

// Function to mask clouds using the QA band for Landsat 7
function maskCloudsL7(image) {
  var qa = image.select('QA_PIXEL');

  // Bits 3 and 5 are cloud and cloud shadow
  var cloudBitMask = 1 << 3;
  var cloudShadowBitMask = 1 << 5;

  // Both flags should be set to zero, indicating clear conditions
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));

  return image.updateMask(mask);
}

// Function to mask clouds using the QA band for Landsat 8
function maskCloudsL8(image) {
  var qa = image.select('QA_PIXEL');

  // Bits 3 and 5 are cloud and cloud shadow
  var cloudBitMask = 1 << 3;
  var cloudShadowBitMask = 1 << 5;

  // Both flags should be set to zero, indicating clear conditions
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudShadowBitMask).eq(0));

  return image.updateMask(mask);
}

