// Define the point of interest and buffer to create a 1km radius area
var point = ee.Geometry.Point([-79.887682, -2.306934]);
var areaOfInterest = point.buffer(1000); // 1000 meters = 1km radius

// Load Landsat 8 Collection 2 Level-2 data
var dataset = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2024-08-29', '2024-08-30')  // Specific date requested
  .filterBounds(areaOfInterest);

// Function to scale the surface reflectance bands
function prepSrL8(image) {
  // Scale the surface reflectance bands (0-65535 to 0-1)
  var opticalBands = image.select('SR_B[1-7]').multiply(0.0000275).add(-0.2);

  // Return the scaled image with selected bands
  return image.addBands(opticalBands, null, true);
}

// Map the function over the image collection
var processedCol = dataset.map(prepSrL8);

// Get the first image (assuming there's at least one image for the date)
var image = processedCol.first();

// Select the bands useful for distinguishing aquaculture from vegetation
// B2 (blue), B3 (green), B4 (red), B5 (NIR), B6 (SWIR1)
var selectedBands = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6']);

// Calculate indices useful for distinguishing shrimp farms and mangroves
// NDVI (Normalized Difference Vegetation Index) - higher in mangroves, lower in water/aquaculture
var ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

// NDWI (Normalized Difference Water Index) - higher in water bodies (like shrimp ponds)
var ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

// MNDWI (Modified NDWI) - better for distinguishing built-up areas from water
var mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');

// Add the indices to the image
var imageWithIndices = image.addBands([ndvi, ndwi, mndwi]);

// Create a classifier to distinguish between shrimp farms and mangroves
// Thresholds based on typical spectral characteristics
var shrimpFarmMask = ndwi.gt(0.2).and(ndvi.lt(0.0));
var mangroveMask = ndvi.gt(0.2).and(ndwi.lt(0.0));

// Calculate areas of each land cover type within the area of interest
var shrimpFarmArea = ee.Image.pixelArea().updateMask(shrimpFarmMask)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: 30, // Landsat 8 resolution
    maxPixels: 1e9
  });

var mangroveArea = ee.Image.pixelArea().updateMask(mangroveMask)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: 30,
    maxPixels: 1e9
  });

// Calculate the percentage of each class
var totalArea = ee.Number(areaOfInterest.area());
var shrimpFarmPercentage = ee.Number(shrimpFarmArea.get('area')).divide(totalArea).multiply(100);
var mangrovePercentage = ee.Number(mangroveArea.get('area')).divide(totalArea).multiply(100);

// Print results
print('Area of Interest (square meters):', totalArea);
print('Shrimp Farm Area (square meters):', shrimpFarmArea.get('area'));
print('Mangrove Area (square meters):', mangroveArea.get('area'));
print('Percentage of Shrimp Farm (%):', shrimpFarmPercentage);
print('Percentage of Mangrove (%):', mangrovePercentage);
print('Is location more likely to be a shrimp farm than mangrove?', 
      ee.Number(shrimpFarmArea.get('area')).gt(mangroveArea.get('area')));

// Visualization parameters
var ndviParams = {min: -0.5, max: 0.9, palette: ['blue', 'white', 'green']};
var ndwiParams = {min: -0.5, max: 0.5, palette: ['red', 'white', 'blue']};
var landCoverVis = {
  min: 0,
  max: 2,
  palette: ['blue', 'green']
};

// Create a land cover classification image (1=shrimp farm, 2=mangrove)
var landCover = shrimpFarmMask.multiply(1).add(mangroveMask.multiply(2));

// Display true color image
var trueColorVis = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0,
  max: 0.3,
};

// Display false color image highlighting vegetation
