// Add layers to the map
Map.addLayer(image, trueColorVis, 'True Color (August 29, 2024)');
Map.addLayer(image, falseColorVis, 'False Color (NIR)', false);
Map.addLayer(imageWithIndices.select('NDVI'), ndviParams, 'NDVI', false);
Map.addLayer(imageWithIndices.select('NDWI'), ndwiParams, 'NDWI', false);
Map.addLayer(landCover, landCoverVis, 'Land Cover (Blue=Shrimp, Green=Mangrove)');
Map.addLayer(areaOfInterest, {color: 'red'}, 'Area of Interest (1km radius)');
Map.addLayer(point, {color: 'yellow'}, 'Point of Interest');

// Define the region of interest (ROI) for Sebkha el Melah
var roi = ee.Geometry.Polygon(
        [[[-1.4176855405389066, 29.35517021085667],
          [-1.4176855405389066, 29.07169730409028],
          [-1.123114617687344, 29.07169730409028],
          [-1.123114617687344, 29.35517021085667]]], null, false);

// Function to calculate NDWI (Normalized Difference Water Index) for MODIS
function addNDWI_MODIS(image) {
  // For MODIS, use band 4 (green, 545nm) and band 6 (SWIR, 1640nm)
  var ndwi = image.normalizedDifference(['sur_refl_b04', 'sur_refl_b06']).rename('NDWI');
  return image.addBands(ndwi);
}

// Function to calculate water area
function calculateWaterArea(image, threshold) {
  var waterMask = image.select('NDWI').gt(threshold);
  var pixelArea = ee.Image.pixelArea();
  var waterArea = pixelArea.updateMask(waterMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 500, // MODIS resolution
    maxPixels: 1e9
  });

  var waterAreaSqMeters = waterArea.get('area');
  var waterAreaSqKm = ee.Number(waterAreaSqMeters).divide(1e6);

  return {
    sqMeters: waterAreaSqMeters,
    sqKm: waterAreaSqKm,
    mask: waterMask
  };
}

