// Function to apply scale factors to Landsat 8/9 SR imagery
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBand = image.select('ST_B.*').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
              .addBands(thermalBand, null, true);
}

// Function to calculate NDWI for Landsat 8/9
function addNDWI(image) {
  // NDWI = Green - NIR / Green + NIR
  // For Landsat 8/9: Green is B3, NIR is B5
  var ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
  return image.addBands(ndwi);
}

// Function to calculate Modified NDWI (MNDWI) for better water detection
function addMNDWI(image) {
  // MNDWI = Green - SWIR / Green + SWIR
  // For Landsat 8/9: Green is B3, SWIR is B6
  var mndwi = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
  return image.addBands(mndwi);
}

// Function to create land mask (potential islands)
function createLandMask(image) {
  // Use MNDWI for better water/land separation
  // Values < 0 are likely land
  var landMask = image.select('MNDWI').lt(0);
  return landMask.rename('land_mask');
}

// Function to calculate area of land within ROI
function calculateLandArea(landMask, resolution) {
  var pixelArea = ee.Image.pixelArea();
  var landArea = pixelArea.updateMask(landMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: resolution,
    maxPixels: 1e9
  });

  var landAreaSqMeters = landArea.get('area');
  var landAreaSqKm = ee.Number(landAreaSqMeters).divide(1e6);

  return {
    sqMeters: landAreaSqMeters,
    sqKm: landAreaSqKm,
    mask: landMask
  };
}

