// Function to scale the surface reflectance data
function applyScaleFactors(image) {
  // Scale surface reflectance bands
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBand = image.select('ST_B10').multiply(0.00341802).add(149.0);

  // Get the QA_PIXEL band for cloud and other masks
  var qaBand = image.select('QA_PIXEL');

  return image.addBands(opticalBands, null, true)
              .addBands(thermalBand, null, true)
              .addBands(qaBand);
}

// Apply scale factors
var scaledImage = applyScaleFactors(image);

// Use QA_PIXEL to detect clouds, shadows, and potential aerosols
// Bit values for QA_PIXEL: https://www.usgs.gov/landsat-missions/landsat-collection-2-quality-assessment-bands
var qaPixel = scaledImage.select('QA_PIXEL');

// Extract specific bits from QA_PIXEL that could indicate plumes
// Bit 1: Dilated Cloud
// Bit 3: Cirrus
// Bit 4: Cloud
var dilatedCloud = bitwiseExtract(qaPixel, 1);
var cirrus = bitwiseExtract(qaPixel, 3);
var cloud = bitwiseExtract(qaPixel, 4);

// Create a combined mask of potential plume indicators
var potentialPlume = dilatedCloud.or(cirrus).or(cloud);

// Function to extract specific bits from a bitmask
function bitwiseExtract(image, bitPosition) {
  var bitMask = ee.Number(1).leftShift(bitPosition);
  return image.bitwiseAnd(bitMask).rightShift(bitPosition);
}

// Create false color composite to visualize the plume
// Using bands that help visualize aerosols and volcanic plumes
// B1 (Ultra Blue), B3 (Green), B5 (NIR)
