// Calculate the mean value of potential plume indicators in each quadrant
var northMean = potentialPlume.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: north,
  scale: 30,
  maxPixels: 1e9
}).get('QA_PIXEL');

var eastMean = potentialPlume.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: east,
  scale: 30,
  maxPixels: 1e9
}).get('QA_PIXEL');

var southMean = potentialPlume.reduceRegion({
