  geometry: west,
  scale: 30,
  maxPixels: 1e9
}).get('QA_PIXEL');

// Print results
print('North Quadrant Mean Plume Indicator:', northMean);
print('East Quadrant Mean Plume Indicator:', eastMean);
print('South Quadrant Mean Plume Indicator:', southMean);
print('West Quadrant Mean Plume Indicator:', westMean);

// Create a dictionary of the means for comparison
var quadrantMeans = ee.Dictionary({
  'North': northMean,
  'East': eastMean,
  'South': southMean,
  'West': westMean
});

// Find the direction with the highest plume indicator value
var highestDirection = quadrantMeans.keys().sort(quadrantMeans.values()).get(-1);
print('Direction with highest plume concentration:', highestDirection);

// Check if the south direction has the highest plume indicator
var isSouthHighest = ee.Algorithms.If(
  ee.String(highestDirection).equals('South'),
