// Function to calculate total precipitation for a specific dataset over a region
function calculateTotalPrecipitation(dataset, region, regionName) {
  // Sum the precipitation over the time period
  var totalPrecip = dataset.sum();

  // Calculate the total precipitation in the region in mm
  var totalRegionalPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e12
  });

  return ee.Dictionary({
    'region': regionName,
    'total_precipitation': totalRegionalPrecip.get('precipitation')
  });
}

