// Using Collection 2 Level 2 surface reflectance data
var landsat = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
  .merge(ee.ImageCollection("LANDSAT/LC09/C02/T1_L2")) // Include Landsat 9 to increase data availability
  .filterDate(startDate, endDate)
