  .sort('CLOUD_COVER')
  .sort('system:time_start', false) // Sort by date, most recent first
  .mosaic(); // Take the most recent, least cloudy image

// Function to rescale the surface reflectance
function prepSrL8(image) {
  // Landsat 8/9 Collection 2 Level 2 surface reflectance data needs scaling
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Apply the scaling function
var landsatScaled = prepSrL8(landsat);

// Define functions for water detection
// 1. Modified Normalized Difference Water Index (MNDWI)
function calculateMNDWI(image) {
  var green = image.select('SR_B3');
  var swir1 = image.select('SR_B6');
  var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('mndwi');
  return mndwi;
}

// 2. Normalized Difference Water Index (NDWI)
function calculateNDWI(image) {
  var green = image.select('SR_B3');
  var nir = image.select('SR_B5');
  var ndwi = green.subtract(nir).divide(green.add(nir)).rename('ndwi');
  return ndwi;
}

// Calculate water indices
var mndwi = calculateMNDWI(landsatScaled);
var ndwi = calculateNDWI(landsatScaled);

// Create a water mask using both indices
var waterMask = mndwi.gt(0.2) // 0.2 threshold for MNDWI
  .or(ndwi.gt(0.2));  // 0.2 threshold for NDWI

// Clean up the water mask with morphological operations to reduce noise
var waterMaskCleaned = waterMask
  .focalMin(1).focalMax(1)  // Remove isolated pixels
  .selfMask();  // Mask out non-water areas

// Convert the water mask to vectors (polygons)
var waterVectors = waterMaskCleaned.reduceToVectors({
  geometry: regionOfInterest,
  scale: 30,
  geometryType: 'polygon',
  eightConnected: true,
  maxPixels: 1e10,
  reducer: ee.Reducer.countEvery()  // Count all water pixels
});

// Calculate area for each water body
var waterBodiesWithArea = waterVectors.map(function(feature) {
  // Calculate area in square meters with an error margin of 1 meter
  var area = feature.geometry().area(1);
  // Convert to square kilometers
  var areaKm2 = area.divide(1000000);
  return feature.set('area_km2', areaKm2);
});

// Filter water bodies larger than 10 sq km (10,000,000 sq meters)
var minLakeArea = 10000000; // 10 sq km in sq meters
var largeLakes = waterBodiesWithArea.filter(ee.Filter.gt('area_km2', 10));

// Count the number of large lakes
var largeCount = largeLakes.size();

// Create a Feature Collection of centroids for the lakes
var lakeCentroids = largeLakes.map(function(feature) {
  var centroid = feature.geometry().centroid(1); // 1 meter error margin
  return ee.Feature(centroid).set('area_km2', feature.get('area_km2'));
});

// Visualization parameters
