  palette: ['0000ff'],
  opacity: 0.8
};

var trueColorVis = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0,
  max: 0.3
};

// Add layers to the map
Map.centerObject(regionOfInterest, 8);
Map.addLayer(landsatScaled, trueColorVis, 'True Color Composite (Aug 2024)');
Map.addLayer(waterMaskCleaned, waterVis, 'Detected Water Bodies');
Map.addLayer(largeLakes, {color: 'cyan'}, 'Large Lakes (>10 sq km)');
Map.addLayer(lakeCentroids, {color: 'red', pointSize: 5}, 'Large Lake Centroids');
Map.addLayer(regionOfInterest, {color: 'yellow', fillColor: '00000000'}, '50km Radius Region');
Map.addLayer(centerPoint, {color: 'red', pointSize: 10}, 'Center Point');

// Print results
print('Question: Is there more than 2 lakes (size > 10 km²) in the Tibetan Plateau region?');
print('Number of large lakes detected (>10 km²):', largeCount);

// Evaluate the condition on the server side
largeLakes.size().gt(2).evaluate(function(result) {
  if (result) {
    print('Answer: YES, there are more than 2 lakes larger than 10 km² in the region.');
  } else {
    print('Answer: NO, there are 2 or fewer lakes larger than 10 km² in the region.');
  }
});

