// Count fire pixels per day for each month
var countFiresPerDay = function(startDate, endDate) {
  var dailyCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filter(ee.Filter.date(startDate, endDate))
    .filter(ee.Filter.bounds(thailand));

  return dailyCollection.map(function(image) {
    var fireMask = image.select('MaxFRP').gt(0);
    var dateMillis = image.get('system:time_start');
    var fireCount = fireMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: thailand,
      scale: 1000,
      maxPixels: 1e12
    }).get('MaxFRP');

    return ee.Feature(null, {
      'date': dateMillis,
      'fireCount': fireCount
    });
  });
};

