var studyArea = santaCruz.geometry().intersection(santaCruzEast);

// Function to mask clouds using the Landsat QA band
function maskL5Clouds(image) {
  var qa = image.select('QA_PIXEL');
  // Bits 3 and 5 are cloud shadow and cloud, respectively
  var cloudShadowBitMask = (1 << 3);
  var cloudsBitMask = (1 << 5);
  // Both flags should be set to zero, indicating clear conditions
  var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to calculate NDVI
function addNDVI(image) {
  var ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  return image.addBands(ndvi);
}

// Function to apply scale factors for surface reflectance
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Function to classify forest based on NDVI
function classifyForest(image) {
  // Consider pixels with NDVI > 0.5 as forest (adjust threshold if needed)
  var forestMask = image.select('NDVI').gt(0.5);
  return forestMask.rename('forest');
}

// Load Landsat 5 TM Collection 2 Tier 1 Surface Reflectance for 1986
var landsat1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
  .filterBounds(studyArea)
  .filterDate('1986-08-01', '1986-08-31')
  .map(maskL5Clouds)
  .map(applyScaleFactors);

// Load Landsat 5 TM Collection 2 Tier 1 Surface Reflectance for 2001
var landsat2001 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
  .filterBounds(studyArea)
  .filterDate('2001-08-01', '2001-08-31')
  .map(maskL5Clouds)
  .map(applyScaleFactors);

// Create cloud-free composites
var composite1986 = landsat1986.median();
var composite2001 = landsat2001.median();

// Calculate NDVI for both time periods
var ndvi1986 = composite1986.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
var ndvi2001 = composite2001.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');

// Classify forest (NDVI > 0.5)
var forest1986 = ndvi1986.gt(0.5).rename('forest');
var forest2001 = ndvi2001.gt(0.5).rename('forest');

// Calculate areas in square kilometers
var areaImage = ee.Image.pixelArea().divide(1000000); // convert to sq km

// Calculate forest area in 1986
var forestArea1986 = forest1986.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 30,
  maxPixels: 1e13
});

// Calculate forest area in 2001
var forestArea2001 = forest2001.multiply(areaImage).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 30,
  maxPixels: 1e13
});

// Calculate forest loss and percentage change
var forestArea1986Value = ee.Number(forestArea1986.get('forest'));
var forestArea2001Value = ee.Number(forestArea2001.get('forest'));
var forestLoss = forestArea1986Value.subtract(forestArea2001Value);
var percentDecrease = forestLoss.divide(forestArea1986Value).multiply(100);

// Determine if forest cover decreased
var hasDecreased = forestArea2001Value.lt(forestArea1986Value);

// Print results
