// Define ozone hole threshold (Dobson Units)
// The ozone hole is typically defined as regions with ozone concentration below 220 DU
var ozoneHoleThreshold = 220;

// Function to calculate ozone hole area for a specific dataset
function calculateOzoneHoleArea(dataset) {
  // Get the mean ozone concentration over the month
  var meanOzone = dataset.mean();

  // Create a binary mask where ozone is below the threshold
  var ozoneHoleMask = meanOzone.lt(ozoneHoleThreshold);

  // Calculate the area of the ozone hole in square kilometers
  var ozoneHoleArea = ozoneHoleMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: 25000,
    maxPixels: 1e12
  });

  return ozoneHoleArea.get('ozone');
}

