// Function to get the closest MODIS composite to a specific date
var getClosestImage = function(collection, date) {
  date = ee.Date(date);

  // Sort the collection by distance from the target date
  var closest = collection
    .map(function(image) {
      // Calculate difference in days between image date and target date
      var diff = ee.Number(date.difference(ee.Date(image.get('system:time_start')), 'day')).abs();
      return image.set('dateDiff', diff);
    })
    .sort('dateDiff')
    .first();

  return closest;
};

