// Define the date range
var startDate = '1984-09-17';
var endDate = '2009-06-02';

// Function to calculate NDVI for Landsat 5 imagery
function calculateNDVI(image) {
  // For Landsat 5, NDVI = (NIR - Red) / (NIR + Red)
  // NIR is band 4, Red is band 3
  var ndvi = image.normalizedDifference(['B4', 'B3']).rename('NDVI');
  return image.addBands(ndvi);
}

// Function to mask clouds in Landsat 5 imagery
function maskClouds(image) {
  // Use the QA band to create a mask for cloudy pixels
  var qa = image.select('QA_PIXEL');

  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  var cloudShadowBitMask = 1 << 3;
  var cloudsBitMask = 1 << 5;

  // Create a mask to remove cloud and cloud shadow pixels
  var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
              .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

  return image.updateMask(mask);
}

// Function to scale the surface reflectance values
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true)
              .copyProperties(image, ["system:time_start"]);
}

// Load Landsat 5 collection, filter by dates and location
var landsat5Collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
  .filterDate(startDate, endDate)
  .filterBounds(buffer)
  .map(applyScaleFactors)
  .map(function(image) {
    // Rename bands for clarity
    return image.select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7', 'QA_PIXEL'])
                .rename(['B1', 'B2', 'B3', 'B4', 'B5', 'B7', 'QA_PIXEL']);
  })
  .map(maskClouds)
  .map(calculateNDVI);

