// Function to calculate cloud/ash pixel count in a region
function calculatePlumePresence(image, region) {
  // Use brightness threshold in Band 1 to identify potential cloud/ash pixels
  // This is a simplistic approach - more sophisticated methods could be implemented
  var plume = image.select('sur_refl_b01').gt(2000);

  var pixelCount = plume.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e12
  });

  return pixelCount.get('sur_refl_b01');
}

