// Function to apply scale factors to Landsat 5 imagery
function applyScaleFactorsL5(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBand = image.select('ST_B6').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBand, null, true);
}

// Function to apply scale factors to Landsat 7 SR imagery
function applyScaleFactorsL7(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B6').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true);
}

// Function to mask clouds for Landsat 4-7
function maskL457Clouds(image) {
  var qa = image.select('QA_PIXEL');
  var cloudBitMask = 1 << 3;
  var shadowBitMask = 1 << 4;
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa.bitwiseAnd(shadowBitMask).eq(0));
  return image.updateMask(mask);
}

// Calculate indices for Landsat 5 TM
function addIndicesL5(image) {
  // NDBI = (SWIR1 - NIR) / (SWIR1 + NIR)
  var ndbi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');

  // NDVI = (NIR - Red) / (NIR + Red)
  var ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');

  // Urban Index (UI)
  var swir1 = image.select('SR_B5');
  var nir = image.select('SR_B4');
  var ui = swir1.subtract(nir).divide(swir1.add(nir)).rename('UI');

  return image.addBands([ndbi, ndvi, ui]);
}

// Function to create a built-up area mask using multiple indices
function createBuiltUpMask(image) {
  // Using NDBI > 0 AND NDVI < 0.2 to identify built-up areas
  var ndbiMask = image.select('NDBI').gt(0);
  var ndviMask = image.select('NDVI').lt(0.2);
  var uiMask = image.select('UI').gt(0);

  // Combine masks: Built-up = high NDBI + low NDVI + high UI
  return ndbiMask.and(ndviMask).and(uiMask);
}

// Function to calculate built-up area
function calculateBuiltUpArea(image, resolution) {
  var builtUpMask = createBuiltUpMask(image);
  var pixelArea = ee.Image.pixelArea();
  var builtUpArea = pixelArea.updateMask(builtUpMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: resolution,
    maxPixels: 1e12
  });

  var builtUpAreaSqMeters = builtUpArea.get('area');
  var builtUpAreaSqKm = ee.Number(builtUpAreaSqMeters).divide(1e6);

  return {
    sqMeters: builtUpAreaSqMeters,
    sqKm: builtUpAreaSqKm,
    mask: builtUpMask
  };
}

// Process Landsat 5 (1989) imagery
