]);

// Function to apply scale factors to Landsat 7 SR imagery
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBand = image.select('ST_B6').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBand, null, true);
}

// Function to calculate NDWI for Landsat 7
function addNDWI_L7(image) {
  var ndwi = image.normalizedDifference(['SR_B2', 'SR_B4']).rename('NDWI');
  return image.addBands(ndwi);
}

// Function to calculate NDWI for Landsat 1
function addNDWI_L1(image) {
  var ndwi = image.normalizedDifference(['B4', 'B6']).rename('NDWI');
  return image.addBands(ndwi);
}

// Function to calculate water area
function calculateWaterArea(image, resolution) {
  var waterMask = image.select('NDWI').gt(0);
  var pixelArea = ee.Image.pixelArea();
  var waterArea = pixelArea.updateMask(waterMask).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: resolution,
    maxPixels: 1e9
  });

  var waterAreaSqMeters = waterArea.get('area');
  var waterAreaSqKm = ee.Number(waterAreaSqMeters).divide(1e6);

  return {
    sqMeters: waterAreaSqMeters,
    sqKm: waterAreaSqKm,
    mask: waterMask
  };
}

