// Analysis of cloud cover over Lago Hermoso, Argentina
// Comparing March 29, 1987 vs February 15, 2001
// Using Google Earth Engine JavaScript API

// Define the Lago Hermoso region (approximate coordinates)
// Lago Hermoso is located in Neuquén Province, Argentina
var lagoHermoso = ee.Geometry.Polygon([
  // Approximate boundary of Lago Hermoso
  [[-71.50, -40.38], 
   [-71.45, -40.38], 
   [-71.45, -40.35], 
   [-71.50, -40.35]]
]);

// Create a function to analyze cloud cover for a specific date
function analyzeCloudCover(date) {
  // Format date strings for filtering
  var startDate = ee.Date(date);
  var endDate = startDate.advance(1, 'day');

  // Load Landsat data for the specified date
  // For 1987, we'll use Landsat 5
  // For 2001, we'll use Landsat 7
  var collection;

  if (startDate.millis().lt(ee.Date('2000-01-01').millis())) {
    // Before 2000 - use Landsat 5
    collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
      .filterDate(startDate, endDate)
      .filterBounds(lagoHermoso);
  } else {
    // 2000 and after - use Landsat 7
    collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_TOA')
      .filterDate(startDate, endDate)
      .filterBounds(lagoHermoso);
  }

  // If no images are available on the exact date, try to get the closest image
  // within a 10-day window
  var image = collection.first();
  if (image === null || image === undefined) {
    var relaxedStartDate = startDate.advance(-5, 'day');
    var relaxedEndDate = startDate.advance(5, 'day');

    if (startDate.millis().lt(ee.Date('2000-01-01').millis())) {
      collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA')
        .filterDate(relaxedStartDate, relaxedEndDate)
        .filterBounds(lagoHermoso);
    } else {
      collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_TOA')
        .filterDate(relaxedStartDate, relaxedEndDate)
        .filterBounds(lagoHermoso);
    }

    image = collection.sort('system:time_start', false).first();
  }

  // If still no image, return null
  if (image === null || image === undefined) {
    return null;
  }

  // Extract the actual capture date
  var captureDate = ee.Date(image.get('system:time_start'));

  // For water detection, use NDWI (Normalized Difference Water Index)
  var ndwi = image.normalizedDifference(['B2', 'B4']);  // Green and NIR bands
  var waterMask = ndwi.gt(0.1).clip(lagoHermoso);

  // Calculate lake area
  var lakeArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lagoHermoso,
    scale: 30,  // Landsat resolution
    maxPixels: 1e10
  });

  // Cloud detection based on the QA_PIXEL band for Collection 2
  // Bit 3 is for Cloud, Bit 1 is for Dilated Cloud
  var cloudBitMask = (1 << 3);
  var dilatedCloudBitMask = (1 << 1);

  // Consider a pixel cloudy if either the cloud bit or dilated cloud bit is set
  var cloudMask = image.select('QA_PIXEL')
    .bitwiseAnd(cloudBitMask).neq(0)
    .or(image.select('QA_PIXEL').bitwiseAnd(dilatedCloudBitMask).neq(0));

  // Calculate cloud coverage over the lake
  var cloudOverLake = cloudMask.updateMask(waterMask);
  var cloudArea = cloudOverLake.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lagoHermoso,
    scale: 30,
    maxPixels: 1e10
  });

  // Calculate cloud percentage
  var lakeAreaValue = ee.Number(lakeArea.get(lakeArea.keys().get(0)));
  var cloudAreaValue = ee.Number(cloudArea.get(cloudArea.keys().get(0)));
  var cloudPercentage = cloudAreaValue.divide(lakeAreaValue).multiply(100);

  return {
    'date': captureDate.format('YYYY-MM-dd'),
    'image': image,
    'waterMask': waterMask,
    'cloudMask': cloudMask,
    'cloudOverLake': cloudOverLake,
    'lakeArea': lakeAreaValue,
    'cloudArea': cloudAreaValue,
    'cloudPercentage': cloudPercentage
  };
}

// Analyze cloud cover for both dates
var result1987 = analyzeCloudCover('1987-03-29');
var result2001 = analyzeCloudCover('2001-02-15');

// Print results
if (result1987 !== null) {
  print('=== Cloud Coverage Analysis for 1987 ===');
  print('Date of Analysis:', result1987.date);
  print('Lake Area (sq m):', result1987.lakeArea);
  print('Cloud-Covered Lake Area (sq m):', result1987.cloudArea);
  print('Cloud Cover Percentage (%):', result1987.cloudPercentage);
} else {
  print('No image available for 1987 analysis period');
}

if (result2001 !== null) {
  print('=== Cloud Coverage Analysis for 2001 ===');
  print('Date of Analysis:', result2001.date);
  print('Lake Area (sq m):', result2001.lakeArea);
  print('Cloud-Covered Lake Area (sq m):', result2001.cloudArea);
  print('Cloud Cover Percentage (%):', result2001.cloudPercentage);
} else {
  print('No image available for 2001 analysis period');
}

// Compare the two dates
if (result1987 !== null && result2001 !== null) {
  var diff = result1987.cloudPercentage.subtract(result2001.cloudPercentage);
  print('=== Comparison ===');
  print('Difference in Cloud Cover (1987 - 2001, %)', diff);
  print('Is there more cloud cover in 1987 than 2001?', diff.gt(0));
}

