// Helper function to get MODIS data for a specific date with a small window (3 days)
function getMODISForDate(date) {
  var startDate = date.advance(-1, 'day');
  var endDate = date.advance(1, 'day');

  return ee.ImageCollection("MODIS/006/MOD09GA")
    .filterDate(startDate, endDate)
