// Function to calculate turbidity index using MODIS bands
// For MODIS, we'll use Red (band 1) and Green (band 4)
function calculateTurbidityIndex(image) {
  // Select Red (band 1) and Green (band 4) from MODIS
  // Scale the values by 0.0001 as per MODIS specifications
  var red = image.select('sur_refl_b01').multiply(0.0001);
  var green = image.select('sur_refl_b04').multiply(0.0001);

  // Calculate NDTI (Normalized Difference Turbidity Index)
  // NDTI = (Red - Green) / (Red + Green)
  var ndti = red.subtract(green).divide(red.add(green)).rename('ndti');

  return ndti;
}

// Calculate NDTI for both dates
var juneNDTI = calculateTurbidityIndex(juneImage);
var julyNDTI = calculateTurbidityIndex(julyImage);

// Function to calculate statistics for a region
function calculateStats(image, region, name) {
  var stats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.stdDev(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  });

  print(name + ' Statistics:', stats);
  return stats;
}

