// Function to calculate mean ozone concentration for a specific dataset over the Arctic
function calculateArcticOzoneMean(dataset) {
  // Get the mean ozone concentration over the month
  var meanOzone = dataset.mean();

  // Calculate the mean for western Arctic
  var arcticMean_west = meanOzone.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arctic_west,
    scale: 25000,
    maxPixels: 1e12
  }).get('ozone');

  // Calculate the mean for eastern Arctic
  var arcticMean_east = meanOzone.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arctic_east,
    scale: 25000,
    maxPixels: 1e12
  }).get('ozone');

  // Take the simple average of the two regions
  // This avoids using .area() which was causing problems
  var combined_mean = ee.Number(arcticMean_west).add(ee.Number(arcticMean_east)).divide(2);

  return combined_mean;
}

