// Function to mask clouds using the quality band (for Landsat 5)
function maskL5(image) {
  // Bit 0 - Fill
  // Bit 1 - Dilated Cloud
  // Bit 2 - Cirrus
  // Bit 3 - Cloud
  // Bit 4 - Cloud Shadow
  var qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);

  // Apply the scaling factors to the appropriate bands
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);

  // Replace the original bands with the scaled ones and apply the masks
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true)
    .updateMask(qaMask);
}

// Apply cloud mask to the collections
var period2004Masked = period2004.map(maskL5);
var period2009Masked = period2009.map(maskL5);

// Get median composites for more stable results
var composite2004 = period2004Masked.median();
var composite2009 = period2009Masked.median();

// Create water mask using NDWI (Normalized Difference Water Index)
function getWaterMask(image) {
  // For Landsat 5: Green is B2, NIR is B4
  var ndwi = image.normalizedDifference(['SR_B2', 'SR_B4']).rename('NDWI');
  return ndwi.gt(0.3); // Threshold for water detection
}

// Generate water masks
var waterMask2004 = getWaterMask(composite2004);
var waterMask2009 = getWaterMask(composite2009);

// Function to calculate surface reflectance statistics for lake area
function calculateSurfaceReflectance(image, waterMask, region, name) {
  // Calculate mean surface reflectance across visible bands (Blue, Green, Red)
  var blue = image.select('SR_B1');  // Blue band
  var green = image.select('SR_B2');  // Green band
  var red = image.select('SR_B3');   // Red band

  // Combine bands to get average visible reflectance
  var visibleReflectance = blue.add(green).add(red).divide(3).rename('visible_reflectance');

  // Apply water mask (only analyze lake pixels)
  var reflectanceWater = visibleReflectance.updateMask(waterMask);

  // Calculate statistics
  var stats = reflectanceWater.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 30,  // Landsat resolution
    maxPixels: 1e12
  });

  print(name + ' Mean Surface Reflectance:', stats.get('visible_reflectance'));
  return stats;
}

