// Function to calculate mean rainfall rate for a specific dataset
function calculateMeanRainfall(dataset, region) {
  // Get the mean precipitation over the year (mm/hr)
  var meanPrecip = dataset.mean();

  // Calculate the average precipitation in the region
  var meanRegionalPrecip = meanPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e12
  });

  return meanRegionalPrecip.get('precipitation');
}

