// Function to scale Landsat 8 surface reflectance values
function applyScaleFactors(image) {
  // Select bands and apply scale factors
  var opticalBands = image.select('SR_B.')
    .multiply(0.0000275).add(-0.2); // Scale factor for L8 surface reflectance

  var thermalBands = image.select('ST_B.*')
    .multiply(0.00341802).add(149.0); // Scale factor for thermal bands

  // Replace original bands with scaled ones
  return image.addBands(opticalBands, null, true)
              .addBands(thermalBands, null, true);
}

// Apply scale factors
