// Function to calculate ash plume presence in a region
function calculatePlumePresence(image, region) {
  // For Landsat 8, use aerosol band (B1) and brightness to identify ash
  // Ash tends to have high reflectance in the blue band and specific thermal signatures
  var plume = image.select('SR_B1').gt(0.1);

  var pixelCount = plume.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 30, // Landsat resolution is 30m
    maxPixels: 1e12
  });

  return pixelCount.get('SR_B1');
}

