// Function to get GRACE data for a specific time period
function getGraceData(startDate, endDate) {
  return ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND')
    .filterDate(startDate, endDate)
    .select(['lwe_thickness_csr'])  // Using CSR solution
    .mean();  // Get mean for the time period
}

// Get GRACE data for 2003 and 2013
var grace2003 = getGraceData(startDate2003, endDate2003);
var grace2013 = getGraceData(startDate2013, endDate2013);

// Calculate the difference between 2013 and 2003
// Negative values indicate groundwater depletion
var graceDifference = grace2013.subtract(grace2003);

// Get statistics for the region of interest
var stats = graceDifference.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: regionOfInterest,
  scale: 25000, // GRACE resolution is coarse (approximately 25 km)
  maxPixels: 1e9
});

