// Function to evaluate significance of change
graceDifference.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: regionOfInterest,
  scale: 25000
}).evaluate(function(result) {
  var change = result.lwe_thickness_csr;
  var message = '';

  if (change === null || change === undefined) {
    message = 'Unable to compute groundwater change - data may be unavailable for this region.';
  } else if (change < -3) {
    message = 'SIGNIFICANT DEPLETION: The analysis shows substantial groundwater loss in this region between 2003 and 2013.';
  } else if (change < -1) {
    message = 'MODERATE DEPLETION: The analysis shows moderate groundwater loss in this region between 2003 and 2013.';
  } else if (change < 1 && change > -1) {
    message = 'MINIMAL CHANGE: The analysis shows minimal change in groundwater in this region between 2003 and 2013.';
  } else if (change > 1 && change < 3) {
    message = 'MODERATE INCREASE: The analysis shows moderate groundwater increase in this region between 2003 and 2013.';
  } else {
    message = 'SIGNIFICANT INCREASE: The analysis shows substantial groundwater increase in this region between 2003 and 2013.';
  }

  print('CONCLUSION:', message);

  // Note about GRACE resolution limitations
  print('NOTE: GRACE has a coarse spatial resolution (approx. 300-400 km), so this analysis provides a regional trend rather than local details.');
});

