// Function to calculate mean soil moisture for a specific dataset at the station
function calculateStationSoilMoisture(dataset, stationGeometry) {
  // Get the mean soil moisture over the time period
  var meanSoilMoisture = dataset.mean();

  // Calculate the average soil moisture at the station
  var stationSoilMoisture = meanSoilMoisture.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: stationGeometry,
    scale: 25000,  // Scale in meters (25km for GLDAS data)
    maxPixels: 1e12
  });

  return stationSoilMoisture;
}

