// Analysis of cloud vs snow coverage for two specific regions
// Date: November 29, 2015
// Using Google Earth Engine (GEE) JavaScript API

// Define the two regions of interest using points and a buffer
var region1 = ee.Geometry.Point([-119.02882425044682, 46.929987337866386]).buffer(5000); // 5km buffer
var region2 = ee.Geometry.Point([-121.12721292232182, 44.504076930305435]).buffer(5000); // 5km buffer

// Create a feature collection for visualization purposes
var regions = ee.FeatureCollection([
  ee.Feature(region1, {name: 'Region 1'}),
  ee.Feature(region2, {name: 'Region 2'})
]);

// Load MODIS Terra data for November 29, 2015
// Using MOD09GA product which has 500m resolution and includes cloud state information
var modisImage = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2015-11-29', '2015-11-30'))
  .first();

// Load MODIS Terra snow cover product for the same date
var modisSnow = ee.ImageCollection('MODIS/061/MOD10A1')
  .filter(ee.Filter.date('2015-11-29', '2015-11-30'))
  .first();

// If MODIS/061/MOD10A1 doesn't have data, calculate NDSI ourselves
// NDSI = (Green - SWIR) / (Green + SWIR) = (Band 4 - Band 6) / (Band 4 + Band 6)
function calculateNDSI(image) {
  var green = image.select('sur_refl_b04'); // Green (band 4)
  var swir = image.select('sur_refl_b06');  // SWIR (band 6)

  // Calculate NDSI
  var ndsi = green.subtract(swir).divide(green.add(swir)).rename('NDSI');

  return ndsi;
}

var ndsiImage = calculateNDSI(modisImage);

// Function to extract cloud flag from MODIS QA band (bit 0-1)
function extractCloudMask(image) {
  var qa = image.select('state_1km');
  // Cloud state: 0=clear, 1=cloudy, 2=mixed, 3=not set, fill value
  var cloudState = qa.bitwiseAnd(3);  // 3 is binary 11, which gets the first two bits
  var cloudMask = cloudState.eq(1);   // 1 means cloudy
  return cloudMask;
}

// Get cloud mask
var cloudMask = extractCloudMask(modisImage);

// Define snow threshold based on NDSI
// NDSI > 0.4 is generally considered snow
var snowThreshold = 0.4;
var snowMask = ndsiImage.gt(snowThreshold);

// Function to analyze a region
function analyzeRegion(region, name) {
  // Calculate cloud percentage
  var cloudPercent = cloudMask.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  }).get('state_1km');

  // Calculate snow percentage using NDSI
  var snowPercent = snowMask.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 500,
    maxPixels: 1e12
  }).get('NDSI');

  // Get the average NDSI value
  var avgNDSI = ndsiImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 500,
    maxPixels: 1e12
  }).get('NDSI');

  // Determine if region is more likely cloud or snow
  // If cloudPercent > 0.5, we consider it mostly cloudy
  // If snowPercent > 0.5, we consider it mostly snow
  var isCloud = ee.Number(cloudPercent).gt(0.5);
  var isSnow = ee.Number(snowPercent).gt(0.5);

  // Print the results
  print(name + ' Analysis:');
  print('- Cloud coverage (%)', ee.Number(cloudPercent).multiply(100));
  print('- Snow coverage (NDSI > 0.4) (%)', ee.Number(snowPercent).multiply(100));
  print('- Average NDSI value', avgNDSI);
  print('- Is primarily cloud covered?', isCloud);
  print('- Is primarily snow covered?', isSnow);

  return ee.Feature(null, {
    'region': name,
    'cloud_percent': ee.Number(cloudPercent).multiply(100),
    'snow_percent': ee.Number(snowPercent).multiply(100),
    'avg_ndsi': avgNDSI,
    'is_cloud': isCloud,
    'is_snow': isSnow
  });
}

// Analyze both regions
var region1Analysis = analyzeRegion(region1, 'Region 1');
var region2Analysis = analyzeRegion(region2, 'Region 2');

// Combine analyses
var allAnalyses = ee.FeatureCollection([region1Analysis, region2Analysis]);

// Determine the answer to the question
var bothCloud = ee.Number(region1Analysis.get('is_cloud'))
  .and(ee.Number(region2Analysis.get('is_cloud')));
var eitherSnow = ee.Number(region1Analysis.get('is_snow'))
  .or(ee.Number(region2Analysis.get('is_snow')));

print('Answer to question:');
print('Are both regions covered by cloud?', bothCloud);
