// Define the location in Texas
var texasPoint = ee.Geometry.Point([-96.111167, 29.956182]);

// Create a 4km buffer around the point
var buffer = texasPoint.buffer(4000);

// Get the US States dataset and filter for Texas
var states = ee.FeatureCollection('TIGER/2018/States')
  .filter(ee.Filter.eq('NAME', 'Texas'));

// Load Landsat 8 imagery for the two dates
var before = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2013-05-04', '2013-05-05')
  .filterBounds(buffer)
  .mosaic();

var after = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2016-05-28', '2016-05-29')
  .filterBounds(buffer)
  .mosaic();

// Function to mask clouds using the quality band
function maskL8(image) {
  // Bit 0 - Fill
  // Bit 1 - Dilated Cloud
  // Bit 2 - Cirrus
  // Bit 3 - Cloud
  // Bit 4 - Cloud Shadow
  var qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);

  // Apply the scaling factors to the appropriate bands
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);

  // Replace the original bands with the scaled ones and apply the masks
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true)
    .updateMask(qaMask);
}

// Apply cloud mask
var beforeCloudMasked = maskL8(before);
var afterCloudMasked = maskL8(after);

// Calculate NDWI (Normalized Difference Water Index) for water detection
// Using Green (B3) and NIR (B5) bands
var ndwiBefore = beforeCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
var ndwiAfter = afterCloudMasked.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

// Apply threshold to identify water (NDWI > 0.1 typically indicates water)
var waterBefore = ndwiBefore.gt(0.1);
var waterAfter = ndwiAfter.gt(0.1);

// Calculate the intersection of the buffer with Texas state boundaries
var studyArea = buffer.intersection(states.geometry());

// Calculate water area for both dates within the study area
var areaBefore = waterBefore.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 30,
  maxPixels: 1e9
});

var areaAfter = waterAfter.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 30,
  maxPixels: 1e9
});

// Calculate the difference in water area
var waterAreaBefore = ee.Number(areaBefore.get('NDWI')).divide(1e6);
var waterAreaAfter = ee.Number(areaAfter.get('NDWI')).divide(1e6);
var difference = waterAreaAfter.subtract(waterAreaBefore);

// Print the water area in square kilometers
print('Water area on May 4, 2016 (sq km):', waterAreaBefore);
print('Water area on May 28, 2016 (sq km):', waterAreaAfter);
print('Difference (sq km):', difference);
print('Did inundation increase?', difference.gt(0));

// Create visualization parameters for water extent
var waterVisPalette = ['white', 'blue'];
var waterVis = {
  min: 0,
  max: 1,
  palette: waterVisPalette
};

// Create RGB visualization parameters for natural color imagery
var rgbVis = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0.0,
  max: 0.3
};

// Create a visualization for the change in water extent
var waterDifference = waterAfter.subtract(waterBefore);
var waterDiffVis = {
  min: -1,
  max: 1,
  palette: ['red', 'white', 'blue']  // red: loss, white: no change, blue: gain
};

// Center the map on the study area
Map.centerObject(studyArea, 12);

// Add layers to the map
Map.addLayer(states.style({color: 'gray', fillColor: '00000000'}), {}, 'Texas State Boundary');
Map.addLayer(buffer, {color: 'red'}, '4km Buffer');
Map.addLayer(beforeCloudMasked, rgbVis, 'Landsat 8 - May 4, 2016 (RGB)', false);
Map.addLayer(afterCloudMasked, rgbVis, 'Landsat 8 - May 28, 2016 (RGB)', false);
Map.addLayer(waterBefore, waterVis, 'Water Extent - May 4, 2016');
Map.addLayer(waterAfter, waterVis, 'Water Extent - May 28, 2016');
Map.addLayer(waterDifference, waterDiffVis, 'Water Change (Blue = Increase, Red = Decrease)');

// Define Lake Urmia location
var lakeUrmiaPoint = ee.Geometry.Point([45.4776, 37.7156]);

// Define Lake Urmia boundary (approximate)
var lakeUrmiaBoundary = lakeUrmiaPoint.buffer(30000);  // 30km buffer to cover the lake

// Define date ranges
var aprilDate = ee.Date('2016-04-23');
var julyDate = ee.Date('2016-07-18');

// Helper function to get MODIS data for a specific date with a wider window (5 days)
// to ensure we get data (sometimes there are gaps in daily coverage)
function getMODISForDate(date) {
  var startDate = date.advance(-2, 'day');
  var endDate = date.advance(2, 'day');
  return ee.ImageCollection("MODIS/061/MOD09GA")
    .filterDate(startDate, endDate)
    .filter(ee.Filter.bounds(lakeUrmiaBoundary))
    .sort('system:time_start')
    .mosaic();
}

// Get MODIS data for both dates
var aprilImage = getMODISForDate(aprilDate);
var julyImage = getMODISForDate(julyDate);

// Function to calculate redness index using MODIS bands
// We'll use a simple Red/Green ratio to calculate a redness index, 
// which is originally designed for anthocyanin;
function calculateRednessIndex(image) {
  // Select Red (band 1) and Green (band 4) from MODIS
  // Scale the values by 0.0001 as per MODIS specifications
  var red = image.select('sur_refl_b01').multiply(0.0001);
  var green = image.select('sur_refl_b04').multiply(0.0001);

  // Calculate the simple Red/Green ratio
  // Higher values indicate more redness
  var redGreenRatio = red.divide(green).rename('redness_ratio');

  return redGreenRatio;
}

// Calculate Redness Index for both dates
var aprilRedness = calculateRednessIndex(aprilImage);
var julyRedness = calculateRednessIndex(julyImage);

// Create a more reliable water mask using NDWI (Normalized Difference Water Index)
// For MODIS, we'll use NIR (band 2) and Green (band 4)
function getWaterMask(image) {
  var green = image.select('sur_refl_b04').multiply(0.0001);
  var nir = image.select('sur_refl_b02').multiply(0.0001);

  // Calculate NDWI = (Green - NIR) / (Green + NIR)
  var ndwi = green.subtract(nir).divide(green.add(nir));

  // Use a threshold to identify water (NDWI > 0.3)
  var waterMask = ndwi.gt(0.3);
  return waterMask;
}

// Get water masks for both dates
var aprilWaterMask = getWaterMask(aprilImage);
var julyWaterMask = getWaterMask(julyImage);

// Combine water masks to get area that is water in both images
var waterMask = aprilWaterMask.and(julyWaterMask);

// Apply water mask to redness indices
var aprilRednessWater = aprilRedness.updateMask(waterMask);
var julyRednessWater = julyRedness.updateMask(waterMask);

// Function to calculate statistics for the lake region
function calculateStats(image, region, name) {
  var stats = image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.stdDev(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  });
  print(name + ' Statistics:', stats);
  return stats;
}

// Calculate statistics for both dates (water areas only)
var aprilStats = calculateStats(aprilRednessWater, lakeUrmiaBoundary, 'April 23, 2016 Redness');
var julyStats = calculateStats(julyRednessWater, lakeUrmiaBoundary, 'July 18, 2016 Redness');

// Compare Redness Index values to determine if redness increased
var aprilRednessMean = ee.Number(aprilStats.get('redness_ratio_mean'));
var julyRednessMean = ee.Number(julyStats.get('redness_ratio_mean'));

// Calculate the difference and percent change
var rednessDifference = julyRednessMean.subtract(aprilRednessMean);
var percentChange = rednessDifference.divide(aprilRednessMean).multiply(100);

// Print results
print('April 23, 2016 Mean Redness Index:', aprilRednessMean);
print('July 18, 2016 Mean Redness Index:', julyRednessMean);
print('Redness Index Difference (July - April):', rednessDifference);
print('Percent Change in Redness Index:', percentChange);
print('Did redness increase?', julyRednessMean.gt(aprilRednessMean));

// Visualization for Redness Index (Red/Green ratio)
var rednessVis = {
