// Define Cambodia boundary
var cambodia = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
  .filter(ee.Filter.eq('country_na', 'Cambodia'));

// Load Hansen Global Forest Change dataset (v1.7)
var hansen = ee.Image("UMD/hansen/global_forest_change_2017_v1_5");

// Extract the layers we need
var treecover2000 = hansen.select('treecover2000');  // Forest cover in year 2000
var lossYear = hansen.select('lossyear');  // Year of forest loss (0 = no loss, 1-17 = 2001-2017)

// Create a binary forest loss mask for 2001-2014
// Values 1-14 represent loss years 2001-2014
var forestLoss = lossYear.gte(1).and(lossYear.lte(14));

// Calculate statistics for Cambodia
// First, get forest cover in 2000
var forestArea2000 = treecover2000.gt(30)  // Consider areas with >30% tree cover as forest
  .multiply(ee.Image.pixelArea())  // Convert to area (square meters)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 30,  // Hansen data is at 30m resolution
    maxPixels: 1e12
  });

// Calculate forest loss area between 2001-2014
var forestLossArea = forestLoss
  .multiply(treecover2000.gt(30))  // Only count loss in areas that were forest in 2000
  .multiply(ee.Image.pixelArea())  // Convert to area (square meters)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 30,
    maxPixels: 1e12
  });

// Calculate percentage of forest loss
var forestArea2000Value = ee.Number(forestArea2000.get('treecover2000'));
var forestLossValue = ee.Number(forestLossArea.get('lossyear'));
var percentLoss = forestLossValue.divide(forestArea2000Value).multiply(100);

// Print results
print('Cambodia Forest Area in 2000 (sq km):', forestArea2000Value.divide(1e6));  // Convert to sq km
print('Cambodia Forest Loss 2001-2014 (sq km):', forestLossValue.divide(1e6));  // Convert to sq km
print('Percentage of Forest Lost between 2001-2014:', percentLoss);
print('Does Cambodia have forest loss between 2001 and 2014?', forestLossValue.gt(0));

// Visualization parameters
var forestCoverVis = {
  min: 0,
  max: 100,
  palette: ['black', 'green']
};

var forestLossVis = {
  palette: ['red']
};

// Add layers to the map
Map.centerObject(cambodia, 7);
Map.addLayer(cambodia, {color: 'gray'}, 'Cambodia Boundary');
Map.addLayer(treecover2000.clip(cambodia), forestCoverVis, 'Forest Cover 2000');
Map.addLayer(forestLoss.clip(cambodia).selfMask(), forestLossVis, 'Forest Loss 2001-2014');

// Create visualization for loss by year
var lossYearVis = {
  min: 1,
  max: 14,
  palette: ['yellow', 'orange', 'red']
};

// Only show loss years 1-14 (2001-2014)
var lossYearMasked = lossYear.gte(1).and(lossYear.lte(14)).multiply(lossYear);
Map.addLayer(lossYearMasked.clip(cambodia).selfMask(), lossYearVis, 'Loss Year 2001-2014');

// Calculate annual forest loss
var annualLoss = ee.List.sequence(1, 14)
  .map(function(year) {
    var yearLoss = lossYear.eq(ee.Number(year))
      .multiply(treecover2000.gt(30))
      .multiply(ee.Image.pixelArea());

    var areaDict = yearLoss.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: cambodia,
      scale: 30,
      maxPixels: 1e12
    });

    return ee.Feature(null, {
      'year': ee.Number(year).add(2000),  // convert to actual year (2001-2014)
      'area': ee.Number(areaDict.get('lossyear')).divide(1e6)  // area in sq km
    });
  });

// Print annual loss data
print('Annual Forest Loss (sq km):', ee.FeatureCollection(annualLoss));

