// Function to calculate mean soil moisture for a specific dataset
function calculateMeanSoilMoisture(dataset, region) {
  // Get the mean soil moisture over the time period
  var meanSoilMoisture = dataset.mean();

  // Calculate the average soil moisture in the region
  var meanRegionalSoilMoisture = meanSoilMoisture.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 10000,  // Scale in meters (10km for SMAP data)
    maxPixels: 1e12
  });

  return meanRegionalSoilMoisture;
}

