// Load Landsat 8 Surface Reflectance data for July 19, 2017
var dataset = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
                  .filter(ee.Filter.date('2017-07-19', '2017-07-20'))
                  .filter(ee.Filter.bounds(ee.Geometry.Point([-136.275745, 69.264212])));


// Select the first image (if multiple are available)
var image = dataset.first();

// Apply scale and offset factors to convert to surface reflectance
// For Landsat 8 Collection 2, the scale factor is 0.0000275 and the offset is -0.2
function applyScaleAndOffset(image) {
  var opticalBands = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5']);
  var scaled = opticalBands.multiply(0.0000275).add(-0.2);

  return image.addBands(scaled, null, true);
}

var scaledImage = applyScaleAndOffset(image);

// Define the coordinates for the river plume and open ocean
var riverPlume = ee.Geometry.Point([-136.275745, 69.264212]);
var openOcean = ee.Geometry.Point([-137.786365, 69.803894]);

// Define a buffer around these points for analysis (2km radius)
var riverPlumeArea = riverPlume.buffer(2000);
var openOceanArea = openOcean.buffer(2000);

// Define a larger region for visualization
var studyRegion = ee.Geometry.Rectangle([-139, 68.5, -134, 70.5]);

// Calculate NDTI (Normalized Difference Turbidity Index)
// NDTI = (Red - Green) / (Red + Green)
var ndti = scaledImage.expression(
  '(red - green) / (red + green)', {
    'red': scaledImage.select('SR_B4'),
    'green': scaledImage.select('SR_B3')
  }).rename("nt");

// Function to calculate NDTI statistics for a region
function calculateNDTIStats(region, name) {
  var stats = ndti.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.stdDev(),
      sharedInputs: true
    }).combine({
      reducer2: ee.Reducer.min(),
      sharedInputs: true
    }).combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 30, // Landsat resolution
    maxPixels: 1e12
  });

  print('NDTI Statistics for ' + name + ':', stats);
  return stats.get('nt_mean');
}

// Calculate NDTI for both regions
