var oceanNDTI = calculateNDTIStats(openOceanArea, 'Beaufort Sea Open Ocean');

// Compare NDTI between the river plume and open ocean
print('Is River Plume more turbid than Open Ocean (based on NDTI)?', 
      ee.Number(plumeNDTI).gt(ee.Number(oceanNDTI)));
print('River Plume to Open Ocean NDTI Ratio:', 
      ee.Number(plumeNDTI).divide(ee.Number(oceanNDTI)));
print('NDTI Difference (Plume - Ocean):', 
      ee.Number(plumeNDTI).subtract(ee.Number(oceanNDTI)));

