// Define Afghanistan boundary
var afghanistan = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
  .filter(ee.Filter.eq('country_na', 'Afghanistan'));

// Load MODIS Land Surface Temperature dataset
var modisLST = ee.ImageCollection("MODIS/061/MOD11A2");

// Define the two periods to compare
var startDate2017 = ee.Date('2017-02-01');
var endDate2017 = ee.Date('2017-02-28');

var startDate2018 = ee.Date('2018-02-01');
var endDate2018 = ee.Date('2018-02-28');

// Select land surface temperature band
var lstBand = 'LST_Day_1km';

// Function to convert MODIS LST to Celsius
var convertToCelsius = function(image) {
  var lst = image.select(lstBand);
  // MODIS LST is stored as Kelvin * 0.02, so multiply by 0.02 to get Kelvin
  // then subtract 273.15 to convert to Celsius
  var lstCelsius = lst.multiply(0.02).subtract(273.15);
  return image.addBands(lstCelsius.rename('LST_Celsius'), null, true);
};

// Get LST data for February 2017
var lst2017 = modisLST
  .filter(ee.Filter.date(startDate2017, endDate2017))
  .map(convertToCelsius)
  .select('LST_Celsius')
  .mean();

// Get LST data for February 2018
var lst2018 = modisLST
  .filter(ee.Filter.date(startDate2018, endDate2018))
  .map(convertToCelsius)
  .select('LST_Celsius')
  .mean();

