// Function to calculate Red Green Ratio Index (RGRI)
function calculateRGRI(image) {
  // RGRI = Red / Green
  var rgri = image.select('SR_B4').divide(image.select('SR_B3')).rename('RGRI');
  return image.addBands(rgri);
}

// Function to mask clouds in Landsat 8 imagery
function maskClouds(image) {
  // Use the QA band to create a mask for cloudy pixels
  var qa = image.select('QA_PIXEL');

  // Bits 3 and 5 are cloud shadow and cloud, respectively.
  var cloudShadowBitMask = 1 << 3;
  var cloudsBitMask = 1 << 5;

  // Create a mask to remove cloud and cloud shadow pixels
  var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
              .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

  return image.updateMask(mask);
}

// Function to apply scale factors for Landsat 8 surface reflectance
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true)
              .copyProperties(image, ["system:time_start"]);
}

// Load Landsat 8 collection for the two specific dates
