  .filter(ee.Filter.date('2019-03-19', '2019-03-20'))
  .filterBounds(cities);

// Get single images from collections
var image2017 = march2017.first();
var image2019 = march2019.first();

// Function to calculate NDWI (Normalized Difference Water Index)
// Using Green and NIR bands for water detection
function calculateNDWI(image) {
  // For MODIS, band 4 is Green and band 2 is NIR
  var ndwi = image.normalizedDifference(['sur_refl_b04', 'sur_refl_b02']).rename('NDWI');
  return ndwi;
}

// Calculate NDWI for both dates
var ndwi2017 = calculateNDWI(image2017);
var ndwi2019 = calculateNDWI(image2019);

// Apply threshold to identify water (NDWI > 0.2 typically indicates water)
var water2017 = ndwi2017.gt(0.2);
var water2019 = ndwi2019.gt(0.2);

// Calculate water extent change
var waterChange = water2019.subtract(water2017);

// Calculate area for each city for both time periods
function calculateWaterAreaForCity(city, waterMask) {
  return waterMask.multiply(ee.Image.pixelArea()).divide(1000*1000) // Convert to km²
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: city.geometry(),
      scale: 500,  // MODIS resolution
      maxPixels: 1e9
    });
}

// Function to calculate areas for each city
function calculateCityWaterAreas(cities, water2017, water2019) {
  return cities.map(function(city) {
    var area2017 = calculateWaterAreaForCity(city, water2017);
    var area2019 = calculateWaterAreaForCity(city, water2019);

    var area2017Value = ee.Number(area2017.get('NDWI'));
    var area2019Value = ee.Number(area2019.get('NDWI'));

    // Calculate absolute and percent change
    var absoluteChange = area2019Value.subtract(area2017Value);
    var percentChange = absoluteChange.divide(area2017Value).multiply(100);

    return city.set({
      'water_area_2017': area2017Value,
      'water_area_2019': area2019Value,
      'absolute_change': absoluteChange,
      'percent_change': percentChange
    });
  });
}

// Calculate water areas for all cities
var citiesWithData = calculateCityWaterAreas(cities, water2017, water2019);

