// Set the location to Lake Sambhar, India
var sambharLake = ee.Geometry.Point([75.0904, 26.9239]);

// Define time periods for comparison
var dateBefore = ee.Date('2018-09-30');  // Around September 30, 2018
var dateAfter = ee.Date('2019-04-10');   // Around April 10, 2019

// Buffer dates to ensure image availability (5 days before and after)
var beforeStart = dateBefore.advance(-5, 'day');
var beforeEnd = dateBefore.advance(5, 'day');
var afterStart = dateAfter.advance(-5, 'day');
var afterEnd = dateAfter.advance(5, 'day');

// Load Landsat 8 Collection 2, Tier 1, Level 2 data
var collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');

// Function to apply scale factors to the images
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true);
}

// Get images for both time periods
var beforeImages = collection
  .filterDate(beforeStart, beforeEnd)
  .filterBounds(sambharLake)
  .map(applyScaleFactors);

var afterImages = collection
  .filterDate(afterStart, afterEnd)
  .filterBounds(sambharLake)
  .map(applyScaleFactors);

// Select the least cloudy image from each period
var beforeImage = beforeImages.sort('CLOUD_COVER').first();
var afterImage = afterImages.sort('CLOUD_COVER').first();

// Display natural color composite
