// Analysis of cloud cover changes in Western Australia
// Date: January 14, 2020
// Time: Between 11:00 and 14:00 local time
// Using Google Earth Engine (GEE) JavaScript API

// Define the point of interest in Western Australia
var westAustraliaPoint = ee.Geometry.Point([125.93, -20.59]);

// Create a small region (buffer) around the point for analysis
var regionOfInterest = westAustraliaPoint.buffer(50000); // 50km buffer

// Calculate the UTC times for 11:00 and 14:00 Western Australia time
// Western Australia Standard Time is UTC+8
// So 11:00 local = 03:00 UTC and 14:00 local = 06:00 UTC
var startTime = ee.Date('2020-01-14T03:00:00');
var endTime = ee.Date('2020-01-14T06:00:00');

// Load MODIS Aqua and Terra data for the time period
// Using MYD09GA (Aqua) and MOD09GA (Terra) products which include cloud state information
// MODIS Terra typically passes over in the morning, while Aqua passes in the afternoon
// This helps us get data closer to our target times

// Filter Terra collection (morning pass, closer to 11:00 local time)
var modisTerraCollection = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2020-01-14', '2020-01-15'))
  .filterBounds(regionOfInterest);

// Filter Aqua collection (afternoon pass, closer to 14:00 local time)
var modisAquaCollection = ee.ImageCollection('MODIS/061/MYD09GA')
  .filter(ee.Filter.date('2020-01-14', '2020-01-15'))
  .filterBounds(regionOfInterest);

// Get the Terra image closest to 11:00 local time
var morningImage = modisTerraCollection
  .sort('system:time_start')
  .first();

// Get the Aqua image closest to 14:00 local time
var afternoonImage = modisAquaCollection
  .sort('system:time_start')
  .first();

// Function to extract cloud flag from MODIS QC band (bit 0-1)
function extractCloudMask(image) {
  var qa = image.select('state_1km');
  // Cloud state: 0=clear, 1=cloudy, 2=mixed, 3=not set, fill value
  var cloudState = qa.bitwiseAnd(3);  // 3 is binary 11, which gets the first two bits
  var cloudMask = cloudState.eq(1).or(cloudState.eq(2));   // 1 means cloudy, 2 means mixed
  return cloudMask;
}

// Get cloud masks for morning and afternoon
var morningCloudMask = extractCloudMask(morningImage).unmask(0);
var afternoonCloudMask = extractCloudMask(afternoonImage).unmask(0);

// Calculate cloud cover percentage for morning and afternoon
var morningStats = morningCloudMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: regionOfInterest,
  scale: 5000, // MODIS resolution
  maxPixels: 1e12
});

var afternoonStats = afternoonCloudMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: regionOfInterest,
  scale: 5000,
  maxPixels: 1e12
});

// Calculate total area of the region
var totalArea = ee.Image.pixelArea().reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: regionOfInterest,
  scale: 5000,
  maxPixels: 1e12
});

// Calculate percentages
var morningCloudArea = ee.Number(morningStats.get('state_1km'));
var afternoonCloudArea = ee.Number(afternoonStats.get('state_1km'));
var totalRegionArea = ee.Number(totalArea.get('area'));

var morningCloudPercentage = morningCloudArea.divide(totalRegionArea).multiply(100);
var afternoonCloudPercentage = afternoonCloudArea.divide(totalRegionArea).multiply(100);
var cloudCoverChange = afternoonCloudPercentage.subtract(morningCloudPercentage);

// Get the actual timestamps of the images for reference
var morningTimestamp = ee.Date(morningImage.get('system:time_start')).format('YYYY-MM-dd HH:mm:ss');
var afternoonTimestamp = ee.Date(afternoonImage.get('system:time_start')).format('YYYY-MM-dd HH:mm:ss');

// Print results
print('Western Australia Cloud Cover Analysis - January 14, 2020');
print('Location:', westAustraliaPoint);
print('Morning image timestamp (UTC):', morningTimestamp);
print('Afternoon image timestamp (UTC):', afternoonTimestamp);
print('Morning cloud cover (%):', morningCloudPercentage);
print('Afternoon cloud cover (%):', afternoonCloudPercentage);
print('Change in cloud cover (percentage points):', cloudCoverChange);
print('Does cloud cover increase between 11:00 and 14:00?', cloudCoverChange.gt(0));

// Visualization parameters
