  min: 0,
  max: 1
};

// Center map on the point of interest
Map.centerObject(regionOfInterest, 8);

// Add layers to the map
Map.addLayer(morningImage, trueColorVisParams, 'Morning True Color (~11:00 local time)', true);
Map.addLayer(afternoonImage, trueColorVisParams, 'Afternoon True Color (~14:00 local time)', true);
Map.addLayer(morningCloudMask.selfMask(), cloudVisParams, 'Morning Clouds', true);
Map.addLayer(afternoonCloudMask.selfMask(), {palette: ['FF0000']}, 'Afternoon Clouds', true);
Map.addLayer(regionOfInterest, {color: 'yellow'}, 'Region of Interest');
Map.addLayer(westAustraliaPoint, {color: 'red'}, 'Target Location (-20.59, 125.93)');

