var fireHotspots2019 = ee.ImageCollection('MODIS/006/MOD14A1')
  .filterDate('2019-01-01', '2019-07-22')  // January through July 22, 2019
  .select('MaxFRP')  // Maximum Fire Radiative Power
  .filterBounds(paranaRiverDelta);

var fireHotspots2020 = ee.ImageCollection('MODIS/006/MOD14A1')
  .filterDate('2020-01-01', '2020-07-22')  // January through July 22, 2020
  .select('MaxFRP')
  .filterBounds(paranaRiverDelta);

// Create binary masks where fire hotspots are present (MaxFRP > 0)
var hotspots2019 = fireHotspots2019.map(function(image) {
  return image.gt(0);
}).sum().clip(paranaRiverDelta);

var hotspots2020 = fireHotspots2020.map(function(image) {
  return image.gt(0);
}).sum().clip(paranaRiverDelta);

// Set visualization parameters for the fire hotspots
