Map.addLayer(hotspots2020, hotspotVis, 'Paraná River Delta Hotspots 2020');
Map.addLayer(paranaRiverDelta, {color: 'blue'}, 'Paraná River Delta Region', true);

// Count the number of hotspots for both periods
var count2019 = hotspots2019.gt(0).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: paranaRiverDelta,
  scale: 1000,
  maxPixels: 1e9
});

var count2020 = hotspots2020.gt(0).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: paranaRiverDelta,
  scale: 1000,
  maxPixels: 1e9
});

// Extract the hotspot count values
