var hotspots2020_count = count2020.get('MaxFRP');

// Print hotspot count results to console
print('Paraná River Delta Fire Hotspots from Jan 1 to Jul 22, 2019:', hotspots2019_count);
print('Paraná River Delta Fire Hotspots from Jan 1 to Jul 22, 2020:', hotspots2020_count);

