var count_difference = ee.Number(hotspots2020_count).subtract(hotspots2019_count);
print('Difference in Fire Hotspot Count (2020 - 2019):', count_difference);

// Calculate percent change
var percent_change = ee.Number(hotspots2020_count).subtract(hotspots2019_count)
  .divide(hotspots2019_count).multiply(100);
print('Percent change in Fire Hotspot Count (2019 to 2020):', percent_change);

// Answer the research question
