  ee.Number(hotspots2020_count).gt(ee.Number(hotspots2019_count)),
  'Yes, the number of fire hotspots in the Paraná River delta from January through July 22, 2020, exceeds the number detected during the same period in 2019.',
  'No, the number of fire hotspots in the Paraná River delta from January through July 22, 2020, does not exceed the number detected during the same period in 2019.'
);

