// Create a chart comparing the fire hotspots between 2019 and 2020 by month
// First, create a function to get monthly hotspot counts
var getMonthlyHotspots = function(year) {
  var startDate = ee.Date.fromYMD(year, 1, 1);
  var endDate = ee.Date.fromYMD(year, 7, 22);

  var months = ee.List.sequence(1, 7);

  return months.map(function(month) {
    var start = ee.Date.fromYMD(year, month, 1);
    var end = ee.Algorithms.If(
      ee.Number(month).eq(7),
      ee.Date.fromYMD(year, month, 22),
      start.advance(1, 'month').advance(-1, 'day')
    );

    var collection = ee.ImageCollection('MODIS/006/MOD14A1')
      .filterDate(start, end)
      .select('MaxFRP')
      .filterBounds(paranaRiverDelta);

    var hotspots = collection.map(function(image) {
      return image.gt(0);
    }).sum().clip(paranaRiverDelta);

    var count = hotspots.gt(0).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: paranaRiverDelta,
      scale: 1000,
      maxPixels: 1e9
    }).get('MaxFRP');

    return ee.Feature(null, {
      'month': month,
      'year': year,
      'count': count
    });
  });
};

var hotspots2019_monthly = ee.FeatureCollection(getMonthlyHotspots(2019));
var hotspots2020_monthly = ee.FeatureCollection(getMonthlyHotspots(2020));

// Merge the collections for charting
var allHotspots = hotspots2019_monthly.merge(hotspots2020_monthly);

// Create the chart
var chart = ui.Chart.feature.groups(allHotspots, 'month', 'count', 'year')
  .setChartType('ColumnChart')
  .setOptions({
    title: 'Monthly Fire Hotspots in Paraná River Delta (Jan-Jul)',
    hAxis: {title: 'Month', gridlines: {count: 7}},
    vAxis: {title: 'Number of Fire Hotspots'},
    legend: {position: 'top'},
    series: {
      0: {color: 'blue'},
      1: {color: 'red'}
    }
  });

print(chart);

// Define the Etosha Pan region of interest
var etosha = ee.Geometry.Rectangle([15.8, -19.0, 17.2, -18.3]);

// Image collections for January and August 2020
var january_collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2020-01-10', '2020-01-20')
  .filterBounds(etosha);

var august_collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2020-08-25', '2020-09-02')
  .filterBounds(etosha);

// Apply scaling factors for proper visualization
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  var thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
    .addBands(thermalBands, null, true);
}

// Map scaling to both collections
var january_scaled = january_collection.map(applyScaleFactors);
var august_scaled = august_collection.map(applyScaleFactors);

// Get median images to reduce cloud influence
var january_image = january_scaled.median();
var august_image = august_scaled.median();

// Natural color visualization
var visParams = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0.02,
  max: 0.3,
};

// Add layers to map
Map.centerObject(etosha, 9);
Map.addLayer(january_image, visParams, 'January 2020');
Map.addLayer(august_image, visParams, 'August 2020');

// Calculate NDWI (Normalized Difference Water Index) for water detection
// NDWI = (Green - NIR) / (Green + NIR)
// For Landsat 8, Green is B3 and NIR is B5
var january_ndwi = january_image.normalizedDifference(['SR_B3', 'SR_B5']);
var august_ndwi = august_image.normalizedDifference(['SR_B3', 'SR_B5']);

// Visualization for NDWI
var ndwiParams = {
  min: -0.5,
  max: 0.5,
  palette: ['red', 'white', 'blue']
};

Map.addLayer(january_ndwi, ndwiParams, 'January 2020 NDWI');
Map.addLayer(august_ndwi, ndwiParams, 'August 2020 NDWI');

// Classify water (NDWI > 0.2 typically indicates water)
var january_water = january_ndwi.gt(0.2);
var august_water = august_ndwi.gt(0.2);

// Calculate areas
var january_water_area = january_water.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: etosha,
  scale: 30,
  maxPixels: 1e9
});

var august_water_area = august_water.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: etosha,
  scale: 30,
  maxPixels: 1e9
});

// Convert to square kilometers
var january_area_km2 = ee.Number(january_water_area.get('nd')).divide(1e6);
var august_area_km2 = ee.Number(august_water_area.get('nd')).divide(1e6);

// Calculate the difference and percentage change
var area_difference = january_area_km2.subtract(august_area_km2);
var percentage_change = area_difference.divide(january_area_km2).multiply(100);

// Print results
print('January 2020 water extent (km²):', january_area_km2);
print('August 2020 water extent (km²):', august_area_km2);
print('Difference (km²):', area_difference);
print('Percentage decrease:', percentage_change);

// Visualize water classification
Map.addLayer(january_water.selfMask(), {palette: ['0000FF']}, 'January 2020 Water');
Map.addLayer(august_water.selfMask(), {palette: ['00FFFF']}, 'August 2020 Water');


// Add a text answer to the console
if (area_difference.getInfo() > 0) {
  print('Yes, the surface water extent in Etosha Pan decreased from mid-January 2020 to late August 2020');
  print('The water surface area decreased by approximately ' + percentage_change.round().getInfo() + '%');
} else {
  print('No, the surface water extent in Etosha Pan did not decrease from mid-January 2020 to late August 2020');
}

