var leipzigArea = ee.Geometry.Rectangle([12.1, 51.1, 12.7, 51.5]);

// Import MODIS surface reflectance datasets
// Note: MODIS data only begins in 2000, so we'll use Landsat 5 for 1987
// For 1987 - using Landsat 5 TM 
