  .filterDate('1987-04-01', '1987-04-30')
  .filterBounds(leipzigArea);

// For 2020 - using MODIS Terra Surface Reflectance
var dataset_2020 = ee.ImageCollection('MODIS/006/MOD09A1')
  .filterDate('2020-04-01', '2020-04-30')
  .filterBounds(leipzigArea);

// Apply scaling factors to Landsat data
function applyScaleFactorsLandsat(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

var dataset_1987 = dataset_1987.map(applyScaleFactorsLandsat);

// Calculate median composites to reduce cloud interference
var composite_1987 = dataset_1987.median();
var composite_2020 = dataset_2020.median();

// Indices for water detection
// For Landsat 5 (1987)
var ndwi_1987 = composite_1987.normalizedDifference(['SR_B2', 'SR_B5']).rename('NDWI');

// For MODIS (2020)
// MODIS bands: 1 (red), 2 (NIR), 3 (blue), 4 (green), 5 (SWIR), 6 (SWIR), 7 (SWIR)
var ndwi_2020 = composite_2020.normalizedDifference(['sur_refl_b04', 'sur_refl_b06']).rename('NDWI');

// Define water threshold (typically NDWI > 0.3 indicates water)
var water_threshold = 0.3;
var water_1987 = ndwi_1987.gt(water_threshold);
var water_2020 = ndwi_2020.gt(water_threshold);

// Calculate the area of water bodies
var area_1987 = water_1987.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: leipzigArea,
  scale: 30, // Landsat resolution
  maxPixels: 1e9
});

var area_2020 = water_2020.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: leipzigArea,
  scale: 500, // MODIS resolution
  maxPixels: 1e9
});

// Calculate difference
var water_change = water_2020.subtract(water_1987);

// Visualization parameters for RGB composites
var visParams_L5 = {
  bands: ['SR_B3', 'SR_B2', 'SR_B1'],
  min: 0,
  max: 0.3,
};

