Map.addLayer(composite_2020, visParams_MODIS, 'MODIS 2020 RGB');

// Add water detection results
Map.addLayer(water_1987, waterVisParams, 'Water 1987');
Map.addLayer(water_2020, waterVisParams, 'Water 2020');
