// Define time periods for comparison
var sept2021 = ee.ImageCollection('MODIS/006/MOD09A1')
  .filter(ee.Filter.date('2021-09-01', '2021-09-30'));

var feb2022 = ee.ImageCollection('MODIS/006/MOD09A1')
  .filter(ee.Filter.date('2022-02-01', '2022-02-28'));

// Define GERD reservoir region (approximate coordinates)
var gerd = ee.Geometry.Point([35.09, 11.21]).buffer(20000);  // 20km buffer around GERD

// Function to calculate NDWI (Normalized Difference Water Index)
function addNDWI(image) {
  var ndwi = image.normalizedDifference(['sur_refl_b04', 'sur_refl_b06']).rename('NDWI');
  return image.addBands(ndwi);
}

// Add NDWI band to both collections
var sept2021WithNDWI = sept2021.map(addNDWI);
var feb2022WithNDWI = feb2022.map(addNDWI);

// Get median composites for more stable results
var sept2021Median = sept2021WithNDWI.median();
var feb2022Median = feb2022WithNDWI.median();

// Create water masks using NDWI threshold
// Values > 0.3 typically represent water
var waterThreshold = 0.3;
var sept2021Water = sept2021Median.select('NDWI').gt(waterThreshold);
var feb2022Water = feb2022Median.select('NDWI').gt(waterThreshold);

// Calculate water area for each period
var sept2021WaterArea = sept2021Water.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: gerd,
  scale: 500,  // MODIS resolution
  maxPixels: 1e9
});

var feb2022WaterArea = feb2022Water.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: gerd,
  scale: 500,
  maxPixels: 1e9
});

// Print results to console
print('September 2021 Water Area (sq m):', sept2021WaterArea.get('NDWI'));
print('February 2022 Water Area (sq m):', feb2022WaterArea.get('NDWI'));

// Calculate percent change
var sept2021Area = ee.Number(sept2021WaterArea.get('NDWI'));
var feb2022Area = ee.Number(feb2022WaterArea.get('NDWI'));
var percentChange = feb2022Area.subtract(sept2021Area).divide(sept2021Area).multiply(100);
print('Percent change in water area:', percentChange);

