// Create a function to get August AOD data for a specific year and apply scaling
function getAugustAOD(year) {
  // Convert the ee.Number to a string format for date filtering
  var yearStr = ee.Number(year).format();
  var startDate = ee.Date.fromYMD(year, 8, 1);
  var endDate = ee.Date.fromYMD(year, 8, 31);

  // Use MODIS Terra Aerosol Optical Depth data
  var aodData = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
                  .filter(ee.Filter.date(startDate, endDate))
                  .filter(ee.Filter.bounds(westernBrazil))
                  .select('Optical_Depth_047');

  // Apply the scaling factor of 0.001 to convert to actual AOD values
  return aodData.mean().multiply(0.001).set('year', year);
}

// Get AOD data for each August from 2002 to 2018
var years = ee.List.sequence(2002, 2018);
var augustAODCollection = ee.ImageCollection.fromImages(
  years.map(function(year) {
    return getAugustAOD(year);
  })
);

