  var meanAOD = yearImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westernBrazil,
    scale: 500000,
    maxPixels: 1e12
  });

  return ee.Feature(null, {
    'year': year,
    'mean_aod': meanAOD.get('Optical_Depth_047')
  });
});

