// Function to calculate fire statistics for a dataset
function calculateFireStats(dataset) {
  // Get the mean FRP over the time period
  var meanFRP = dataset.mean();

  // Calculate the mean value within the region
  var regionalMean = meanFRP.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laPalmaRegion,
    scale: 1000, // MODIS resolution
    maxPixels: 1e12
  });

  // Count fire pixels (where MaxFRP > 0)
  var fireCount = dataset.map(function(image) {
    return image.gt(0).selfMask();
  }).sum();

  var totalFirePixels = fireCount.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: laPalmaRegion,
    scale: 1000,
    maxPixels: 1e12
  });

  return {
    'meanFRP': regionalMean.get('MaxFRP'),
    'firePixelCount': totalFirePixels.get('MaxFRP')
  };
}

// Calculate the fire statistics for both periods
var statsEarly = calculateFireStats(frpEarly);
var statsLate = calculateFireStats(frpLate);

// Print the results
print('July 15-16, 2023 Fire Statistics:');
print('- Mean Fire Radiative Power (MW):', statsEarly.meanFRP);
print('- Fire Pixel Count:', statsEarly.firePixelCount);

