var frpPercentChange = frpChange.divide(statsEarly.meanFRP).multiply(100);

var countChange = ee.Number(statsLate.firePixelCount).subtract(statsEarly.firePixelCount);
var countPercentChange = countChange.divide(statsEarly.firePixelCount).multiply(100);

print('Fire Radiative Power Change (MW):', frpChange);
print('Fire Radiative Power Percentage Change (%):', frpPercentChange);
print('Fire Pixel Count Change:', countChange);
print('Fire Pixel Count Percentage Change (%):', countPercentChange);

