// Optional: Extract daily data to see day-by-day patterns
function getDailyFireData(startDate, endDate) {
  var dailyCollection = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(laPalmaRegion);

  return dailyCollection.map(function(image) {
    var fireMask = image.select('MaxFRP').gt(0);
    var dateMillis = image.get('system:time_start');
    var fireCount = fireMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: laPalmaRegion,
      scale: 1000,
      maxPixels: 1e12
    }).get('MaxFRP');

    return ee.Feature(null, {
      'date': dateMillis,
      'fireCount': fireCount
    });
  });
}

