// Function to calculate NDSI (Normalized Difference Snow Index)
var calculateNDSI = function(image) {
  var green = image.select('sur_refl_b04'); // Band 4 (Green)
  var swir = image.select('sur_refl_b06'); // Band 6 (SWIR)
  var ndsi = green.subtract(swir).divide(green.add(swir));
  return ndsi.rename('NDSI');
};

// Calculate NDSI for both dates
var ndsi_2021 = dataset_2021.map(calculateNDSI).mosaic().clip(tinguiriricaBasin);
var ndsi_2023 = dataset_2023.map(calculateNDSI).mosaic().clip(tinguiriricaBasin);

// Define NDSI threshold for snow detection
var ndsiThreshold = 0.4;

// Create snow masks
var snowMask_2021 = ndsi_2021.gte(ndsiThreshold);
var snowMask_2023 = ndsi_2023.gte(ndsiThreshold);

