// Function to calculate NDSI (Normalized Difference Snow Index)
var calculateNDSI = function(image) {
  var green = image.select('sur_refl_b04'); // Band 4 (Green)
  var swir = image.select('sur_refl_b06');  // Band 6 (SWIR)
  var ndsi = green.subtract(swir).divide(green.add(swir));
  return ndsi.rename('NDSI');
};

// Function to calculate snow cover area for a specific date
var calculateSnowCover = function(year) {
  // Create date range for December 18 of the specified year
  var startDate = year + '-12-18';
  var endDate = year + '-12-19';

  // Get MODIS data for the specified date
  var dataset = ee.ImageCollection('MODIS/061/MOD09GA')
    .filter(ee.Filter.date(startDate, endDate))
    .map(function(img) {
      return img.add(-100).multiply(0.0001);
    })
    .filterBounds(tinguiriricaBasin);

  // If no data is available, return null
  var datasetSize = dataset.size();
  var hasData = ee.Algorithms.If(datasetSize.gt(0), true, false);

  return ee.Algorithms.If(
    hasData,
    function() {
      // Calculate NDSI
      var ndsi = dataset.map(calculateNDSI).mosaic().clip(tinguiriricaBasin);

      // Define NDSI threshold for snow detection
      var ndsiThreshold = 0.4;

      // Create snow mask
      var snowMask = ndsi.gte(ndsiThreshold);

      // Calculate snow area (in pixels)
      var snowArea = snowMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: tinguiriricaBasin,
        scale: 500, // MODIS resolution
        maxPixels: 1e13
      }).get('NDSI');

      // Calculate the snow area in km²
      var pixelArea = 500 * 500 / 1000000; // area of one pixel in km²
      var snowAreaKm2 = ee.Number(snowArea).multiply(pixelArea);

      return ee.Feature(null, {
        'year': year,
        'date': startDate,
        'snow_pixels': snowArea,
        'snow_area_km2': snowAreaKm2
      });
    }(),
    ee.Feature(null, {
      'year': year,
      'date': startDate,
      'snow_pixels': 0,
      'snow_area_km2': 0,
      'note': 'No data available'
    })
  );
};

// Years to analyze (2016-2023)
