});

print(snowCoverChart);

// Visualize the basin area
Map.centerObject(tinguiriricaBasin, 10);
Map.addLayer(tinguiriricaBasin, {color: 'red'}, 'Tinguiririca Basin');

// Define the study areas: Bryce Canyon National Park and Las Vegas
var bryceCanyonNP = ee.Geometry.Point([-112.1827, 37.5930]).buffer(10000); // 10km buffer around Bryce Canyon NP
var lasVegas = ee.Geometry.Point([-115.1398, 36.1699]).buffer(15000); // 15km buffer around Las Vegas

// Load VIIRS nighttime light data for 2024 (using available months)
var viirs_2024 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
  .filterDate('2024-01-01', '2024-03-01') // using available 2024 data
  .select('avg_rad')
  .median();

// Clip the data to our regions of interest
var bryce_lights = viirs_2024.clip(bryceCanyonNP);
var vegas_lights = viirs_2024.clip(lasVegas);

// Set visualization parameters for the nighttime lights
var viirsVis = {
  min: 0,
  max: 60,  // Higher max value for Las Vegas which will have much brighter lights
  palette: ['black', 'navy', 'blue', 'aqua', 'yellow', 'white']
};

// Set map view to show both locations
Map.setCenter(-113.6613, 36.8815, 7); // Center point between the two locations

// Add the nighttime light layers
Map.addLayer(bryce_lights, viirsVis, 'Bryce Canyon Lights 2024');
Map.addLayer(vegas_lights, viirsVis, 'Las Vegas Lights 2024');
Map.addLayer(bryceCanyonNP, {color: 'green'}, 'Bryce Canyon National Park', true);
Map.addLayer(lasVegas, {color: 'red'}, 'Las Vegas', true);

// Calculate mean values for both locations
var bryce_mean = bryce_lights.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: bryceCanyonNP,
  scale: 500,
  maxPixels: 1e9
});

var vegas_mean = vegas_lights.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: lasVegas,
  scale: 500,
  maxPixels: 1e9
});

// Print mean results to console
print('Bryce Canyon Mean Nighttime Light 2024:', bryce_mean);
print('Las Vegas Mean Nighttime Light 2024:', vegas_mean);

// Extract the radiance values
var bryce_rad = bryce_mean.get('avg_rad');
var vegas_rad = vegas_mean.get('avg_rad');

// Calculate the ratio of Bryce Canyon to Las Vegas light intensity
var ratio = ee.Number(bryce_rad).divide(vegas_rad).multiply(100);
print('Bryce Canyon light intensity as percentage of Las Vegas:', ratio, '%');

// Calculate how many times brighter Las Vegas is compared to Bryce Canyon
var times_brighter = ee.Number(vegas_rad).divide(bryce_rad);
print('Las Vegas is approximately this many times brighter than Bryce Canyon:', times_brighter);

// Answer the research question
var comparison_result = ee.Algorithms.If(
  ee.Number(bryce_rad).lt(ee.Number(vegas_rad)),
  'Yes, the nighttime light intensity in Bryce Canyon National Park is lower compared to Las Vegas during 2024.',
  'No, the nighttime light intensity in Bryce Canyon National Park is not lower compared to Las Vegas during 2024.'
);

print('Answer to Research Question:', comparison_result);

// Define Amistad Reservoir region
var amistad = ee.Geometry.Rectangle([-101.35, 29.25, -100.85, 29.65]);

// Import Landsat 8 Collection 2 Tier 1 data
// August 2016 data
var august2016 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2016-08-01', '2016-08-31')
  .filterBounds(amistad)
  .filter(ee.Filter.lt('CLOUD_COVER', 20)); // Filter for low cloud cover

// August 2024 data
var august2024 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
  .filterDate('2023-08-01', '2023-08-31') // Note: Using 2023 as a proxy since knowledge cutoff is Oct 2024
  .filterBounds(amistad)
  .filter(ee.Filter.lt('CLOUD_COVER', 20)); // Filter for low cloud cover

// Function to apply scaling factors to Landsat 8 Surface Reflectance data
function applyScaleFactors(image) {
  var opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  return image.addBands(opticalBands, null, true);
}

// Apply scaling factors
var august2016_scaled = august2016.map(applyScaleFactors);
var august2024_scaled = august2024.map(applyScaleFactors);

// Create median composites for both periods to reduce cloud interference
var composite2016 = august2016_scaled.median();
var composite2024 = august2024_scaled.median();

// Function to calculate NDWI (Normalized Difference Water Index)
// For Landsat 8, using Green (B3) and NIR (B5) bands
function calculateNDWI(image) {
  return image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
}

// Calculate NDWI for both time periods
var ndwi2016 = calculateNDWI(composite2016);
var ndwi2024 = calculateNDWI(composite2024);

// Apply threshold to identify water (NDWI > 0.2 typically indicates water)
var waterThreshold = 0.2;
var water2016 = ndwi2016.gt(waterThreshold);
var water2024 = ndwi2024.gt(waterThreshold);

// Calculate water extent for both periods (in sq km)
var area2016 = water2016.multiply(ee.Image.pixelArea()).divide(1000*1000)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: amistad,
    scale: 30,  // Landsat 8 resolution
    maxPixels: 1e9
  });

var area2024 = water2024.multiply(ee.Image.pixelArea()).divide(1000*1000)
  .reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: amistad,
    scale: 30,
    maxPixels: 1e9
  });

// Calculate water change (2024 - 2016)
var waterChange = water2024.subtract(water2016);

// True color visualization parameters
var trueColorVis = {
  bands: ['SR_B4', 'SR_B3', 'SR_B2'],
  min: 0,
  max: 0.3
};

// NDWI visualization parameters
var ndwiVis = {
  min: -1,
  max: 1,
  palette: ['red', 'white', 'blue']
};

// Water visualization parameters
var waterVis = {
  palette: ['white', 'blue']
};

// Change visualization parameters
var changeVis = {
  palette: ['red', 'white', 'blue'] // Red: water loss, Blue: water gain
};

// Center map on Amistad Reservoir
Map.centerObject(amistad, 11);

// Add reservoir boundary
Map.addLayer(ee.Feature(amistad), {color: 'yellow'}, 'Amistad Reservoir Area');

// Add RGB composites
Map.addLayer(composite2016, trueColorVis, 'August 2016 - True Color');
Map.addLayer(composite2024, trueColorVis, 'August 2024 - True Color');

// Add NDWI layers
Map.addLayer(ndwi2016, ndwiVis, 'August 2016 - NDWI', false);
Map.addLayer(ndwi2024, ndwiVis, 'August 2024 - NDWI', false);

// Add water extent layers
Map.addLayer(water2016.selfMask(), waterVis, 'August 2016 - Water Extent');
Map.addLayer(water2024.selfMask(), waterVis, 'August 2024 - Water Extent');

// Add water change layer
Map.addLayer(waterChange, changeVis, 'Water Change (Blue: Gain, Red: Loss)');

// Print water areas to console
print('Amistad Reservoir Water Area - August 2016 (sq km):', area2016.get('NDWI'));
print('Amistad Reservoir Water Area - August 2024 (sq km):', area2024.get('NDWI'));

// Calculate and print difference
var area2016Value = ee.Number(area2016.get('NDWI'));
var area2024Value = ee.Number(area2024.get('NDWI'));
var areaDifference = area2024Value.subtract(area2016Value);
var percentChange = areaDifference.divide(area2016Value).multiply(100);

print('Absolute change in water area (sq km):', areaDifference);
print('Percent change in water area (%):', percentChange);

// Add a conclusive answer based on the calculation
print('Does water extent decrease?', 
      ee.Algorithms.If(areaDifference.lt(0), 
                      'Yes, water extent decreased from 2016 to 2024', 
                      'No, water extent did not decrease from 2016 to 2024'));

// Analysis of cloud cover in Amazon Rainforest
// Comparing land areas vs river areas on August 19, 2009
// Center point: -1.593993, -49.053062 (near Belém, Pará, Brazil)
// Define the study area: 100 km radius around the specified point
var centerPoint = ee.Geometry.Point([-49.053062, -1.593993]);
var studyArea = centerPoint.buffer(100000); // 100 km in meters
// Load MODIS Aqua data for August 19, 2009
// Using MYD09GA product which has 500m resolution and includes cloud state information
var modisImage = ee.ImageCollection('MODIS/061/MYD09GA')
  .filter(ee.Filter.date('2009-08-19', '2009-08-20'))
  .first();

// Load the JRC Global Surface Water dataset to identify river areas
var jrcWater = ee.Image('JRC/GSW1_3/GlobalSurfaceWater')
  .select('occurrence');
// Create a mask of the study area (all 1s inside, all 0s outside)
var studyAreaMask = ee.Image.constant(1).clip(studyArea);
// Create water mask (areas that are water >90% of the time)
// Force the mask to be binary (1 or 0) and clip to study area
var riverMask = jrcWater.gt(90).selfMask().unmask(0).clip(studyArea);
// Create land mask - ensure we're creating exactly the opposite of river within the study area
// Use unmask() to convert any masked pixels to 0, ensuring no NaN values
var landMask = riverMask.eq(0).and(studyAreaMask.eq(1)).selfMask().unmask(0).clip(studyArea);
// Function to extract cloud flag from MODIS QC band (bit 0-1)
function extractCloudMask(image) {
  var qa = image.select('state_1km');
  var cloudState = qa.bitwiseAnd(3);
  var cloudMask = cloudState.eq(1);
  return cloudMask;
}
// Get cloud mask
var cloudMask = extractCloudMask(modisImage).unmask(0);
function calculateCloudArea(mask, regionMask) {
  var intersection = mask.and(regionMask);
  return intersection.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: studyArea,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  }).get('state_1km');
}
// Calculate total areas of river and land
var riverArea = riverMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 500,
  maxPixels: 1e12
}).get('occurrence');
var landArea = landMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: studyArea,
  scale: 500,
  maxPixels: 1e12
}).get('occurrence');
// Calculate cloud cover over river and land areas
var cloudOverRiverArea = calculateCloudArea(cloudMask, riverMask);
var cloudOverLandArea = calculateCloudArea(cloudMask, landMask);
// For visualization, create filtered cloud masks
var cloudOverRiver = cloudMask.and(riverMask);
var cloudOverLand = cloudMask.and(landMask);
// Calculate percentages
var riverCloudPercentage = ee.Number(cloudOverRiverArea).divide(riverArea).multiply(100);
var landCloudPercentage = ee.Number(cloudOverLandArea).divide(landArea).multiply(100);
// Print results
print('Study Area (100km radius around point)', studyArea);
print('Total River Area (sq m):', riverArea);
print('Total Land Area (sq m):', landArea);
print('Cloud-covered River Area (sq m):', cloudOverRiverArea);
print('Cloud-covered Land Area (sq m):', cloudOverLandArea);
print('River Cloud Coverage (%)', riverCloudPercentage);
print('Land Cloud Coverage (%)', landCloudPercentage);
print('Is cloud cover greater over land than rivers?', 
      ee.Number(landCloudPercentage).gt(riverCloudPercentage));
// Visualization parameters
var visParams = {
  bands: ['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03'],
  min: 0,
  max: 3000
};
var landsatVisParams = {
  bands: ['B4', 'B3', 'B2'],
  min: 0,
  max: 0.3
};
var waterVisParams = {
  min: -1,
  max: 1,
  palette: ['white', 'blue']
};
var landVisParams = {
  min: -1,
  max: 1,
  palette: ['green', 'brown']  // Using different colors for land
};
var cloudVisParams = {
  palette: ['cyan']
};
// Center map on the study point
Map.centerObject(centerPoint, 8);
Map.addLayer(studyArea, {color: 'black'}, '100km Study Radius');
Map.addLayer(modisImage, visParams, 'MODIS Image', false);

Map.addLayer(studyAreaMask, {palette: ['yellow']}, 'Study Area Mask', false);
Map.addLayer(riverMask, waterVisParams, 'River Areas');
Map.addLayer(landMask, landVisParams, 'Land Areas');
Map.addLayer(cloudMask.selfMask(), cloudVisParams, 'All Cloud Cover');

Map.addLayer(cloudOverRiver, waterVisParams, 'Clouds over Rivers');
Map.addLayer(cloudOverLand, landVisParams, 'Clouds over Land');
Map.addLayer(centerPoint, {color: 'yellow'}, 'Center Point (-1.593993, -49.053062)');

// Define the study area: Bradwell Bay Wilderness in Apalachicola National Forest
var bradwellCenterPoint = ee.Geometry.Point([-84.5466, 30.1845]);
var bradwellRegion = bradwellCenterPoint.buffer(10000); // 10km radius to cover the wilderness area

// Define time periods for analysis
var earlyApril2004 = ee.DateRange('2004-04-01', '2004-04-10'); 
var lateApril2004 = ee.DateRange('2004-04-20', '2004-04-30');

// Load MODIS surface reflectance data (MOD09A1 - 8-day composite at 500m resolution)
var modisEarlyApril = ee.ImageCollection('MODIS/061/MOD09A1')
  .filterDate(earlyApril2004)
  .filterBounds(bradwellRegion)
  .first();

var modisLateApril = ee.ImageCollection('MODIS/061/MOD09A1')
  .filterDate(lateApril2004)
  .filterBounds(bradwellRegion)
  .first();

// Create NBR function for MODIS
// NBR = (NIR - SWIR) / (NIR + SWIR)
// For MODIS: Band 2 is NIR and Band 7 is SWIR
function calculateNBR(image) {
  var nir = image.select('sur_refl_b02'); // NIR band
  var swir = image.select('sur_refl_b07'); // SWIR band

  // Scale values if needed (MODIS is stored as integers)
  var scaledNIR = nir.float();
  var scaledSWIR = swir.float();

  // Calculate NBR
  var nbr = scaledNIR.subtract(scaledSWIR)
                     .divide(scaledNIR.add(scaledSWIR))
                     .rename('NBR');
  return nbr;
}

// Calculate NBR for both time periods
var nbrEarlyApril = calculateNBR(modisEarlyApril);
var nbrLateApril = calculateNBR(modisLateApril);

// Set NBR visualization
var nbrVis = {
  min: -0.5,
  max: 1,
  palette: ['red', 'yellow', 'green']
};

// Set map center to Bradwell Bay Wilderness
Map.centerObject(bradwellRegion, 12);

// Add the layers to the map
Map.addLayer(bradwellRegion, {color: 'blue'}, 'Bradwell Bay Wilderness Region', true);
Map.addLayer(nbrEarlyApril, nbrVis, 'NBR Early April 2004', true);
Map.addLayer(nbrLateApril, nbrVis, 'NBR Late April 2004', true);

// Calculate average NBR values for the entire region
var avgNbrEarlyApril = nbrEarlyApril.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: bradwellRegion,
  scale: 500, // MODIS resolution
  maxPixels: 1e9
});

var avgNbrLateApril = nbrLateApril.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: bradwellRegion,
  scale: 500, // MODIS resolution
  maxPixels: 1e9
});

// Extract the average NBR values
var earlyAprilAvgNbr = avgNbrEarlyApril.get('NBR');
var lateAprilAvgNbr = avgNbrLateApril.get('NBR');

// Print average NBR results to console
print('Average NBR in Bradwell Bay Wilderness (early April 2004):', earlyAprilAvgNbr);
print('Average NBR in Bradwell Bay Wilderness (late April 2004):', lateAprilAvgNbr);

// Calculate the difference in average NBR
var nbrDifference = ee.Number(lateAprilAvgNbr).subtract(earlyAprilAvgNbr);
print('Difference in Average NBR (Late April - Early April):', nbrDifference);

// Calculate percent change in NBR
var nbrPercentChange = ee.Number(lateAprilAvgNbr).subtract(earlyAprilAvgNbr)
  .divide(ee.Number(earlyAprilAvgNbr).abs()).multiply(100);
print('Percent change in Average NBR (Early April to Late April 2004):', nbrPercentChange);

// Interpret NBR change: lower NBR values indicate more burn (more negative = more severe burn)
// Therefore, if late April has lower NBR than early April, burn area likely increased
var comparisonResult = ee.Algorithms.If(
  ee.Number(lateAprilAvgNbr).lt(ee.Number(earlyAprilAvgNbr)),
  'Yes, the burn condition in Apalachicola National Forest\'s Bradwell Bay Wilderness appears to have increased between early April 2004 and late April 2004 (average NBR decreased).',
  'No, the burn condition in Apalachicola National Forest\'s Bradwell Bay Wilderness does not appear to have increased between early April 2004 and late April 2004 (average NBR did not decrease).'
);
print('Answer to Research Question:', comparisonResult);

// Create NBR difference image to visualize spatial patterns of change
var nbrDiff = nbrLateApril.subtract(nbrEarlyApril);

// Visualize NBR difference (negative values indicate more burning in late April)
var diffVis = {
  min: -0.3,
  max: 0.3,
  palette: ['red', 'white', 'green']  // Red = more burned in late April, Green = less burned
};

Map.addLayer(nbrDiff, diffVis, 'NBR Change (Late April - Early April)', true);

// Define the study area: Acre state in Brazil
var acreState = ee.FeatureCollection('FAO/GAUL/2015/level1')
  .filter(ee.Filter.eq('ADM1_NAME', 'Acre'));

// Define time periods for analysis
var lateJuly2005 = ee.DateRange('2005-07-20', '2005-07-31'); 
var lateSeptember2005 = ee.DateRange('2005-09-20', '2005-09-30');

// Load MODIS surface reflectance data (MOD09A1 - 8-day composite at 500m resolution)
var modisJuly = ee.ImageCollection('MODIS/061/MOD09A1')
  .filterDate(lateJuly2005)
  .filterBounds(acreState)
  .mosaic();

var modisSeptember = ee.ImageCollection('MODIS/061/MOD09A1')
  .filterDate(lateSeptember2005)
  .filterBounds(acreState)
  .mosaic();

// Create NBR function for MODIS
// NBR = (NIR - SWIR) / (NIR + SWIR)
// For MODIS: Band 2 is NIR and Band 7 is SWIR
function calculateNBR(image) {
  var nir = image.select('sur_refl_b02'); // NIR band
  var swir = image.select('sur_refl_b07'); // SWIR band

  // Scale values (MODIS is stored as integers)
  var scaledNIR = nir.float();
  var scaledSWIR = swir.float();

  // Calculate NBR
  var nbr = scaledNIR.subtract(scaledSWIR)
                     .divide(scaledNIR.add(scaledSWIR))
                     .rename('NBR');
  return nbr;
}

// Calculate NBR for both time periods
var nbrJuly = calculateNBR(modisJuly);
var nbrSeptember = calculateNBR(modisSeptember);

// Define NBR threshold for burned areas (typically NBR < -0.1 indicates burns)
// For tropical forests, this threshold might need adjustment
var burnThreshold = -0.1;

// Create binary masks where burn scars are present (NBR < threshold)
var julyBurnMask = nbrJuly.lt(burnThreshold);
var septemberBurnMask = nbrSeptember.lt(burnThreshold);

// Set visualization parameters for the burned areas
var burnedAreaVis = {
  min: 0,
  max: 1,
  palette: ['white', 'red']
};

// Set NBR visualization
var nbrVis = {
  min: -0.5,
  max: 1,
  palette: ['red', 'yellow', 'green']
};

// Set map center to Acre, Brazil
Map.centerObject(acreState, 8);

// Add the layers to the map
Map.addLayer(acreState, {color: 'blue'}, 'Acre State, Brazil', true);
Map.addLayer(nbrJuly, nbrVis, 'NBR July 2005', false);
Map.addLayer(nbrSeptember, nbrVis, 'NBR September 2005', false);
Map.addLayer(julyBurnMask, burnedAreaVis, 'July 2005 Burns', true);
Map.addLayer(septemberBurnMask, burnedAreaVis, 'September 2005 Burns', true);

// Calculate area of burn scars for both dates
var areaJuly = julyBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: acreState,
  scale: 500, // MODIS resolution
  maxPixels: 1e13  // Increased for larger area
});

var areaSeptember = septemberBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: acreState,
  scale: 500, // MODIS resolution
  maxPixels: 1e13  // Increased for larger area
});

// Extract the area values in square meters
var julyAreaSqm = areaJuly.get('NBR');
var septemberAreaSqm = areaSeptember.get('NBR');

// Convert to square kilometers for easier interpretation
var julyAreaSqkm = ee.Number(julyAreaSqm).divide(1000000);
var septemberAreaSqkm = ee.Number(septemberAreaSqm).divide(1000000);

// Print area results to console
print('Acre Burn Scar Area in late July 2005 (sq km):', julyAreaSqkm);
print('Acre Burn Scar Area in late September 2005 (sq km):', septemberAreaSqkm);

// Calculate the difference in burned area
var areaDifference = ee.Number(septemberAreaSqkm).subtract(julyAreaSqkm);
print('Difference in Burn Scar Area (September - July) in sq km:', areaDifference);

// Calculate percent change
var percentChange = ee.Number(septemberAreaSqkm).subtract(julyAreaSqkm)
  .divide(julyAreaSqkm).multiply(100);
print('Percent change in Burn Scar Area (July to September 2005):', percentChange);

// Answer the research question
var comparisonResult = ee.Algorithms.If(
  ee.Number(septemberAreaSqkm).gt(ee.Number(julyAreaSqkm)),
  'Yes, the burned area extent in Acre, Brazil increased in late September 2005 compared to late July 2005.',
  'No, the burned area extent in Acre, Brazil did not increase in late September 2005 compared to late July 2005.'
);
print('Answer to Research Question:', comparisonResult);

// Add a cloud mask visualization to help interpret results (optional)
// Cloud presence can affect NBR calculations
var julyClouds = modisJuly.select('StateQA').bitwiseAnd(1).eq(1);
var septemberClouds = modisSeptember.select('StateQA').bitwiseAnd(1).eq(1);

Map.addLayer(julyClouds, {min: 0, max: 1, palette: ['white', 'cyan']}, 'July Clouds', false);
Map.addLayer(septemberClouds, {min: 0, max: 1, palette: ['white', 'cyan']}, 'September Clouds', false);

// Define New York City boundary
var nyc = ee.FeatureCollection("TIGER/2018/Counties")
  .filter(ee.Filter.eq('STATEFP', '36'))  // New York State FIPS code is 36
  .filter(ee.Filter.or(
    ee.Filter.eq('NAME', 'Kings'),    // Brooklyn
    ee.Filter.eq('NAME', 'Queens'),
    ee.Filter.eq('NAME', 'New York'), // Manhattan
    ee.Filter.eq('NAME', 'Bronx'),
    ee.Filter.eq('NAME', 'Richmond')  // Staten Island
  ));
// Load MODIS Land Surface Temperature dataset
var modisLST = ee.ImageCollection("MODIS/061/MOD11A1");

// Load MODIS Vegetation Indices dataset for NDVI
var modisNDVI = ee.ImageCollection("MODIS/061/MOD13Q1");

// Load JRC Global Surface Water dataset for water masking
var water = ee.Image("JRC/GSW1_3/GlobalSurfaceWater").select('occurrence');

// Create water mask (pixels where water occurred more than 50% of the time)
var waterMask = water.gt(50);

// Define the date of interest (August 14, 2002)
var targetDate = ee.Date('2002-08-14');

// Get LST data for the target date
// MOD11A1 is daily, so we can filter precisely
var lstImage = modisLST
  .filter(ee.Filter.date(targetDate, targetDate.advance(2, 'day')))
  .median();

// Function to convert MODIS LST to Celsius
var convertToCelsius = function(image) {
  var lst = image.select('LST_Day_1km');
  var lstCelsius = lst.multiply(0.02).subtract(273.15);
  return lstCelsius.rename('LST_Celsius');
};

var lstLand = convertToCelsius(lstImage);

var ndviImage = modisNDVI
  .filter(ee.Filter.date(targetDate.advance(-8, 'day'), targetDate.advance(8, 'day')))
  .median();
var ndviLand = ndviImage.select('NDVI').multiply(0.0001); // Scale factor for NDVI is 0.0001

var lstVis = {
  min: 25,
  max: 45,
  palette: ['blue', 'green', 'yellow', 'orange', 'red']
};

var ndviVis = {
  min: 0,
  max: 0.8,
  palette: ['brown', 'yellow', 'lightgreen', 'green', 'darkgreen']
};

// Center the map on NYC
Map.centerObject(nyc, 10);

// Add NYC boundary
Map.addLayer(nyc, {color: 'black'}, 'NYC Boundary');

// Add layers to the map
Map.addLayer(lstLand.clip(nyc), lstVis, 'LST (°C) - Aug 14, 2002');
Map.addLayer(ndviLand.clip(nyc), ndviVis, 'NDVI - Aug 14, 2002');

// Correlation and regression analysis
// Sample points in NYC (land areas only)
var samples = lstLand.addBands(ndviLand).rename(['LST', 'NDVI']).sample({
  region: nyc, 
  scale: 1000,
  numPixels: 1000,
  geometries: true
});

// Calculate correlation between LST and NDVI
var correlation = samples.reduceColumns({
  reducer: ee.Reducer.pearsonsCorrelation(),
  selectors: ['LST', 'NDVI']
});

// Linear regression analysis
var linearRegression = samples.reduceColumns({
  reducer: ee.Reducer.linearRegression({
    numX: 1,
    numY: 1
  }),
