// Create NBR function for MODIS
// NBR = (NIR - SWIR) / (NIR + SWIR)
// For MODIS: Band 2 is NIR and Band 7 is SWIR
function calculateNBR(image) {
  var nir = image.select('sur_refl_b02'); // NIR band
  var swir = image.select('sur_refl_b07'); // SWIR band

  // Scale values if needed (MODIS is stored as integers)
  var scaledNIR = nir.float();
  var scaledSWIR = swir.float();

  // Calculate NBR
  var nbr = scaledNIR.subtract(scaledSWIR)
                     .divide(scaledNIR.add(scaledSWIR))
                     .rename('NBR');
  return nbr;
}

// Calculate NBR for both time periods
var nbrAugust = calculateNBR(modisAugust);
var nbrSeptember = calculateNBR(modisSeptember);

// Define NBR threshold for burned areas (typically NBR < -0.1 indicates burns)
// Adjust threshold based on local conditions if needed
var burnThreshold = -0.1;

// Create binary masks where burn scars are present (NBR < threshold)
var augustBurnMask = nbrAugust.lt(burnThreshold);
var septemberBurnMask = nbrSeptember.lt(burnThreshold);

// Set visualization parameters for the burned areas
