Map.addLayer(augustBurnMask, burnedAreaVis, 'August 2012 Burns', true);
Map.addLayer(septemberBurnMask, burnedAreaVis, 'September 2012 Burns', true);

// Calculate area of burn scars for both dates
var areaAugust = augustBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: pineCreekRegion,
  scale: 500, // MODIS resolution
  maxPixels: 1e9
});

var areaSeptember = septemberBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
