// Analysis of cloud cover over the Great Lakes
// Date: February 11, 2016
// Using Google Earth Engine (GEE) JavaScript API

// Define the Great Lakes region using a geometry collection
var greatLakes = ee.FeatureCollection([
  // Lake Superior
  ee.Feature(ee.Geometry.Polygon([
    [-89.5, 46.5], [-84.5, 46.5], [-84.5, 49.0], [-89.5, 49.0]
  ]), {name: 'Lake Superior'}),

  // Lake Michigan
  ee.Feature(ee.Geometry.Polygon([
    [-88.0, 41.5], [-85.0, 41.5], [-85.0, 46.0], [-88.0, 46.0]
  ]), {name: 'Lake Michigan'}),

  // Lake Huron
  ee.Feature(ee.Geometry.Polygon([
    [-84.0, 43.0], [-80.0, 43.0], [-80.0, 46.5], [-84.0, 46.5]
  ]), {name: 'Lake Huron'}),

  // Lake Erie
  ee.Feature(ee.Geometry.Polygon([
    [-83.5, 41.0], [-78.5, 41.0], [-78.5, 43.0], [-83.5, 43.0]
  ]), {name: 'Lake Erie'}),

  // Lake Ontario
  ee.Feature(ee.Geometry.Polygon([
    [-80.0, 43.0], [-76.0, 43.0], [-76.0, 44.5], [-80.0, 44.5]
  ]), {name: 'Lake Ontario'})
]);

// Create a single combined geometry for all lakes
var allLakesGeometry = greatLakes.geometry();

// Load MODIS Aqua data for February 11, 2016
// Using MYD09GA product which has 500m resolution and includes cloud state information
var modisImage = ee.ImageCollection('MODIS/061/MYD09GA')
  .filter(ee.Filter.date('2016-02-11', '2016-02-12'))
  .filterBounds(allLakesGeometry)
  .first();

// Load MODIS Terra data as a backup in case Aqua has issues
var modisTerraImage = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2016-02-11', '2016-02-12'))
  .filterBounds(allLakesGeometry)
  .first();

// Use Terra if Aqua is not available
var modisForAnalysis = ee.Algorithms.If(
  ee.Algorithms.IsEqual(modisImage, null),
  modisTerraImage,
  modisImage
);
modisForAnalysis = ee.Image(modisForAnalysis);

// Function to extract cloud flag from MODIS QC band (bit 0-1)
function extractCloudMask(image) {
  var qa = image.select('state_1km');
  // Cloud state: 0=clear, 1=cloudy, 2=mixed, 3=not set, fill value
  var cloudState = qa.bitwiseAnd(3);  // 3 is binary 11, which gets the first two bits
  var cloudMask = cloudState.eq(1);   // 1 means cloudy
  return cloudMask;
}

// Get cloud mask
var cloudMask = extractCloudMask(modisForAnalysis).unmask(0);

// Also get 'mixed' pixels which might be partially cloudy
var mixedMask = modisForAnalysis.select('state_1km').bitwiseAnd(3).eq(2).unmask(0);

// Combine definitely cloudy and mixed pixels
var possibleCloudMask = cloudMask.or(mixedMask);

// Load the JRC Global Surface Water dataset to help identify lake areas more accurately
var jrcWater = ee.Image('JRC/GSW1_3/GlobalSurfaceWater')
  .select('occurrence');

// Create water mask (areas that are water >90% of the time)
var waterMask = jrcWater.gt(90).clip(allLakesGeometry);

// Calculate cloud cover over each lake individually
var results = greatLakes.map(function(lake) {
  var lakeName = lake.get('name');
  var lakeGeom = lake.geometry();

  // Get the lake area by first making sure we're only counting water pixels
  // This helps with accuracy as our lake boundaries are approximate
  var lakeWaterMask = waterMask.clip(lakeGeom);

  // Calculate lake area, cloud area, and mixed area
  var lakeArea = lakeWaterMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeGeom,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  }).get('occurrence');

  var cloudArea = cloudMask.updateMask(lakeWaterMask)
    .multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeGeom,
      scale: 500,
      maxPixels: 1e12
    }).get('state_1km');

  var mixedArea = mixedMask.updateMask(lakeWaterMask)
    .multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeGeom,
      scale: 500,
      maxPixels: 1e12
    }).get('state_1km');

  // Calculate percentages
  var cloudPercentage = ee.Number(cloudArea).divide(lakeArea).multiply(100);
  var mixedPercentage = ee.Number(mixedArea).divide(lakeArea).multiply(100);
  var totalCloudPercentage = ee.Number(cloudArea).add(mixedArea).divide(lakeArea).multiply(100);

  // Return as a feature with properties
  return ee.Feature(null, {
    'Lake': lakeName,
    'Area_sqkm': ee.Number(lakeArea).divide(1e6),  // Convert to sq km
    'Cloud_Coverage_sqkm': ee.Number(cloudArea).divide(1e6),
    'Mixed_Coverage_sqkm': ee.Number(mixedArea).divide(1e6),
    'Cloud_Coverage_percent': cloudPercentage,
    'Mixed_Coverage_percent': mixedPercentage,
    'Total_Possible_Cloud_percent': totalCloudPercentage,
    'Has_Clouds': ee.Number(cloudArea).gt(0)
  });
});

// Calculate overall statistics for all Great Lakes
var totalLakeArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
  reducer: ee.Reducer.sum(),
  geometry: allLakesGeometry,
  scale: 500,
  maxPixels: 1e12
}).get('occurrence');

var totalCloudArea = cloudMask.updateMask(waterMask)
  .multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: allLakesGeometry,
    scale: 500,
    maxPixels: 1e12
  }).get('state_1km');

var totalMixedArea = mixedMask.updateMask(waterMask)
  .multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: allLakesGeometry,
    scale: 500,
    maxPixels: 1e12
  }).get('state_1km');

var overallCloudPercentage = ee.Number(totalCloudArea).divide(totalLakeArea).multiply(100);
var overallMixedPercentage = ee.Number(totalMixedArea).divide(totalLakeArea).multiply(100);
var overallTotalCloudPercentage = ee.Number(totalCloudArea).add(totalMixedArea)
  .divide(totalLakeArea).multiply(100);

// Print results
print('Date of Analysis: February 11, 2016');
print('Great Lakes Region', allLakesGeometry);
print('Individual Lake Cloud Statistics:', results);
print('Overall Cloud Coverage Statistics:');
print('Total Lakes Area (sq km):', ee.Number(totalLakeArea).divide(1e6));
print('Definite Cloud Coverage (sq km):', ee.Number(totalCloudArea).divide(1e6));
print('Mixed/Possible Cloud Coverage (sq km):', ee.Number(totalMixedArea).divide(1e6));
print('Definite Cloud Coverage (%)', overallCloudPercentage);
print('Mixed/Possible Cloud Coverage (%)', overallMixedPercentage);
print('Total Possible Cloud Coverage (%)', overallTotalCloudPercentage);
print('Are clouds present over the Great Lakes?', ee.Number(totalCloudArea).gt(0));

