// Define the area of interest: Asir region in Saudi Arabia
var asirRegion = ee.Geometry.Rectangle([41.0, 17.5, 44.5, 20.5]); // Approximate bounds for Asir region

// Date ranges for analysis
var baselineStartYear = 2003;
var baselineEndYear = 2011;
var comparisonStartYear = 2016;
var comparisonEndYear = 2017;

// Load MODIS Terra NDVI dataset (16-day composites)
var modisNDVI = ee.ImageCollection('MODIS/006/MOD13Q1')
  .filter(ee.Filter.bounds(asirRegion))
  .select('NDVI');

// Filter collections for baseline and comparison periods (May only)
var baselineCollection = modisNDVI
  .filter(ee.Filter.calendarRange(baselineStartYear, baselineEndYear, 'year'))
  .filter(ee.Filter.calendarRange(5, 5, 'month')); // May only

var comparisonCollection = modisNDVI
  .filter(ee.Filter.calendarRange(comparisonStartYear, comparisonEndYear, 'year'))
  .filter(ee.Filter.calendarRange(5, 5, 'month')); // May only

// Get baseline mean NDVI for May
var baselineMean = baselineCollection
  .mean()
  .multiply(0.0001)  // Scale factor for MODIS NDVI
  .clip(asirRegion);

// Get mean NDVI for May 2016-2017
var comparisonMean = comparisonCollection
  .mean()
  .multiply(0.0001)  // Scale factor for MODIS NDVI
  .clip(asirRegion);

// Calculate the difference: 2016-2017 minus baseline
var ndviDifference = comparisonMean.subtract(baselineMean);

// Visualization parameters
var ndviVis = {
  min: 0,
  max: 0.8,
  palette: ['brown', 'yellow', 'lightgreen', 'green', 'darkgreen']
};

var ndviDifferenceVis = {
  min: -0.2,
  max: 0.2,
  palette: ['red', 'white', 'green']
};

// Statistical analysis of NDVI values and change
var baselineStats = baselineMean.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: asirRegion,
  scale: 250,
  maxPixels: 1e9
});

var comparisonStats = comparisonMean.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: asirRegion,
  scale: 250,
  maxPixels: 1e9
});

var differenceStats = ndviDifference.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: asirRegion,
  scale: 250,
  maxPixels: 1e9
});

// Calculate percentage of area with significantly higher NDVI
var significantIncrease = ndviDifference.gt(0.05);  // Areas with NDVI increase > 0.05
var percentageIncreased = significantIncrease.reduceRegion({
  reducer: ee.Reducer.mean(),
  geometry: asirRegion,
  scale: 250,
  maxPixels: 1e9
}).get('NDVI');

// Determine if vegetation increased overall
var meanNDVIDifference = ee.Number(differenceStats.get('NDVI'));
var hasIncreased = meanNDVIDifference.gt(0);

// Center map on Asir region
Map.centerObject(asirRegion, 7);

// Add layers to the map
Map.addLayer(baselineMean, ndviVis, 'Baseline Mean NDVI (May 2003-2011)');
Map.addLayer(comparisonMean, ndviVis, 'Comparison Mean NDVI (May 2016-2017)');
Map.addLayer(ndviDifference, ndviDifferenceVis, 'NDVI Difference (2016-2017 minus Baseline)');
Map.addLayer(asirRegion, {color: 'blue', opacity: 0.3, fillColor: '00000000'}, 'Asir Region');
Map.addLayer(significantIncrease.selfMask(), {palette: ['darkgreen']}, 'Areas with Significant NDVI Increase');

// Print results
print('=== Asir Region NDVI Analysis ===');
print('Baseline Period:', baselineStartYear + '-' + baselineEndYear + ' (May)');
print('Comparison Period:', comparisonStartYear + '-' + comparisonEndYear + ' (May)');
print('Number of images in baseline collection:', baselineCollection.size());
print('Number of images in comparison collection:', comparisonCollection.size());
print('Mean NDVI in Baseline Period:', baselineStats.get('NDVI'));
print('Mean NDVI in Comparison Period:', comparisonStats.get('NDVI'));
print('Mean NDVI Difference:', meanNDVIDifference);
print('Does Asir show higher NDVI in May 2016-2017 compared to 2003-2011?', hasIncreased);
print('Percentage of area with significant NDVI increase (>0.05):', 
      ee.Number(percentageIncreased).multiply(100).format('%.2f'));

// Analysis of ice coverage over the Great Lakes
// Date: February 14, 2018
// Using Google Earth Engine (GEE) JavaScript API with MODIS/061/MYD10A1 snow/ice cover data

// Define the Great Lakes region using a feature collection
var greatLakes = ee.FeatureCollection([
  // Lake Superior
  ee.Feature(ee.Geometry.Polygon([
    [-92.0, 46.5], [-84.5, 46.5], [-84.5, 49.0], [-92.0, 49.0]
  ]), {name: 'Lake Superior'}),

