  ee.Feature(ee.Geometry.Polygon([
    [-88.0, 41.5], [-85.0, 41.5], [-85.0, 46.0], [-88.0, 46.0]
  ]), {name: 'Lake Michigan'}),

  // Lake Huron
  ee.Feature(ee.Geometry.Polygon([
    [-84.0, 43.0], [-80.0, 43.0], [-80.0, 46.5], [-84.0, 46.5]
  ]), {name: 'Lake Huron'}),

  // Lake Erie
  ee.Feature(ee.Geometry.Polygon([
    [-83.5, 41.0], [-78.5, 41.0], [-78.5, 43.0], [-83.5, 43.0]
  ]), {name: 'Lake Erie'}),

  // Lake Ontario
  ee.Feature(ee.Geometry.Polygon([
    [-80.0, 43.0], [-76.0, 43.0], [-76.0, 44.5], [-80.0, 44.5]
  ]), {name: 'Lake Ontario'})
]);

// Load the JRC Global Surface Water dataset to help identify lake areas more accurately
var jrcWater = ee.Image('JRC/GSW1_3/GlobalSurfaceWater')
  .select('occurrence');

// Create water mask (areas that are water >90% of the time)
var waterMask = jrcWater.gt(90);

// Load MODIS Aqua Snow Cover product for February 14, 2018 (MYD10A1)
var snowIceData = ee.ImageCollection('MODIS/061/MYD10A1')
  .filter(ee.Filter.date('2018-02-14', '2018-02-15'))
  .first();

// Get the NDSI_Snow_Cover band (shows snow and ice cover percentage)
var ndsiSnowCover = snowIceData.select('NDSI_Snow_Cover');

// Define a threshold for ice coverage (NDSI_Snow_Cover value)
// Values 0-100 represent percentage of pixel covered by snow/ice
var iceThreshold = 20; // Consider pixels with >20% as ice covered

// Create ice mask
var iceMask = ndsiSnowCover.gte(iceThreshold);

// Function to calculate statistics for each lake
var calculateLakeStats = function(lake) {
  var lakeName = lake.get('name');
  var lakeGeom = lake.geometry();

  // Clip water mask to individual lake
  var lakeWaterMask = waterMask.clip(lakeGeom);

  // Calculate total lake area (considering only water pixels)
  var lakeArea = lakeWaterMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeGeom,
    scale: 500, // MODIS resolution
    maxPixels: 1e12
  }).get('occurrence');

  // Calculate ice-covered area
  var iceArea = iceMask.updateMask(lakeWaterMask)
    .multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeGeom,
      scale: 500,
      maxPixels: 1e12
    }).get('NDSI_Snow_Cover');

  // Calculate percentage of ice coverage
  var icePercentage = ee.Number(iceArea).divide(lakeArea).multiply(100);

  // Return as a feature with properties
  return ee.Feature(null, {
    'Lake': lakeName,
    'Area_sqkm': ee.Number(lakeArea).divide(1e6),  // Convert to sq km
    'Ice_Coverage_sqkm': ee.Number(iceArea).divide(1e6),
    'Ice_Coverage_percent': icePercentage
  });
};

// Map the function over all lakes
var lakeStats = greatLakes.map(calculateLakeStats);

// Get Erie stats specifically
var erieStats = lakeStats.filter(ee.Filter.eq('Lake', 'Lake Erie')).first();

// Get other lakes stats
var otherLakesStats = lakeStats.filter(ee.Filter.neq('Lake', 'Lake Erie'));

// Calculate average ice coverage for other lakes
var otherLakesIceAvg = otherLakesStats.aggregate_mean('Ice_Coverage_percent');

// Compare Lake Erie to other lakes
var isErieMoreIcy = ee.Number(erieStats.get('Ice_Coverage_percent')).gt(otherLakesIceAvg);

// Print results
print('Date of Analysis: February 14, 2018 (MODIS Aqua afternoon pass)');
print('Lake Erie Ice Coverage (%):', erieStats.get('Ice_Coverage_percent'));
print('Average Ice Coverage for Other Great Lakes (%):', otherLakesIceAvg);
print('Lake Erie has more ice coverage than other Great Lakes (on average):', isErieMoreIcy);

// Visualization parameters for snow/ice cover
var snowCoverVis = {
  min: 0.0,
  max: 100.0,
  palette: ['black', '0dffff', '0524ff', 'ffffff'],
};

// Visualization for ice over lakes (masked to only show on lakes)
var lakeIceVis = {
  min: iceThreshold,
  max: 100.0,
  palette: ['cyan', 'blue', 'white'],
};

// Lake outline parameters
var lakeOutlineParams = {
  color: '0000FF',  // Blue for lake outlines
  width: 2
};

// Center map on the Great Lakes
Map.centerObject(greatLakes.geometry(), 5);

// Add layers to the map
Map.addLayer(ndsiSnowCover, snowCoverVis, 'MODIS Snow/Ice Cover', false);
Map.addLayer(ndsiSnowCover.updateMask(waterMask), lakeIceVis, 'Lake Ice Cover', true);
Map.addLayer(greatLakes, lakeOutlineParams, 'Great Lakes Outlines');

// Highlight Lake Erie
