  width: 3
};
Map.addLayer(greatLakes.filter(ee.Filter.eq('name', 'Lake Erie')), 
             erieOutlineParams, 'Lake Erie Highlighted');

// Analysis of urban-rural fog coverage differences in Delhi NCR region
// Comparing New Delhi (urban) with Modinagar and Greater Noida (rural areas)
// Date of analysis: January 30, 2014

// Define the regions of interest
var newDelhi = ee.Geometry.Rectangle([77.1, 28.5, 77.3, 28.7]); // New Delhi urban core
var modinagar = ee.Geometry.Rectangle([77.5, 28.8, 77.65, 29.0]); // Modinagar (rural)
var greaterNoida = ee.Geometry.Rectangle([77.4, 28.4, 77.6, 28.55]); // Greater Noida (rural)

// Create a feature collection for visualization purposes
var areas = ee.FeatureCollection([
  ee.Feature(newDelhi, {name: 'New Delhi'}),
  ee.Feature(modinagar, {name: 'Modinagar'}),
  ee.Feature(greaterNoida, {name: 'Greater Noida'})
]);

// Load MODIS Terra (morning) data for January 30, 2014
// Terra passes in the morning (~10:30 AM local time) when fog is likely still present
var terraMorning = ee.ImageCollection('MODIS/061/MOD21A1D')
  .filter(ee.Filter.date('2014-01-30', '2014-01-31'))
  .first();

// If MOD21A1D doesn't have data for this date, fallback to MOD09GA (surface reflectance product)
// which can be used to identify fog through its state flags
var modisReflectance = ee.ImageCollection('MODIS/061/MOD09GA')
  .filter(ee.Filter.date('2014-01-30', '2014-01-31'))
  .first();

// Function to extract cloud/fog information from the state QA band in MOD09GA
// MOD09GA has a 'state_1km' QA band where bits 0-1 indicate cloud state
function extractCloudInfo(image) {
  var stateQA = image.select('state_1km');
  // Extract bits 0-1 for cloud state
  var cloudState = stateQA.bitwiseAnd(3); // 3 = 0b11 (keeps first 2 bits)

  // In MOD09GA, cloud state values:
  // 0 = clear, 1 = cloudy, 2 = mixed, 3 = not set

  // For fog detection, we consider 'cloudy' pixels at low elevation as potential fog
  // This is a simplification; ideal fog detection would use additional data
  return cloudState;
}

// Extract cloud state information
var cloudState = extractCloudInfo(modisReflectance);

// Create a fog mask (assuming cloudy pixels in this winter morning are likely fog)
// Value 1 in cloudState indicates cloudy pixels
var fogMask = cloudState.eq(1);

// Calculate fog coverage percentage for each region
function calculateFogPercentage(fogMask, region) {
  // Count total pixels in region
  var totalPixels = fogMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000, // MODIS resolution
    maxPixels: 1e12
  }).get('state_1km');

  // Count fog-covered pixels
  var fogPixels = fogMask.eq(1).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e12
  }).get('state_1km');

  // Calculate percentage
  return ee.Number(fogPixels).divide(totalPixels).multiply(100);
}

// Calculate fog coverage for each region
var delhiFogPercentage = calculateFogPercentage(fogMask, newDelhi);
var modinagarFogPercentage = calculateFogPercentage(fogMask, modinagar);
var noidaFogPercentage = calculateFogPercentage(fogMask, greaterNoida);

// Print results
print('New Delhi Fog Coverage (%)', delhiFogPercentage);
print('Modinagar Fog Coverage (%)', modinagarFogPercentage);
print('Greater Noida Fog Coverage (%)', noidaFogPercentage);

// Calculate urban-rural differences
var delhiVsModinagar = ee.Number(delhiFogPercentage).subtract(modinagarFogPercentage);
var delhiVsNoida = ee.Number(delhiFogPercentage).subtract(noidaFogPercentage);
var averageRural = ee.Number(modinagarFogPercentage).add(noidaFogPercentage).divide(2);
var delhiVsRuralAvg = ee.Number(delhiFogPercentage).subtract(averageRural);

print('Fog Coverage Difference: Delhi vs Modinagar (%)', delhiVsModinagar);
print('Fog Coverage Difference: Delhi vs Greater Noida (%)', delhiVsNoida);
print('Fog Coverage Difference: Delhi vs Rural Average (%)', delhiVsRuralAvg);
print('Does Delhi have less fog than surrounding rural areas?', delhiVsRuralAvg.lt(0));

// Visualization
// Create a visualization of the fog mask
