// Define Cambodia region
var cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
                  .filter(ee.Filter.eq('country_na', 'Cambodia'));

// Define time periods for analysis
var february2018 = ee.DateRange('2018-02-01', '2018-02-28');
var august2017 = ee.DateRange('2017-08-01', '2017-08-31');

// Load MODIS Thermal Anomalies & Fire data for the two time periods
var dataset_feb = ee.ImageCollection('MODIS/006/MOD14A1')
                  .filter(ee.Filter.date(february2018))
                  .filter(ee.Filter.bounds(cambodia));

var dataset_aug = ee.ImageCollection('MODIS/006/MOD14A1')
                  .filter(ee.Filter.date(august2017))
                  .filter(ee.Filter.bounds(cambodia));

// Select the Maximum Fire Radiative Power band
var frp_feb = dataset_feb.select('MaxFRP');
var frp_aug = dataset_aug.select('MaxFRP');

// Create a visualization parameter for fire data
var fireVis = {
  min: 0,
  max: 500, // Adjust based on typical FRP range
  palette: ['black', 'blue', 'purple', 'cyan', 'green', 'yellow', 'red']
};

// Function to calculate fire statistics for a dataset
function calculateFireStats(dataset) {
  // Get the mean FRP over the time period
  var meanFRP = dataset.mean();

  // Calculate the mean value within the region
  var regionalMean = meanFRP.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cambodia,
    scale: 1000,
    maxPixels: 1e12
  });

  // Count fire pixels (where MaxFRP > 0)
  var fireCount = dataset.map(function(image) {
    return image.gt(0).selfMask();
  }).sum();

  var totalFirePixels = fireCount.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 1000,
    maxPixels: 1e12
  });

  return {
    'meanFRP': regionalMean.get('MaxFRP'),
    'firePixelCount': totalFirePixels.get('MaxFRP')
  };
}

// Calculate the fire statistics for both periods
var stats_feb = calculateFireStats(frp_feb);
var stats_aug = calculateFireStats(frp_aug);

// Print the results
print('February 2018 Fire Statistics:');
print('- Mean Fire Radiative Power (MW):', stats_feb.meanFRP);
print('- Fire Pixel Count:', stats_feb.firePixelCount);

print('August 2017 Fire Statistics:');
print('- Mean Fire Radiative Power (MW):', stats_aug.meanFRP);
print('- Fire Pixel Count:', stats_aug.firePixelCount);

// Calculate the percentage change
var frpChange = ee.Number(stats_aug.meanFRP).subtract(stats_feb.meanFRP);
var frpPercentChange = frpChange.divide(stats_feb.meanFRP).multiply(100);

var countChange = ee.Number(stats_aug.firePixelCount).subtract(stats_feb.firePixelCount);
var countPercentChange = countChange.divide(stats_feb.firePixelCount).multiply(100);

print('Fire Radiative Power Change (MW):', frpChange);
print('Fire Radiative Power Percentage Change (%):', frpPercentChange);
print('Fire Pixel Count Change:', countChange);
print('Fire Pixel Count Percentage Change (%):', countPercentChange);

// Answer the research question
print('Does Cambodia have more active fire detections in February 2018 compared to August 2017?', 
      ee.Number(stats_feb.firePixelCount).gt(stats_aug.firePixelCount));

